import { useQuery } from "@tanstack/react-query";

import query from "@/Utils/request/query";
import { AbdmConfig } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const DEFAULT_OTP_POLICY: AbdmConfig["otp"] = {
  length: 6,
  resend_wait_seconds: 60,
  max_resends: 2,
};

/**
 * Reads the deployment's ABDM configuration.
 *
 * Everything ABHA-related in the UI is gated on `enabled`. When the backend
 * has ABDM turned off, does not know the endpoint, or cannot be reached, the
 * hook reports `enabled: false` and CARE behaves exactly as it did before.
 */
export function useAbdmConfig() {
  const { data, isLoading } = useQuery({
    queryKey: ["abdm", "config"],
    queryFn: query(abdmApi.getConfig, { silent: true }),
    staleTime: 5 * 60 * 1000,
    retry: false,
  });

