import { FileCheck2Icon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { FactKey, FactProvenance } from "@/components/Abdm/types";

interface ProvenanceHintProps {
  provenance: FactProvenance;
  /** Which value was reused; words the "entered earlier" hint. */
  field?: FactKey;
  className?: string;
}

/**
 * A small marker telling the user where a prefilled value came from, so a
 * value is never reused silently ("never ask twice").
 */
export function ProvenanceHint({
  provenance,
  field,
  className,
}: ProvenanceHintProps) {
  const { t } = useTranslation();

  const label =
    provenance === "entered" && field
      ? t(`abdm_provenance__entered_${field}`)
      : t(`abdm_provenance__${provenance}`);

  return (
    <span
      data-slot="provenance-hint"
      className={cn(
        "inline-flex items-center gap-1 rounded-sm bg-primary-50 px-1.5 py-0.5 text-xs font-normal text-primary-800",
        className,
      )}
    >
      <FileCheck2Icon className="size-3" aria-hidden />
      {label}
    </span>
  );
}

import { AbhaExistingPatient, AbhaProfile } from "@/types/abdm/abdm";

/** Where a reused value came from; shown next to every prefilled field. */
export type FactProvenance = "entered" | "patient_record" | "abha";

export type FactKey = "aadhaar" | "mobile" | "abha_number" | "abha_address";

export interface Fact {
  value: string;
  provenance: FactProvenance;
}

/**
 * Values collected once in a flow and reused by later steps and fallback
 * paths ("never ask twice"). The Aadhaar fact is only recorded together with
 * the patient's consent, so its presence means consent was given.
 */
export type AbhaFacts = Partial<Record<FactKey, Fact>>;

export type RememberFact = (
  key: FactKey,
  value: string,
  provenance?: FactProvenance,
) => void;

export interface AbhaFlowResult {
  /** A verified (or enrolled) server-side transaction, usable for linking. */
  transactionId: string;
  profile: AbhaProfile;
  existingPatient: AbhaExistingPatient | null;
  /** Set when the ABHA came from the Aadhaar enrolment endpoints. */
  isNew?: boolean;
}

import { AlertCircleIcon, RotateCcwIcon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import {
  getAbdmErrorMessage,
  isAbdmErrorType,
  RESTART_ERROR_TYPES,
} from "@/components/Abdm/utils";

interface AbdmErrorAlertProps {
  error: unknown;
  /** Offered when the transaction can no longer continue (e.g. it expired). */
  onRestart?: () => void;
  className?: string;
}

/** Renders an ABDM error inline on the step in view. */
export function AbdmErrorAlert({
  error,
  onRestart,
  className,
}: AbdmErrorAlertProps) {
  const { t } = useTranslation();

  if (!error) {
    return null;
  }

  const { title, description } = getAbdmErrorMessage(t, error);
  const canRestart =
    !!onRestart && isAbdmErrorType(error, ...RESTART_ERROR_TYPES);

  return (
    <Alert
      variant="destructive"
      className={cn("border-red-200 bg-red-50", className)}
      data-testid="abdm-error"
    >
      <AlertCircleIcon />
      <AlertTitle className="line-clamp-none">{title}</AlertTitle>
      {(description || canRestart) && (
        <AlertDescription>
          {description && <p>{description}</p>}
          {canRestart && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="mt-1"
              onClick={onRestart}
            >
              <RotateCcwIcon />
              {t("abdm_start_again")}
            </Button>
          )}
        </AlertDescription>
      )}
    </Alert>
  );
}

