import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { ProvenanceHint } from "@/components/Abdm/ProvenanceHint";
import { FactProvenance } from "@/components/Abdm/types";
import { maskAadhaar, normalizeAadhaar } from "@/components/Abdm/utils";

interface AadhaarConsentInputProps {
  value: string;
  onChange: (value: string) => void;
  consented: boolean;
  onConsentChange: (consented: boolean) => void;
  /** The exact consent text served by the backend (`config.consent.text`). */
  consentText: string;
  error?: string;
  /** Set while the value is reused from an earlier step. */
  provenance?: FactProvenance;
  autoFocus?: boolean;
  disabled?: boolean;
}

/**
 * Aadhaar number input with the mandatory ABDM consent shown verbatim above an
 * "I agree" checkbox. The number is masked to its last 4 digits whenever the
 * field is not being edited, and is never echoed back in full.
 */
export function AadhaarConsentInput({
  value,
  onChange,
  consented,
  onConsentChange,
  consentText,
  error,
  provenance,
  autoFocus,
  disabled,
}: AadhaarConsentInputProps) {
  const { t } = useTranslation();
  const id = useId();
  const [isEditing, setIsEditing] = useState(false);

  const displayValue =
    !isEditing && value.length === 12 ? maskAadhaar(value) : value;

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-col gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <Label htmlFor={`${id}-aadhaar`} aria-required>
            {t("aadhaar_number")}
          </Label>
          {provenance && (
            <ProvenanceHint provenance={provenance} field="aadhaar" />
          )}
        </div>
        <Input
          id={`${id}-aadhaar`}
          data-testid="abdm-aadhaar-input"
          inputMode="numeric"
          autoComplete="off"
          spellCheck={false}
          placeholder={t("abdm_aadhaar_placeholder")}
          value={displayValue}
          autoFocus={autoFocus}
          disabled={disabled}
          aria-invalid={!!error}
          aria-describedby={`${id}-aadhaar-help`}
          onFocus={() => setIsEditing(true)}
          onBlur={() => setIsEditing(false)}
          onChange={(e) => onChange(normalizeAadhaar(e.target.value))}
        />
        <p id={`${id}-aadhaar-help`} className="text-xs text-gray-500">
          {t("aadhaar_number_will_not_be_stored")}
        </p>
        {error && (
          <p className="text-sm text-red-500" role="alert">
            {error}
          </p>
        )}
      </div>

      <div className="flex flex-col gap-2 rounded-md border border-gray-200 bg-gray-50 p-3">
        <p className="text-sm font-semibold text-gray-900">
          {t("abdm_consent_title")}
        </p>
        <div
          className="max-h-48 overflow-y-auto whitespace-pre-line text-xs leading-relaxed text-gray-700"
          tabIndex={0}
          data-testid="abdm-consent-text"
        >
          {consentText}
        </div>
        <div className="flex items-start gap-2 pt-1">
          <Checkbox
            id={`${id}-consent`}
            data-testid="abdm-consent-checkbox"
            checked={consented}
            disabled={disabled}
            onCheckedChange={(checked) => onConsentChange(checked === true)}
          />
          <Label
            htmlFor={`${id}-consent`}
            className="text-sm font-medium leading-snug"
          >
            {t("abdm_consent_agree")}
          </Label>
        </div>
      </div>
    </div>
  );
}

