  otpSent,
  onOtpSentChange,
  otpLength,
  value,
  onChange,
  disabled,
  onRestart,
}: AbhaOtpInputProps) {
  const { t } = useTranslation();
  const id = useId();

  const [resendAt, setResendAt] = useState(
    () => Date.now() + otpSent.resend.available_in_seconds * 1000,
  );
  const [remaining, setRemaining] = useState(otpSent.resend.remaining);
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    setResendAt(Date.now() + otpSent.resend.available_in_seconds * 1000);
