        {remaining > 0 ? (
          <>
            <Button
              type="button"
              variant="outline"
              size="sm"
              data-testid="abdm-resend-otp"
              disabled={secondsLeft > 0 || resendMutation.isPending || disabled}
              onClick={() =>
                resendMutation.mutate({
                  transaction_id: otpSent.transaction_id,
                })
              }
            >
              <RotateCwIcon />
              {secondsLeft > 0
                ? t("abdm_resend_otp_in", { seconds: secondsLeft })
                : t("abdm_resend_otp")}
            </Button>
            <span className="text-xs text-gray-500" aria-live="polite">
              {t("abdm_resends_left", { count: remaining })}
            </span>
          </>
        ) : (
          <span className="text-xs text-gray-500" aria-live="polite">
            {t("abdm_no_resends_left")}
          </span>
        )}
      </div>

      {resendMutation.error &&
        getAbdmError(resendMutation.error)?.type !== "resend_too_soon" && (
          <AbdmErrorAlert
            error={resendMutation.error}
            onRestart={onRestart}
          />
        )}
    </div>
  );
}

