/**
 * Types for ABDM Milestone 1 (ABHA creation and verification).
 *
 * The browser never talks to ABDM directly: CARE's backend keeps every ABDM
 * token server-side and hands the frontend an opaque `transaction_id` per
 * flow. All shapes mirror the contract served under `/api/v1/abdm/`.
 */

export type AbhaIdentifierType =
  | "mobile"
  | "aadhaar"
  | "abha_number"
  | "abha_address";

/** `aadhaar` = OTP to the Aadhaar-linked mobile, `abdm` = OTP to the ABHA mobile. */
export type AbhaOtpSystem = "aadhaar" | "abdm";

export type AbhaGender = "male" | "female" | "transgender" | "non_binary";

export interface AbdmConsentText {
  code: string;
  version: string;
  text: string;
}

export interface AbdmOtpPolicy {
  length: number;
  resend_wait_seconds: number;
  max_resends: number;
}

export interface AbdmConfig {
  enabled: boolean;
  cm_id: string;
  /** e.g. "@sbx"; appended by the backend when an ABHA address omits it. */
  abha_address_suffix: string;
  consent: AbdmConsentText;
  otp: AbdmOtpPolicy;
}

export interface AbhaConsentAgreement {
  agreed: true;
  version: string;
}

export interface AbhaProfile {
  /** Hyphenated, e.g. "91-1234-5678-9012". */
  abha_number: string | null;
  /** Preferred ABHA address, e.g. "john.doe@sbx". */
  abha_address: string | null;
  abha_addresses: string[];
  name: string;
  first_name: string | null;
  middle_name: string | null;
  last_name: string | null;
  /** Mapped to CARE's gender vocabulary. */
  gender: AbhaGender | null;
  /** Raw ABDM gender code: "M" | "F" | "O" | "T" | "D" | "U". */
  abdm_gender: string | null;
  /** "YYYY-MM-DD" when the full date of birth is known. */
  date_of_birth: string | null;
  year_of_birth: number | null;
  /** 10 digits, without a country code. */
  mobile: string | null;
  email: string | null;
  address: string | null;
  pincode: string | null;
  state_name: string | null;
  state_code: string | null;
  district_name: string | null;
  district_code: string | null;
  kyc_verified: boolean;
  status: string | null;
  /** Base64 JPEG; returned live by the backend and never stored. */
  photo: string | null;
}

/** A row in the account chooser when one mobile carries several ABHAs. */
export interface AbhaAccount {
  abha_number: string | null;
  abha_address: string | null;
  name: string;
  gender: string | null;
  kyc_verified: boolean | null;
  status: string | null;
  photo: string | null;
}

export interface AbhaOtpResend {
  available_in_seconds: number;
  remaining: number;
}

export interface AbhaOtpSent {
  transaction_id: string;
  /** ABDM's message; safe to show to the user. */
  message: string;
  /** e.g. "******1234" */
  masked_mobile: string | null;
  otp_system: AbhaOtpSystem;
  resend: AbhaOtpResend;
}

export interface AbhaExistingPatient {
  id: string;
  name: string;
  can_view: boolean;
}

export interface AbhaVerified {
  transaction_id: string;
  status: "verified" | "select_account";
  accounts: AbhaAccount[];
  profile: AbhaProfile | null;
  existing_patient: AbhaExistingPatient | null;
}

/** A masked row returned by "find ABHA by mobile" (no OTP is sent). */
export interface AbhaFindAccount {
  index: number | string;
  abha_number: string;
  name: string;
  gender: string | null;
  kyc_verified: boolean | null;
  /** e.g. ["AADHAAR_OTP", "MOBILE_OTP"] */
  auth_methods: string[];
}

export interface AbhaFindResponse {
  transaction_id: string;
  accounts: AbhaFindAccount[];
}

export interface AbhaCreateVerified {
  transaction_id: string;
  is_new: boolean;
  profile: AbhaProfile;
  mobile_verification_required: boolean;
  abha_address_required: boolean;
  existing_patient: AbhaExistingPatient | null;
}

export interface AbhaTransactionProfile {
  transaction_id: string;
  profile: AbhaProfile;
}

export interface AbhaFile {
  content_type: string;
  /** Base64-encoded file contents. */
  data: string;
}

export interface AbhaOtpRequest {
  identifier_type: AbhaIdentifierType;
  value: string;
  otp_system?: AbhaOtpSystem;
  consent?: AbhaConsentAgreement;
  facility?: string;
}

export interface AbhaCreateOtpRequest {
  aadhaar: string;
  consent: AbhaConsentAgreement;
  facility?: string;
}

export type AbhaLinkSource = "verification" | "creation" | "profile_share";

export interface AbhaLinkedBy {
  id: string;
  username: string;
  first_name: string;
  last_name: string;
}

export interface PatientAbhaLinked {
  linked: true;
  id: string;
  abha_number: string | null;
  abha_address: string | null;
  abha_addresses: string[];
  kyc_verified: boolean;
  profile: AbhaProfile | null;
  source: AbhaLinkSource;
  verification_method: string | null;
  linked_by: AbhaLinkedBy | null;
  linked_at: string;
}

export type PatientAbha = { linked: false } | PatientAbhaLinked;

export type PatientAbhaLinkRequest =
  | { transaction_id: string }
  | { profile_share: string };

export interface AbdmError {
  /** e.g. "abha_not_found", "invalid_otp", "resend_too_soon" */
  type: string;
  msg: string;
  abdm_code?: string | null;
  loc?: (string | number)[] | null;
  retry_after_seconds?: number | null;
  /** Set for `abha_linked_to_other_patient`. */
  patient?: AbhaExistingPatient | null;
}

/* Phase B: facility HIP configuration and scan & share */

export interface FacilityAbdmCounter {
  code: string;
  name: string;
}

export interface FacilityAbdmShareUrl {
  counter: string;
  url: string;
}

export type FacilityAbdmConfig =
  | { configured: false }
  | {
      configured: true;
      hip_id: string;
      hip_name: string;
      counters: FacilityAbdmCounter[];
      share_urls: FacilityAbdmShareUrl[];
    };

export interface FacilityAbdmConfigUpdate {
  hip_id: string;
  hip_name: string;
  counters: FacilityAbdmCounter[];
}

export type AbhaProfileShareStatus =
  | "pending"
  | "registered"
  | "linked"
  | "failed";

export interface AbhaProfileShare {
  id: string;
  token_number: string | number | null;
  counter_code: string | null;
  abha_number: string | null;
  abha_address: string | null;
  profile: AbhaProfile | null;
  status: AbhaProfileShareStatus;
  patient: { id: string; name: string } | null;
  created_date: string;
  expires_at: string | null;
}
import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";
import {
  AbdmConfig,
  AbhaCreateOtpRequest,
  AbhaCreateVerified,
  AbhaFile,
  AbhaFindResponse,
  AbhaOtpRequest,
  AbhaOtpSent,
  AbhaOtpSystem,
  AbhaProfile,
  AbhaProfileShare,
  AbhaProfileShareStatus,
  AbhaTransactionProfile,
  AbhaVerified,
  FacilityAbdmConfig,
  FacilityAbdmConfigUpdate,
  PatientAbha,
  PatientAbhaLinked,
  PatientAbhaLinkRequest,
} from "./abdm";

export default {
  // Configuration
  getConfig: {
    path: "/api/v1/abdm/config/",
    method: HttpMethod.GET,
    TRes: Type<AbdmConfig>(),
  },

  // Identify (login / verify an existing ABHA)
  requestOtp: {
    path: "/api/v1/abdm/abha/otp/request/",
    method: HttpMethod.POST,
    TBody: Type<AbhaOtpRequest>(),
    TRes: Type<AbhaOtpSent>(),
  },
  resendOtp: {
    path: "/api/v1/abdm/abha/otp/resend/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string }>(),
    TRes: Type<AbhaOtpSent>(),
  },
  verifyOtp: {
    path: "/api/v1/abdm/abha/otp/verify/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; otp: string }>(),
    TRes: Type<AbhaVerified>(),
  },
  selectAccount: {
    path: "/api/v1/abdm/abha/select-account/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; abha_number: string }>(),
    TRes: Type<AbhaVerified>(),
  },

  // Find a forgotten ABHA by mobile (returns a masked list, sends no OTP)
  find: {
    path: "/api/v1/abdm/abha/find/",
    method: HttpMethod.POST,
    TBody: Type<{ mobile: string }>(),
    TRes: Type<AbhaFindResponse>(),
  },
  findOtp: {
    path: "/api/v1/abdm/abha/find/otp/",
    method: HttpMethod.POST,
    TBody: Type<{
      transaction_id: string;
      index: number | string;
      otp_system: AbhaOtpSystem;
    }>(),
    TRes: Type<AbhaOtpSent>(),
  },

  // Create (Aadhaar only)
  createOtp: {
    path: "/api/v1/abdm/abha/create/otp/",
    method: HttpMethod.POST,
    TBody: Type<AbhaCreateOtpRequest>(),
    TRes: Type<AbhaOtpSent>(),
<shellId: 58 completed with exit code 0>

# Playwright guardrails (from coordinator)
1. tests/globalSetup.ts runs scripts/playwright-db.sh restore unless CI set; pg_restore --clean into POSTGRES_DB (default `care` = USER MAIN DB, NEVER touch).
   - EVERY playwright invocation: POSTGRES_DB=care_m1 PLAYWRIGHT_DB_SNAPSHOT=/tmp/care_m1_playwright_snapshot.dump
   - Never run npm run playwright:db-* / scripts/playwright-db.sh without both vars.
   - Never read/write/delete /tmp/care_playwright_snapshot.dump
   - Snapshot only for care_m1; coordinate via coordinator before resetting care_m1. Restoring from care_m1 snapshot ok.
2. playwright.config.ts baseURL :4000 = user's server. Create untracked playwright.m1.local.config.ts overriding use.baseURL -> http://localhost:4100; add to .git/info/exclude; run with --config.
3. Another session uses Playwright elsewhere; don't touch shared /tmp artefacts or global browsers beyond `npx playwright install chromium`.
- Confirm .env.local has REACT_CARE_API_URL=http://localhost:9100 before first run.
# Other hard rules
- No push, no PR, no GH account actions, no star. Don't touch /Users/jacob/Desktop/care_fe, ports 4000/8000/8001.
- Never send OTPs to real people. Dev server: npx vite --port 4100 --strictPort (leave running).
# Contract clarifications (coordinator)
- abha_address input: user may type with/without suffix (john.doe or john.doe@sbx). Backend appends @{cm_id} when no '@'. UI: show suffix as adornment/hint from config.abha_address_suffix; don't require; don't reject '@sbx'.
- Unknown address -> 404 abha_not_found like others; shared not-found screen. For ABHA address: offer "check the address" (edit) FIRST, creation SECONDARY.
- Backend still building; coordinator will message when :9100 is up + deviations.

## Contract revision (coordinator, Aadhaar always enrols)
1. Identifier = Aadhaar -> ALWAYS enrolment endpoints, never otp/request identifier_type=aadhaar.
   consent checkbox -> POST abha/create/otp {aadhaar, consent} -> OTP step asks OTP + "Mobile number for ABHA communication"
   -> POST abha/create/verify {transaction_id, otp, mobile}. ABDM returns existing ABHA with is_new:false.
2. is_new:false -> show "An ABHA already exists for this Aadhaar", go to result (profile card + primary action), skip mobile verify & address
   (exception: show address step if abha_address_required true). mobile_verification_required false for existing.
3. is_new:true -> optional mobile verify, then address.
4. Not found (abha_not_found from other identifiers) -> "Create ABHA with Aadhaar" goes STRAIGHT to create/otp (no lookup first). Reuse Aadhaar+consent if already entered.
5. Unchanged: link uses POST patient/{id}/abha/link/ {transaction_id} with create txn; existing_patient in create/verify response.

## REVERTED: "Aadhaar always enrols" is REVERTED. ORIGINAL DESIGN STANDS (§7 step 5)
1. Aadhaar picked -> consent text + checkbox -> POST otp/request {identifier_type:"aadhaar", value, consent}
   - Found: OTP sent -> OTP step -> otp/verify as normal.
   - 404 abha_not_found: no OTP sent -> "No ABHA found for this Aadhaar. Create one?" -> confirm -> POST create/otp {aadhaar, consent}
     (reuse Aadhaar+consent, never ask twice) -> OTP step with OTP + "Mobile number for ABHA communication" -> create/verify.
2. abha_not_found from other identifiers: "Create ABHA" asks only Aadhaar + consent -> STILL looks up first via otp/request aadhaar; create only on 2nd abha_not_found.
KEEP: is_new:false from create/verify = rare safety net -> "An ABHA already exists for this Aadhaar" -> result; skip mobile verify; skip address unless abha_address_required.
KEEP: ABHA address input & suffix guidance.

## UX rules (coordinator; atoms m1-never-ask-twice, m1-screen-contract, m1-honest-screen-states)
1. Fact store holds {value, provenance} per fact. Every prefilled field in the flow shows provenance:
   "from the mobile you entered earlier", "from patient record", "from ABHA". Nothing silently overwrites a fact.
2. Failed route gives back what it collected: mobile -> abha_not_found -> Create ABHA asks only Aadhaar+consent (lookup first);
   create OTP step "Mobile number for ABHA communication" PREFILLED from that mobile w/ provenance.
3. Patient page: prefill mobile identifier from patient.phone_number, provenance "from patient record".
4. Reset whole fact store + hand-typed inputs whenever flow closed or restarted.
5. Inactive steps inert: render only active step.
6. abha_not_found can come from otp/verify too -> same not-found screen.
