        </div>
        <div className="flex min-w-0 flex-col gap-1">
          <p
            className="text-base font-semibold break-words text-gray-900"
            data-testid="abha-profile-name"
          >
            {profile.name}
          </p>
          <div className="flex flex-wrap gap-1">
            {profile.kyc_verified ? (
              <Badge variant="green" data-testid="abha-kyc-badge">
                <BadgeCheckIcon className="size-3" />
                {t("abha_kyc_verified")}
              </Badge>
            ) : (
              <Badge variant="yellow" data-testid="abha-kyc-badge">
                {t("abha_kyc_not_verified")}
              </Badge>
            )}
            {profile.status && profile.status !== "ACTIVE" && (
              <Badge variant="secondary">{profile.status}</Badge>
            )}
          </div>
        </div>
      </div>

      <dl className="grid grid-cols-1 gap-x-4 gap-y-2 text-sm sm:grid-cols-2">
        {rows.map((row) => (
          <div key={row.testId} className="flex min-w-0 flex-col">
            <dt className="text-xs text-gray-500">{row.label}</dt>
            <dd
              className="font-medium break-words text-gray-900"
              data-testid={row.testId}
            >
              {row.value || "-"}
            </dd>
          </div>
        ))}
      </dl>

      {transactionId && (
        <div className="flex flex-wrap gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => cardMutation.mutate(undefined)}
            disabled={cardMutation.isPending}
            data-testid="abha-download-card"
          >
            {cardMutation.isPending ? (
              <Loader2Icon className="animate-spin" />
            ) : (
              <DownloadIcon />
            )}
            {t("abha_download_card")}
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => setIsQrOpen(true)}
            data-testid="abha-show-qr"
          >
            <QrCodeIcon />
            {t("abha_show_qr")}
          </Button>
        </div>
      )}

      {cardMutation.error && <AbdmErrorAlert error={cardMutation.error} />}

      {children}

      {transactionId && (
        <AbhaQrDialog
          open={isQrOpen}
          onOpenChange={setIsQrOpen}
          transactionId={transactionId}
          name={profile.name}
        />
      )}
    </div>
  );
}

function AbhaQrDialog({
  open,
  onOpenChange,
  transactionId,
  name,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  transactionId: string;
  name: string;
}) {
  const { t } = useTranslation();

  const { data, error, isLoading } = useQuery({
    queryKey: ["abdm", "abha-qr", transactionId],
    queryFn: query(abdmApi.getQr, {
      queryParams: { transaction_id: transactionId },
      silent: abdmSilent,
    }),
    enabled: open,
    retry: false,
    staleTime: Infinity,
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>{t("abha_qr_code")}</DialogTitle>
          <DialogDescription>{name}</DialogDescription>
        </DialogHeader>
        <div className="flex justify-center">
          {isLoading && <Skeleton className="size-64" />}
          {data && (
            <img
              src={toDataUrl(data)}
              alt={t("abha_qr_code")}
              className="size-64 object-contain"
              data-testid="abha-qr-image"
            />
          )}
        </div>
        {error && <AbdmErrorAlert error={error} />}
      </DialogContent>
    </Dialog>
  );
}

