import { createContext, useContext } from "react";

import {
  AbhaFacts,
  AbhaFlowResult,
  AbhaFlowStep,
  RememberFact,
} from "@/components/Abdm/types";

import { AbdmConfig, AbhaConsentAgreement } from "@/types/abdm/abdm";

interface AbhaFlowContextValue {
  config: AbdmConfig;
  facilityId?: string;
  /** The per-flow fact store ("never ask twice"). */
  facts: AbhaFacts;
  rememberFact: RememberFact;
  /** False when the flow only verifies an ABHA that is already known. */
  allowCreate: boolean;
  /** The consent payload sent with every Aadhaar request. */
  consent: AbhaConsentAgreement;
  goTo: (step: AbhaFlowStep) => void;
  finish: (result: AbhaFlowResult, notice?: "abha_exists") => void;
  /** Discards the flow and every value collected in it. */
  restart: () => void;
}

export const AbhaFlowContext = createContext<AbhaFlowContextValue | null>(
  null,
);

export function useAbhaFlow() {
  const context = useContext(AbhaFlowContext);
  if (!context) {
    throw new Error("useAbhaFlow must be used within an AbhaIdentifyFlow");
  }
  return context;
}

