import { useMutation } from "@tanstack/react-query";
import { Loader2Icon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { ProvenanceHint } from "@/components/Abdm/ProvenanceHint";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import { AbhaVerifyIdentifierType } from "@/components/Abdm/types";
import { abdmSilent, isAbdmErrorType } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { AbhaOtpSystem } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const OTP_SYSTEMS: AbhaOtpSystem[] = ["aadhaar", "abdm"];

export function AuthMethodStep({
  identifierType,
  value,
  canGoBack,
}: {
  identifierType: AbhaVerifyIdentifierType;
  value: string;
  canGoBack: boolean;
}) {
  const { t } = useTranslation();
  const { facilityId, facts, goTo } = useAbhaFlow();
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem>("abdm");

  const fact = facts[identifierType];

  const otpMutation = useMutation({
    mutationFn: mutate(abdmApi.requestOtp, { silent: abdmSilent }),
    onSuccess: (otpSent) =>
      goTo({ name: "otp", otpSent, identifierType, value }),
    onError: (error) => {
      if (isAbdmErrorType(error, "abha_not_found")) {
        goTo({ name: "not_found", identifierType, value });
      }
    },
  });

  return (
    <StepLayout
      title={t("abdm_auth_method_title")}
      description={t("abdm_auth_method_description")}
      onBack={
        canGoBack
          ? () => goTo({ name: "identifier", identifierType })
          : undefined
      }
      testId="abdm-step-auth-method"
      footer={
        <Button
          type="button"
          variant="primary"
          disabled={otpMutation.isPending}
