import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbdmField } from "@/components/Abdm/AbdmField";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import {
  abdmSilent,
  isAbdmErrorType,
  isValidMobile,
  provenanceFor,
} from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { AbhaFindAccount, AbhaOtpSystem } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const AUTH_METHOD_TO_OTP_SYSTEM: Record<string, AbhaOtpSystem> = {
  AADHAAR_OTP: "aadhaar",
  MOBILE_OTP: "abdm",
};

function getOtpSystems(account: AbhaFindAccount) {
  const systems = (account.auth_methods ?? [])
    .map((method) => AUTH_METHOD_TO_OTP_SYSTEM[method])
    .filter((system): system is AbhaOtpSystem => !!system);
  return systems.length ? [...new Set(systems)] : (["abdm"] as const);
}

export function FindStep() {
  const { t } = useTranslation();
  const { facts, rememberFact, goTo } = useAbhaFlow();

  const [mobile, setMobile] = useState(() => facts.mobile?.value ?? "");
  const [showErrors, setShowErrors] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<string>();
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem>();

  const findMutation = useMutation({
    mutationFn: mutate(abdmApi.find, { silent: abdmSilent }),
    onSuccess: (data) => {
      const [first] = data.accounts;
      if (data.accounts.length === 1 && first) {
        setSelectedIndex(String(first.index));
        setOtpSystem(getOtpSystems(first)[0]);
      }
    },
    onError: (error, variables) => {
      if (isAbdmErrorType(error, "abha_not_found")) {
        goTo({
          name: "not_found",
          identifierType: "mobile",
          value: variables.mobile,
        });
      }
    },
  });

  const otpMutation = useMutation({
    mutationFn: mutate(abdmApi.findOtp, { silent: abdmSilent }),
    onSuccess: (otpSent) =>
      goTo({
        name: "otp",
        otpSent,
        identifierType: "mobile",
        value: mobile,
      }),
  });

  const accounts = findMutation.data?.accounts ?? [];
  const selectedAccount = accounts.find(
    (account) => String(account.index) === selectedIndex,
  );
  const mobileError =
    showErrors && !isValidMobile(mobile)
      ? t("abdm_validation__mobile")
      : undefined;

  const handleSearch = (event: FormEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (!isValidMobile(mobile)) return;
    rememberFact("mobile", mobile);
    setSelectedIndex(undefined);
    setOtpSystem(undefined);
    otpMutation.reset();
    findMutation.mutate({ mobile });
  };

  const findError = isAbdmErrorType(findMutation.error, "abha_not_found")
    ? null
    : findMutation.error;

  return (
    <StepLayout
      title={t("abdm_find_title")}
      description={t("abdm_find_description")}
      onBack={() => goTo({ name: "identifier" })}
      testId="abdm-step-find"
    >
      <form
        className="flex flex-col gap-3 sm:flex-row sm:items-end"
        onSubmit={handleSearch}
        noValidate
      >
        <AbdmField
          className="flex-1"
          label={t("mobile_number")}
          prefix="+91"
          inputMode="numeric"
          maxLength={10}
          placeholder={t("abdm_mobile_placeholder")}
          value={mobile}
          onChange={(e) => {
            setMobile(e.target.value.replace(/\D/g, "").slice(0, 10));
            if (findMutation.data) {
              findMutation.reset();
              otpMutation.reset();
            }
          }}
          error={mobileError}
          provenance={provenanceFor(facts.mobile, mobile, "mobile")}
          data-testid="abdm-find-mobile-input"
        />
        <Button
          type="submit"
          variant={findMutation.data ? "outline" : "primary"}
          disabled={findMutation.isPending}
          data-testid="abdm-find-submit"
          className={mobileError ? "sm:mb-7" : undefined}
        >
          {findMutation.isPending ? (
            <Loader2Icon className="animate-spin" />
          ) : (
            <SearchIcon />
          )}
          {t("search")}
        </Button>
      </form>

      {findError && <AbdmErrorAlert error={findError} />}

      {accounts.length > 0 && (
        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <p className="text-sm font-medium text-gray-900">
              {t("abdm_find_accounts_found", { count: accounts.length })}
            </p>
            <RadioGroup
              value={selectedIndex ?? ""}
              onValueChange={(index) => {
                setSelectedIndex(index);
                const account = accounts.find(
                  (item) => String(item.index) === index,
                );
                setOtpSystem(account ? getOtpSystems(account)[0] : undefined);
                otpMutation.reset();
              }}
              aria-label={t("abdm_find_choose_account")}
              className="gap-2"
            >
              {accounts.map((account) => (
                <Label
                  key={account.index}
                  htmlFor={`abdm-find-account-${account.index}`}
                  className="flex cursor-pointer items-start gap-3 rounded-md border border-gray-200 p-3 font-normal has-[button[data-state=checked]]:border-primary-500 has-[button[data-state=checked]]:bg-primary-50"
                  data-testid="abdm-find-account"
                >
                  <RadioGroupItem
                    id={`abdm-find-account-${account.index}`}
                    value={String(account.index)}
                    className="mt-0.5"
                  />
                  <span className="flex min-w-0 flex-col gap-1">
                    <span className="text-sm font-medium text-gray-900">
                      {account.name}
                    </span>
                    <span className="text-xs text-gray-600">
                      {account.abha_number}
                      {account.gender && ` · ${account.gender}`}
                    </span>
                    {account.kyc_verified && (
                      <Badge variant="green" size="xs" className="w-fit">
                        <BadgeCheckIcon className="size-3" />
                        {t("abha_kyc_verified")}
                      </Badge>
                    )}
                  </span>
                </Label>
              ))}
            </RadioGroup>
          </div>

          {selectedAccount && (
            <div className="flex flex-col gap-2">
              <p className="text-sm font-medium text-gray-900">
                {t("abdm_auth_method_title")}
              </p>
              <RadioGroup
                value={otpSystem ?? ""}
                onValueChange={(next) => setOtpSystem(next as AbhaOtpSystem)}
                aria-label={t("abdm_auth_method_title")}
                className="gap-2"
              >
                {getOtpSystems(selectedAccount).map((system) => (
                  <Label
                    key={system}
                    htmlFor={`abdm-find-otp-system-${system}`}
                    className="flex cursor-pointer items-center gap-3 rounded-md border border-gray-200 p-3 font-normal has-[button[data-state=checked]]:border-primary-500 has-[button[data-state=checked]]:bg-primary-50"
                  >
                    <RadioGroupItem
                      id={`abdm-find-otp-system-${system}`}
                      value={system}
                      data-testid={`abdm-find-otp-system-${system}`}
                    />
                    <span className="text-sm text-gray-900">
                      {t(`abdm_otp_system__${system}`)}
                    </span>
                  </Label>
                ))}
              </RadioGroup>
            </div>
          )}

          {otpMutation.error && <AbdmErrorAlert error={otpMutation.error} />}

          <div className="flex justify-end">
            <Button
              type="button"
              variant="primary"
              disabled={
                !selectedAccount ||
                !otpSystem ||
                !findMutation.data ||
                otpMutation.isPending
              }
              onClick={() => {
                if (!selectedAccount || !otpSystem || !findMutation.data) {
                  return;
                }
                otpMutation.mutate({
                  transaction_id: findMutation.data.transaction_id,
                  index: selectedAccount.index,
                  otp_system: otpSystem,
                });
              }}
              data-testid="abdm-find-send-otp"
            >
              {otpMutation.isPending && (
                <Loader2Icon className="animate-spin" />
              )}
              {t("abdm_send_otp")}
            </Button>
          </div>
        </div>
      )}
    </StepLayout>
  );
}

