import { useState } from "react";

import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";

import {
  AbhaIdentifyFlow,
  AbhaIdentifyFlowProps,
} from "@/components/Abdm/AbhaIdentifyFlow";

interface AbhaIdentifySheetProps extends Omit<
  AbhaIdentifyFlowProps,
  "onRestart"
> {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
}

/**
 * Hosts the ABHA flow in a side sheet. Closing the sheet unmounts the flow
 * and "Start again" remounts it, so no value survives into the next patient.
 */
export function AbhaIdentifySheet({
  open,
  onOpenChange,
  title,
  description,
  ...flowProps
}: AbhaIdentifySheetProps) {
  const [flowKey, setFlowKey] = useState(0);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        className="flex w-full flex-col gap-0 p-0 sm:max-w-lg"
        onInteractOutside={(event) => event.preventDefault()}
        data-testid="abdm-sheet"
      >
        <SheetHeader className="border-b border-gray-200 p-4 pr-12">
          <SheetTitle>{title}</SheetTitle>
          {description && <SheetDescription>{description}</SheetDescription>}
        </SheetHeader>
        <div className="flex-1 overflow-y-auto p-4">
          <AbhaIdentifyFlow
            key={flowKey}
            {...flowProps}
            onRestart={() => setFlowKey((key) => key + 1)}
          />
        </div>
      </SheetContent>
    </Sheet>
  );
}

