/**
 * ABDM requests render their errors inline on the step in view, so the global
 * toast handler is silenced for them. A 401 still reaches the global handler,
 * because it means the CARE session (not ABDM) has expired.
 */
export const abdmSilent = (res: Response) => res.status !== 401;

export function getAbdmError(error: unknown): AbdmError | undefined {
  if (!(error instanceof HTTPError)) {
    return undefined;
  }
  const errors = (error.cause as { errors?: unknown } | undefined)?.errors;
  if (Array.isArray(errors) && errors.length > 0) {
    const first = errors[0];
    if (first && typeof first === "object" && "type" in first) {
      return first as AbdmError;
    }
  }
  return undefined;
}

export function isAbdmErrorType(error: unknown, ...types: string[]) {
  const type = getAbdmError(error)?.type;
  return !!type && types.includes(type);
}

/** Errors after which the current ABDM transaction cannot continue. */
export const RESTART_ERROR_TYPES = [
  "transaction_expired",
  "transaction_not_found",
  "invalid_state",
  "abdm_session_expired",
];

/** Errors whose server message (ABDM's own wording) adds useful detail. */
const DETAILED_ERROR_TYPES = [
  "validation_error",
  "abdm_validation_error",
  "abdm_error",
];

const KNOWN_ERROR_TYPES = [
  "validation_error",
  "abdm_validation_error",
  "invalid_otp",
  "otp_expired",
  "transaction_expired",
  "invalid_state",
