export function normalizeAadhaar(value: string) {
  return onlyDigits(value).slice(0, 12);
}

export function isValidAadhaar(value: string) {
  return /^\d{12}$/.test(value) && isVerhoeffValid(value);
}

/** Shows only the last 4 digits, e.g. "XXXX XXXX 1234". */
export function maskAadhaar(value: string) {
  return `XXXX XXXX ${value.slice(-4)}`;
}

export function isValidMobile(value: string) {
  return /^[6-9]\d{9}$/.test(value);
}

/** Extracts a 10 digit Indian mobile from a CARE phone number (+91XXXXXXXXXX). */
export function phoneToMobile(phone?: string | null) {
  if (!phone) return undefined;
  const digits = onlyDigits(phone);
  const mobile =
    digits.length === 12 && digits.startsWith("91") ? digits.slice(2) : digits;
  return isValidMobile(mobile) ? mobile : undefined;
}

export function mobileToPhone(mobile: string) {
  return `+91${mobile}`;
}

export function isValidAbhaNumber(value: string) {
  return /^\d{14}$/.test(onlyDigits(value)) && /^[\d\s-]+$/.test(value);
}

/** Formats 14 digits as "XX-XXXX-XXXX-XXXX". */
export function formatAbhaNumber(value: string) {
  const digits = onlyDigits(value);
  if (digits.length !== 14) return value;
  return `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6, 10)}-${digits.slice(10)}`;
}

/** ABHA address used to log in; the suffix (e.g. "@sbx") is optional. */
export function isValidAbhaAddressLogin(value: string) {
  return /^[^\s@]+(@[^\s@]+)?$/.test(value.trim());
}

/**
 * Validates a new ABHA address (without the suffix) against the ABDM policy:
 * letters, digits and dots only; must not begin with a digit; must not begin
 * or end with a dot; must not be a mobile number.
 * Returns an i18n key for the problem, or undefined when valid.
 */
export function getNewAbhaAddressError(value: string) {
  if (!value) return "abha_address_error__required";
  if (isValidMobile(value) || /^\d+$/.test(value)) {
    return "abha_address_error__mobile";
  }
  if (!/^[a-zA-Z0-9.]+$/.test(value)) return "abha_address_error__characters";
  if (/^\d/.test(value)) return "abha_address_error__starts_with_digit";
  if (value.startsWith(".") || value.endsWith(".")) {
    return "abha_address_error__dot";
  }
  return undefined;
}

/** Removes the CM suffix from an ABHA address, e.g. "john.doe@sbx" → "john.doe". */
export function stripAbhaAddressSuffix(value: string) {
  return value.trim().split("@")[0];
}

export function toDataUrl(file: AbhaFile) {
  return `data:${file.content_type};base64,${file.data}`;
}

export function photoToDataUrl(photo?: string | null) {
  if (!photo) return undefined;
  if (photo.startsWith("data:")) return photo;
  return `data:image/jpeg;base64,${photo}`;
}

const FILE_EXTENSIONS: Record<string, string> = {
  "application/pdf": "pdf",
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/jpg": "jpg",
  "image/svg+xml": "svg",
};

export function downloadBase64File(file: AbhaFile, filename: string) {
  const binary = atob(file.data);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const blob = new Blob([bytes], { type: file.content_type });
  const url = URL.createObjectURL(blob);
  const extension =
    FILE_EXTENSIONS[file.content_type] ??
    file.content_type.split("/")[1] ??
    "bin";
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `${filename}.${extension}`;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

