export function getAbhaAddressSuffix(config: {
  abha_address_suffix?: string | null;
  cm_id?: string | null;
}) {
  const suffix = config.abha_address_suffix || config.cm_id || "";
  if (!suffix) return "";
  return suffix.startsWith("@") ? suffix : `@${suffix}`;
}

