         !data.date_of_birth && data.year_of_birth
           ? new Date().getFullYear() - data.year_of_birth
           : undefined,
       blood_group: data.blood_group || undefined,
       tags: [], // This is only used for create patient

       address: data.address || "",
       permanent_address: data.permanent_address || "",
       permanent_address_same_as_address:
         data.address === data.permanent_address,
       geo_organization: data.geo_organization?.id || "",
       pincode: data.pincode || undefined,

       is_deceased: !!data.deceased_datetime,
       deceased_datetime: data.deceased_datetime || null,

       required_identifiers:
         getRequiredIdentifierConfigs(facility).map(getIdentifier),
       optional_identifiers:
         getOptionalIdentifierConfigs(facility).map(getIdentifier),
       autogenerated_identifiers:
         getAutogeneratedIdentifierConfigs(facility).map(getIdentifier),

       _selected_levels: [data.geo_organization],

       extensions: {
         ...ext.defaults,
         ...Object.fromEntries(
           Object.entries(data.extensions || {}).map(([key, value]) => [
             key,
             { ...(ext.defaults[key] || {}), ...value },
           ]),
         ),
       },
     });

     // eslint-disable-next-line react-hooks/exhaustive-deps
   }, [patientQuery.data, facility, defaultGeoOrg, ext.defaults]);

   const phoneNumber = form.watch("phone_number");
   const patientPhoneSearch = useQuery({
     queryKey: ["patients", "phone-number", phoneNumber],
     queryFn: query.debounced(patientApi.search, {
       body: { phone_number: phoneNumber },
     }),
     enabled: isValidPhoneNumber(phoneNumber),
   });

   const duplicatePatients = patientPhoneSearch.data?.results.filter(
     (p) => p.id !== patientId,
   );

   const { mutate: createPatient, isPending: isCreatingPatient } = useMutation({
     mutationKey: ["create_patient"],
     mutationFn: mutate(patientApi.create),
     onSuccess: (resp: PatientRead) => {
       toast.success(t("patient_registration_success"));
       // Navigate the user to the patients home page to access the newly created patient
       navigate(`/facility/${facilityId}/patients/home`, {
         query: {
           phone_number: resp.phone_number,
           year_of_birth: resp.year_of_birth,
           partial_id: resp?.id?.slice(0, 5),
           ...(flow && { flow, createEncounter: "true" }),
           ...(careConfig.openScheduleAfterPatientRegistration && {
             open_schedule: "true",
           }),
         },
         replace: true,
       });
     },
   });

   const { mutate: updatePatient, isPending: isUpdatingPatient } = useMutation({
     mutationKey: ["update_patient"],
     mutationFn: mutate(patientApi.update, {
       pathParams: { id: patientId || "" },
     }),
     onSuccess: () => {
       toast.success(t("patient_update_success"));
       form.reset(form.getValues());
       goBack();
     },
   });

   const isPending = isCreatingPatient || isUpdatingPatient;

   const showDuplicate =
     !patientPhoneSearch.isLoading &&
     !!duplicatePatients?.length &&
     !!isValidPhoneNumber(phoneNumber) &&
     !suppressDuplicateWarning;

   useNavigationPrompt(
     form.formState.isDirty && !isPending && !showDuplicate,
     t("unsaved_changes"),
   );

   if (patientId && patientQuery.isLoading) {
     return <Loading />;
   }

   function onSubmit(values: z.infer<typeof formSchema>) {
     if (!facility) {
       return;
     }

     const { extensions: formExtensions, ...restValues } = values;
     const cleanedExtensions = extensions.prepareForSubmit(
       formExtensions as NamespacedExtensionData,
     );

     const basePayload = {
       ...restValues,

       age:
         restValues.age_or_dob === "dob"
           ? undefined
           : restValues.age || undefined,
       date_of_birth:
         restValues.age_or_dob === "dob"
           ? restValues.date_of_birth || undefined
           : undefined,

       emergency_phone_number:
         restValues.emergency_phone_number_same_as_phone_number
           ? restValues.phone_number
           : restValues.emergency_phone_number,

       permanent_address: restValues.permanent_address_same_as_address
         ? restValues.address
         : restValues.permanent_address,
       pincode: restValues.pincode,

       deceased_datetime: restValues.is_deceased
         ? restValues.deceased_datetime
         : null,

       identifiers: getEditableIdentifiers(
         [
           ...restValues.required_identifiers,
           ...restValues.optional_identifiers,
           ...restValues.autogenerated_identifiers,
         ],
         facility,
       ),

       extensions: cleanedExtensions,
     };

     if (!patientId) {
       createPatient({
         ...basePayload,
         tags: restValues.tags,
       });
     } else {
       updatePatient(basePayload);
     }
   }

   const pageTitle = !patientId
     ? t("register_new_patient")
     : t("update_patient_details");

   return (
     <Page title={pageTitle} hideTitleOnPage>
       <div className="flex flex-col gap-4 max-w-2xl mx-auto">
         <div>
           <BackButton data-shortcut-id="go-back">
             <ArrowLeft />
             {t("back")}
           </BackButton>
         </div>
         <div className="pb-4 mb-2 border-b border-gray-200">
           <div className="flex flex-col">
             <h4 className="font-semibold">{pageTitle}</h4>
             {!patientId && (
               <span className="text-sm text-gray-700">
                 {t("patient_create_description")}
               </span>
             )}
           </div>
         </div>

         <Form {...form}>
           <form onSubmit={form.handleSubmit(onSubmit)}>
             <Accordion
               type="multiple"
               className="flex flex-col gap-6"
               defaultValue={
                 quickRegistration
                   ? ["patient-basics"]
                   : ["patient-basics", "additional-details"]
               }
             >
               <PLUGIN_Component
                 __name="PatientRegistrationForm"
                 form={form}
                 facilityId={facilityId}
                 patientId={patientId}
                 submitForm={form.handleSubmit(onSubmit)}
               />
               <AccordionItem
                 value="patient-basics"
                 className="bg-white flex flex-col gap-4 p-6 shadow rounded-md"
               >
                 <AccordionTrigger className="flex justify-between">
                   <div className="flex gap-3 items-center w-full">
                     <h5 className="text-lg font-semibold">
                       1: {t("patient_basics")}
                     </h5>
                     {/* TODO: add progress bar */}
                   </div>
                 </AccordionTrigger>
                 <AccordionContent className="px-1 flex flex-col gap-6">
                   <PatientBasicsContent form={form} isCreate={!patientId} />
                 </AccordionContent>
               </AccordionItem>
               <AccordionItem
                 value="additional-details"
                 className="bg-white flex flex-col gap-4 p-6 shadow rounded-md"
               >
                 <AccordionTrigger className="flex justify-between">
                   <div className="flex gap-3 items-center w-full">
                     <h5 className="text-lg font-semibold">
                       2: {t("additional_details")}{" "}
                       {quickRegistration && `(${t("optional")})`}
                     </h5>
                     {/* TODO: add progress bar */}
                   </div>
                 </AccordionTrigger>
                 <AccordionContent className="px-1 flex flex-col gap-6">
                   <AdditionalDetailsContent form={form} />
                   {extensions.fields}
                 </AccordionContent>
               </AccordionItem>
             </Accordion>
             <div className="w-full border-t border-gray-200 py-6 mt-6">
               <div className="max-w-2xl mx-auto flex justify-end">
                 <Button
                   variant="primary_gradient"
                   disabled={
                     !form.formState.isDirty || isPending || isExtensionsLoading
                   }
                 >
                   <CheckIcon />
                   {patientId ? t("update") : t("register_patient")}
                   <ShortcutBadge actionId="submit-action" />
                 </Button>
               </div>
             </div>
           </form>
         </Form>
       </div>

       {showDuplicate && (
         <DuplicatePatientDialog
           open={showDuplicate}
           patientList={duplicatePatients}
           onTransfer={() =>
             navigate(`/facility/${facilityId}/patients`, {
               query: { phone_number: form.getValues("phone_number") },
             })
           }
           onOpenChange={(open) => {
             if (!open) {
               setSuppressDuplicateWarning(true);
             }
           }}
         />
       )}
     </Page>
   );
 };

