import { AlertCircleIcon, RotateCcwIcon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import {
  getAbdmErrorMessage,
  isAbdmErrorType,
  RESTART_ERROR_TYPES,
} from "@/components/Abdm/utils";

interface AbdmErrorAlertProps {
  error: unknown;
  /** Offered when the transaction can no longer continue (e.g. it expired). */
  onRestart?: () => void;
  className?: string;
}

/** Renders an ABDM error inline on the step in view. */
export function AbdmErrorAlert({
  error,
  onRestart,
  className,
}: AbdmErrorAlertProps) {
  const { t } = useTranslation();

  if (!error) {
    return null;
  }

  const { title, description } = getAbdmErrorMessage(t, error);
  const canRestart =
    !!onRestart && isAbdmErrorType(error, ...RESTART_ERROR_TYPES);

  return (
    <Alert
      variant="destructive"
      className={cn("border-red-200 bg-red-50", className)}
      data-testid="abdm-error"
    >
      <AlertCircleIcon />
      <AlertTitle className="line-clamp-none">{title}</AlertTitle>
      {(description || canRestart) && (
        <AlertDescription>
          {description && <p>{description}</p>}
          {canRestart && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="mt-1"
              onClick={onRestart}
            >
              <RotateCcwIcon />
              {t("abdm_start_again")}
            </Button>
          )}
        </AlertDescription>
      )}
    </Alert>
  );
}
