+  const prefill: AbhaRegistrationPrefill = {};
+
+  if (profile.name?.trim()) prefill.name = profile.name.trim();
+  if (profile.gender) prefill.gender = profile.gender;
+
+  if (profile.date_of_birth) {
+    prefill.date_of_birth = profile.date_of_birth;
+  } else if (profile.year_of_birth) {
+    const age = new Date().getFullYear() - profile.year_of_birth;
+    if (age >= 1) prefill.age = age;
+  }
+
+  if (profile.mobile) prefill.phone_number = mobileToPhone(profile.mobile);
+  if (profile.address?.trim()) prefill.address = profile.address.trim();
+  if (profile.pincode && /^\d{6}$/.test(profile.pincode)) {
+    prefill.pincode = Number(profile.pincode);
+  }
+
+  return prefill;
+}
+
+const normalizeName = (name: string) =>
+  name.toLowerCase().replace(/[^a-z0-9]/g, "");
+
+async function findGovtOrganization(name: string, parent?: Organization) {
+  const { results } = await callApi(organizationApi.list, {
+    queryParams: {
+      org_type: "govt",
+      parent: parent?.id ?? "",
+      name,
+      limit: 50,
+    },
+    silent: true,
+  });
+  const target = normalizeName(name);
+  return results.find(
+    (organization) =>
+      normalizeName(organization.name) === target &&
+      (parent
+        ? organization.level_cache === parent.level_cache + 1
+        : organization.level_cache === 0),
+  );
+}
+
+/**
+ * Best-effort match of the ABHA's state and district to CARE's government
+ * organizations, by name. Returns the deepest level that matched, or
+ * undefined; the user can always change the selection.
+ */
+export async function matchAbhaGeoOrganization(
+  profile: AbhaProfile,
+): Promise<Organization | undefined> {
+  if (!profile.state_name) return undefined;
+  try {
+    const state = await findGovtOrganization(profile.state_name);
+    if (!state || !profile.district_name || !state.has_children) {
+      return state;
+    }
+    const district = await findGovtOrganization(profile.district_name, state);
+    return district ?? state;
+  } catch {
+    return undefined;
+  }
+}

