import { useQuery } from "@tanstack/react-query";
import { IdCardIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import { AbhaExistingPatientAlert } from "@/components/Abdm/AbhaExistingPatientAlert";
import { AbhaIdentifyFlow } from "@/components/Abdm/AbhaIdentifyFlow";
import { AbhaProfileCard } from "@/components/Abdm/AbhaProfileCard";
import { RegistrationAbha } from "@/components/Abdm/registration";
import { AbhaFacts } from "@/components/Abdm/types";
import { abdmSilent, phoneToMobile } from "@/components/Abdm/utils";

import query from "@/Utils/request/query";
import { AbdmConfig, AbhaProfileShare } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

interface AbhaRegistrationStepProps {
  config: AbdmConfig;
  facilityId: string;
  /** The phone number the user searched with before registering, if any. */
  phoneNumber?: string;
  /** A profile shared at a counter ("scan and share") to register from. */
  profileShare?: { id: string; date?: string };
  onUse: (selection: RegistrationAbha) => void;
  onSkip: () => void;
}

/**
 * The ABHA step that opens patient registration: look the patient's ABHA up
 * (or create one) first, then fill the registration form from it.
 */
export function AbhaRegistrationStep({
  config,
  facilityId,
  phoneNumber,
  profileShare,
  onUse,
  onSkip,
}: AbhaRegistrationStepProps) {
  const { t } = useTranslation();
  const [flowKey, setFlowKey] = useState(0);
  const [useShare, setUseShare] = useState(!!profileShare);

  const mobile = phoneToMobile(phoneNumber);
  const initialFacts: AbhaFacts = mobile
    ? { mobile: { value: mobile, provenance: "entered" } }
    : {};

  return (
    <section
      className="flex flex-col gap-4 rounded-md bg-white p-6 shadow"
      data-testid="abdm-registration-step"
    >
      <div className="flex items-start gap-3">
        <div className="rounded-full bg-primary-100 p-2 text-primary-700">
          <IdCardIcon className="size-5" aria-hidden />
        </div>
        <div className="flex flex-col gap-0.5">
          <h5 className="text-lg font-semibold">
            {t("abdm_registration_title")}
          </h5>
          <p className="text-sm text-gray-600">
            {t("abdm_registration_description")}
          </p>
        </div>
      </div>

      {profileShare && useShare ? (
        <ProfileShareStep
          facilityId={facilityId}
          shareId={profileShare.id}
          date={profileShare.date}
          onUse={onUse}
          onSkip={onSkip}
          onVerifyInstead={() => setUseShare(false)}
        />
      ) : (
        <AbhaIdentifyFlow
          key={flowKey}
          config={config}
          facilityId={facilityId}
          initialFacts={initialFacts}
          onRestart={() => setFlowKey((key) => key + 1)}
          exitLabel={t("abdm_continue_without_abha")}
          onExit={onSkip}
          renderResultAction={(result) =>
            result.existingPatient ? (
              <AbhaExistingPatientAlert
                patient={result.existingPatient}
                facilityId={facilityId}
              />
            ) : (
              <Button
                type="button"
                onClick={() =>
                  onUse({
                    profile: result.profile,
                    link: { transaction_id: result.transactionId },
                  })
                }
                data-testid="abdm-use-for-registration"
              >
                {t("abdm_use_for_registration")}
              </Button>
            )
          }
        />
      )}
    </section>
  );
}

function ProfileShareStep({
  facilityId,
  shareId,
  date,
  onUse,
  onSkip,
  onVerifyInstead,
}: {
  facilityId: string;
  shareId: string;
  date?: string;
  onUse: (selection: RegistrationAbha) => void;
  onSkip: () => void;
  onVerifyInstead: () => void;
}) {
  const { t } = useTranslation();

  // There is no single-share endpoint: the share is found in its day's queue.
  const { data, isLoading, isError } = useQuery({
    queryKey: ["abdm", "shares", facilityId, date ?? "today"],
    queryFn: query(abdmApi.listShares, {
      pathParams: { facilityId },
      queryParams: { ...(date && { date }), limit: 100 },
      silent: abdmSilent,
    }),
  });

  const share: AbhaProfileShare | undefined = data?.results.find(
    (item) => item.id === shareId,
  );

  return (
    <div className="flex flex-col gap-4" data-testid="abdm-profile-share">
      {isLoading ? (
        <Skeleton className="h-40 w-full" />
      ) : !share?.profile ? (
        <Alert variant="destructive" className="border-red-200 bg-red-50">
          <AlertDescription>
            {t(
              isError
                ? "abdm_profile_share_load_failed"
                : "abdm_profile_share_not_found",
            )}
          </AlertDescription>
        </Alert>
      ) : (
        <>
          <p className="text-sm text-gray-700">
            {share.token_number != null
              ? t("abdm_profile_share_token", { token: share.token_number })
              : t("abdm_profile_share_shared")}
          </p>
          <AbhaProfileCard profile={share.profile}>
            {share.patient ? (
              <AbhaExistingPatientAlert
                patient={{ ...share.patient, can_view: true }}
                facilityId={facilityId}
              />
            ) : (
              <Button
                type="button"
                onClick={() =>
                  onUse({
                    profile: share.profile!,
                    link: { profile_share: share.id },
                  })
                }
                data-testid="abdm-use-for-registration"
              >
                {t("abdm_use_for_registration")}
              </Button>
            )}
          </AbhaProfileCard>
        </>
      )}
      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-gray-200 pt-3">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={onVerifyInstead}
        >
          {t("abdm_verify_different_abha")}
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={onSkip}
          data-testid="abdm-exit"
        >
          {t("abdm_continue_without_abha")}
        </Button>
      </div>
    </div>
  );
}

