import { IdCardIcon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import { RegistrationAbhaState } from "@/components/Abdm/registration";

/**
 * Sits above the registration form: says which ABHA will be linked when the
 * patient is registered, or offers to add one if the user skipped the step.
 */
export function AbhaRegistrationBanner({
  abha,
  onChange,
  onRemove,
}: {
  abha: RegistrationAbhaState | null;
  onChange: () => void;
  onRemove: () => void;
}) {
  const { t } = useTranslation();

  if (!abha) {
    return (
      <div
        className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-gray-200 bg-white px-4 py-3 text-sm text-gray-700"
        data-testid="abdm-registration-no-abha"
      >
        <span>{t("abdm_registration_without_abha")}</span>
        <Button type="button" variant="outline" size="sm" onClick={onChange}>
          <IdCardIcon />
          {t("abdm_add_abha")}
        </Button>
      </div>
    );
  }

  const { profile } = abha;

  return (
    <div
      className="flex flex-col gap-3 rounded-md border border-primary-200 bg-primary-50 p-4 sm:flex-row sm:items-start sm:justify-between"
      data-testid="abdm-registration-abha"
    >
      <div className="flex items-start gap-3">
        <IdCardIcon className="mt-0.5 size-5 shrink-0 text-primary-700" />
        <div className="flex flex-col gap-1 text-sm">
          <p className="flex flex-wrap items-center gap-2 font-semibold text-gray-900">
            {t("abdm_registration_abha_selected", {
              abha: profile.abha_number ?? profile.abha_address,
            })}
            {profile.kyc_verified && (
              <Badge variant="green" size="sm">
                {t("abdm_kyc_verified")}
              </Badge>
            )}
          </p>
          <p className="text-gray-700">
            {t("abdm_registration_link_on_register")}
          </p>
          {abha.locked && (
            <p className="text-gray-700">
              {t("abdm_registration_locked_fields")}
            </p>
          )}
        </div>
      </div>
      <div className="flex shrink-0 flex-wrap gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={onChange}
          data-testid="abdm-change-abha"
        >
          {t("abdm_change_abha")}
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={onRemove}
          data-testid="abdm-remove-abha"
        >
          {t("abdm_remove_abha")}
        </Button>
      </div>
    </div>
  );
}

