import { useMutation, useQuery } from "@tanstack/react-query";
import { Loader2Icon } from "lucide-react";
import { FormEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbdmField } from "@/components/Abdm/AbdmField";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import { AbhaFlowNotice } from "@/components/Abdm/types";
import {
  abdmSilent,
  getAbhaAddressSuffix,
  getNewAbhaAddressError,
  stripAbhaAddressSuffix,
} from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import {
  AbhaExistingPatient,
  AbhaProfile,
  AbhaTransactionProfile,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

/** Picks or types an ABHA address for a newly created ABHA. */
export function AddressStep({
  transactionId,
  profile,
  required,
  existingPatient,
  isNew,
  notice,
}: {
  transactionId: string;
  profile: AbhaProfile;
  required: boolean;
  existingPatient: AbhaExistingPatient | null;
  isNew: boolean;
  notice?: AbhaFlowNotice;
}) {
  const { t } = useTranslation();
  const { config, finish, restart } = useAbhaFlow();
  const suffix = getAbhaAddressSuffix(config);

  const [address, setAddress] = useState("");
  const [showErrors, setShowErrors] = useState(false);

  const suggestionsQuery = useQuery({
    queryKey: ["abdm", "address-suggestions", transactionId],
    queryFn: query(abdmApi.addressSuggestions, {
      queryParams: { transaction_id: transactionId },
      silent: abdmSilent,
    }),
    retry: false,
    staleTime: Infinity,
  });

  const createMutation = useMutation({
    mutationFn: mutate(abdmApi.createAddress, { silent: abdmSilent }),
    onSuccess: (data: AbhaTransactionProfile) =>
      finish(
        {
          transactionId: data.transaction_id,
          profile: data.profile,
          existingPatient,
          isNew,
        },
        notice,
      ),
  });

  const value = stripAbhaAddressSuffix(address);
  const validationKey = getNewAbhaAddressError(value);
  const fieldError =
    showErrors && validationKey ? t(validationKey) : undefined;

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (validationKey || createMutation.isPending) return;
    createMutation.mutate({ transaction_id: transactionId, abha_address: value });
  };

  const suggestions = suggestionsQuery.data?.suggestions ?? [];

  return (
    <StepLayout
      title={t("abdm_address_title")}
      description={
        required
          ? t("abdm_address_description_required")
          : t("abdm_address_description_optional")
      }
      testId="abdm-step-address"
    >
      {notice === "abha_exists" && (
        <Alert className="border-primary-200 bg-primary-50">
          <AlertDescription className="text-gray-800">
            {t("abdm_notice__abha_exists")}
          </AlertDescription>
        </Alert>
      )}
      {profile.abha_address && (
        <div className="flex flex-col gap-1 rounded-md border border-gray-200 bg-gray-50 p-3">
          <span className="text-xs text-gray-500">
            {t("abdm_current_abha_address")}
          </span>
          <span
            className="font-medium break-all text-gray-900"
            data-testid="abdm-current-abha-address"
          >
            {profile.abha_address}
          </span>
        </div>
      )}
      <form className="flex flex-col gap-4" onSubmit={handleSubmit} noValidate>
        <div className="flex flex-col gap-2">
          <p className="text-sm font-medium text-gray-900">
            {t("abdm_address_suggestions")}
          </p>
          {suggestionsQuery.isLoading ? (
            <div className="flex flex-wrap gap-2">
              <Skeleton className="h-8 w-28" />
              <Skeleton className="h-8 w-24" />
              <Skeleton className="h-8 w-32" />
            </div>
          ) : suggestions.length ? (
            <div
              className="flex flex-wrap gap-2"
              role="group"
              aria-label={t("abdm_address_suggestions")}
            >
              {suggestions.map((suggestion) => (
                <button
                  key={suggestion}
                  type="button"
                  aria-pressed={value === suggestion}
                  className={cn(
                    "rounded-full border px-3 py-1 text-sm transition-colors focus-visible:ring-2 focus-visible:ring-primary-500 focus-visible:outline-none",
                    value === suggestion
                      ? "border-primary-500 bg-primary-50 text-primary-900"
                      : "border-gray-300 bg-white text-gray-800 hover:border-primary-400",
                  )}
                  onClick={() => {
                    setAddress(suggestion);
                    createMutation.reset();
                  }}
                  data-testid="abdm-address-suggestion"
                >
                  {suggestion}
                  {suffix}
                </button>
              ))}
            </div>
          ) : (
            <p className="text-sm text-gray-500">
              {t("abdm_address_no_suggestions")}
            </p>
          )}
        </div>

        <AbdmField
          label={t("abha_address")}
          suffix={suffix}
          placeholder={t("abdm_abha_address_placeholder")}
          value={address}
          onChange={(e) => {
            setAddress(e.target.value.trim());
            createMutation.reset();
          }}
          hint={t("abdm_address_rules")}
          error={fieldError}
          data-testid="abdm-address-input"
        />

        {createMutation.error && (
          <AbdmErrorAlert error={createMutation.error} onRestart={restart} />
        )}

        <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
          {!required && (
            <Button
              type="button"
              variant="outline"
              disabled={createMutation.isPending}
              onClick={() =>
                finish(
                  { transactionId, profile, existingPatient, isNew },
                  notice,
                )
              }
              data-testid="abdm-address-skip"
            >
              {t("abdm_address_skip")}
            </Button>
          )}
          <Button
            type="submit"
            variant="primary"
            disabled={createMutation.isPending}
            data-testid="abdm-address-submit"
          >
            {createMutation.isPending && (
              <Loader2Icon className="animate-spin" />
            )}
            {t("abdm_address_create")}
          </Button>
        </div>
      </form>
    </StepLayout>
  );
}
