/** Verifies the communication mobile when it differs from Aadhaar's mobile. */
export function CreateMobileStep({
  created,
  mobile,
  otpSent: initialOtpSent,
  sendError,
}: {
  created: AbhaCreateVerified;
  mobile: string;
  otpSent: AbhaOtpSent | null;
  sendError?: unknown;
}) {
  const { t } = useTranslation();
  const { config, goTo, finish, restart } = useAbhaFlow();
  const [otpSent, setOtpSent] = useState(initialOtpSent);
  const [otp, setOtp] = useState("");

  const sendMutation = useMutation({
    mutationFn: mutate(abdmApi.createMobileOtp, { silent: abdmSilent }),
    onSuccess: (data: AbhaOtpSent) => setOtpSent(data),
  });

  const verifyMutation = useMutation({
    mutationFn: mutate(abdmApi.createMobileVerify, { silent: abdmSilent }),
    onSuccess: ({ transaction_id, profile }: AbhaTransactionProfile) => {
      if (created.abha_address_required) {
        goTo({
          name: "address",
          transactionId: transaction_id,
          existingPatient: created.existing_patient,
          isNew: true,
        });
        return;
      }
      finish({
        transactionId: transaction_id,
        profile,
        existingPatient: created.existing_patient,
        isNew: true,
      });
    },
  });

  const isComplete = otp.length === config.otp.length;

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    if (!otpSent || !isComplete || verifyMutation.isPending) return;
    verifyMutation.mutate({ transaction_id: otpSent.transaction_id, otp });
  };

  const sendFailure = sendMutation.error ?? (!otpSent ? sendError : null);

  return (
    <StepLayout
      title={t("abdm_verify_mobile_title")}
      description={t("abdm_verify_mobile_description", {
        mobile: `+91 ${mobile}`,
      })}
      testId="abdm-step-create-mobile"
    >
      {otpSent ? (
        <form
          className="flex flex-col gap-4"
          onSubmit={handleSubmit}
          noValidate
        >
          <AbhaOtpInput
            otpSent={otpSent}
            onOtpSentChange={setOtpSent}
            otpLength={config.otp.length}
            value={otp}
            onChange={(next) => {
              setOtp(next);
              if (verifyMutation.error) verifyMutation.reset();
            }}
            disabled={verifyMutation.isPending}
            onRestart={restart}
          />
          {verifyMutation.error && (
            <AbdmErrorAlert error={verifyMutation.error} onRestart={restart} />
          )}
          <div className="flex justify-end">
            <Button
              type="submit"
              variant="primary"
              disabled={!isComplete || verifyMutation.isPending}
              data-testid="abdm-create-mobile-submit"
            >
              {verifyMutation.isPending && (
                <Loader2Icon className="animate-spin" />
              )}
              {t("verify")}
            </Button>
          </div>
        </form>
      ) : (
        <>
          {sendFailure ? (
            <AbdmErrorAlert error={sendFailure} onRestart={restart} />
          ) : null}
          <div className="flex justify-end">
            <Button
              type="button"
              variant="primary"
              disabled={sendMutation.isPending}
              onClick={() =>
                sendMutation.mutate({
                  transaction_id: created.transaction_id,
                  mobile,
                })
              }
              data-testid="abdm-create-mobile-send"
            >
              {sendMutation.isPending ? (
                <Loader2Icon className="animate-spin" />
              ) : (
                <SendIcon />
              )}
              {t("abdm_send_otp")}
            </Button>
          </div>
        </>
      )}
    </StepLayout>
  );
}
