import { useMutation } from "@tanstack/react-query";
import { CheckCircle2Icon, Loader2Icon, SendIcon } from "lucide-react";
import { FormEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbdmField } from "@/components/Abdm/AbdmField";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { AbhaOtpInput } from "@/components/Abdm/AbhaOtpInput";
import { AbhaFlowResult } from "@/components/Abdm/types";
import { abdmSilent, isValidMobile } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { AbhaOtpSent, AbhaProfile } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

/**
 * Changes the mobile number on a verified ABHA. Runs as the result action of
 * the identify flow, so the patient has just proven they hold the ABHA; the
 * new number is then confirmed with its own OTP.
 */
export function AbhaUpdateMobile({
  result,
  patientMobile,
  onUpdated,
  onDone,
}: {
  result: AbhaFlowResult;
  /** The patient record's mobile, offered as the new number. */
  patientMobile?: string;
  onUpdated?: (profile: AbhaProfile) => void;
  onDone: () => void;
}) {
  const { t } = useTranslation();
  const { config, restart } = useAbhaFlow();
  const currentMobile = result.profile.mobile;

  const [mobile, setMobile] = useState(() =>
    patientMobile && patientMobile !== currentMobile ? patientMobile : "",
  );
  const [showErrors, setShowErrors] = useState(false);
  const [otpSent, setOtpSent] = useState<AbhaOtpSent | null>(null);
  const [otp, setOtp] = useState("");
  const [updated, setUpdated] = useState<AbhaProfile | null>(null);

  const sendMutation = useMutation({
    mutationFn: mutate(abdmApi.profileMobileOtp, { silent: abdmSilent }),
    onSuccess: (data: AbhaOtpSent) => {
      setOtp("");
      setOtpSent(data);
    },
  });

  const verifyMutation = useMutation({
    mutationFn: mutate(abdmApi.profileMobileVerify, { silent: abdmSilent }),
    onSuccess: ({ profile }: { profile: AbhaProfile }) => {
      setUpdated(profile);
      onUpdated?.(profile);
    },
  });

  const mobileError = !isValidMobile(mobile)
    ? t("abdm_validation__mobile")
    : mobile === currentMobile
      ? t("abdm_update_mobile_same")
      : undefined;

  const handleSend = (event: FormEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (mobileError || sendMutation.isPending) return;
    sendMutation.mutate({ transaction_id: result.transactionId, mobile });
  };

  const handleVerify = (event: FormEvent) => {
    event.preventDefault();
    if (!otpSent || otp.length !== config.otp.length) return;
    if (verifyMutation.isPending) return;
    verifyMutation.mutate({ transaction_id: otpSent.transaction_id, otp });
  };

  if (updated) {
    return (
