              .length > 0 && (
              <AbhaDetail
                label={t("abdm_other_abha_addresses")}
                testId="patient-abha-other-addresses"
                value={
                  <span className="break-all">
                    {link.abha_addresses
                      .filter((a) => a !== link.abha_address)
                      .join(", ")}
                  </span>
                }
              />
            )}
            <AbhaDetail
              label={t("abdm_kyc")}
              testId="patient-abha-kyc"
              value={
                link.kyc_verified ? (
                  <Badge variant="green">
                    <BadgeCheckIcon className="size-3" />
                    {t("abha_kyc_verified")}
                  </Badge>
                ) : (
                  <Badge variant="yellow">{t("abha_kyc_not_verified")}</Badge>
                )
              }
            />
            <AbhaDetail
              label={t("abdm_link_source")}
              testId="patient-abha-source"
              value={[
                t(`abdm_link_source__${link.source}`),
                link.verification_method &&
                  t(`abdm_verification_method__${link.verification_method}`, {
                    defaultValue: humanize(link.verification_method),
                  }),
              ]
                .filter(Boolean)
                .join(" · ")}
            />
            <AbhaDetail
              label={t("abdm_linked_by")}
              testId="patient-abha-linked-by"
              value={
                link.linked_by
                  ? `${formatName(link.linked_by)} · ${formatDateTime(link.linked_at)}`
                  : formatDateTime(link.linked_at)
              }
            />
          </dl>
          <div className="flex flex-wrap gap-2">
            {verifyIdentifier && (
