import { useMutation } from "@tanstack/react-query";
import { Loader2Icon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { ProvenanceHint } from "@/components/Abdm/ProvenanceHint";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import { AbhaVerifyIdentifierType } from "@/components/Abdm/types";
import { abdmSilent, isAbdmErrorType } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { AbhaOtpSent, AbhaOtpSystem } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const OTP_SYSTEMS: AbhaOtpSystem[] = ["aadhaar", "abdm"];

export function AuthMethodStep({
  identifierType,
  value,
  canGoBack,
}: {
  identifierType: AbhaVerifyIdentifierType;
  value: string;
  canGoBack: boolean;
}) {
  const { t } = useTranslation();
  const { facilityId, facts, goTo } = useAbhaFlow();
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem>("abdm");

  const fact = facts[identifierType];

  const otpMutation = useMutation({
    mutationFn: mutate(abdmApi.requestOtp, { silent: abdmSilent }),
    onSuccess: (otpSent: AbhaOtpSent) =>
      goTo({ name: "otp", otpSent, identifierType, value }),
    onError: (error) => {
      if (isAbdmErrorType(error, "abha_not_found")) {
        goTo({ name: "not_found", identifierType, value });
      }
    },
  });

  return (
    <StepLayout
      title={t("abdm_auth_method_title")}
      description={t("abdm_auth_method_description")}
      onBack={
        canGoBack
          ? () => goTo({ name: "identifier", identifierType })
          : undefined
      }
      testId="abdm-step-auth-method"
      footer={
        <Button
          type="button"
          variant="primary"
          disabled={otpMutation.isPending}
          onClick={() =>
            otpMutation.mutate({
              identifier_type: identifierType,
              value,
              otp_system: otpSystem,
              facility: facilityId,
            })
          }
          data-testid="abdm-auth-method-submit"
        >
          {otpMutation.isPending && <Loader2Icon className="animate-spin" />}
          {t("abdm_send_otp")}
        </Button>
      }
    >
      <div className="flex flex-col gap-1 rounded-md border border-gray-200 bg-gray-50 p-3">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-xs text-gray-500">
            {t(identifierType === "abha_number" ? "abha_number" : "abha_address")}
          </span>
          {fact && fact.value === value && (
            <ProvenanceHint
              provenance={fact.provenance}
              field={identifierType}
            />
          )}
        </div>
        <span
          className="font-medium break-all text-gray-900"
          data-testid="abdm-auth-method-identifier"
        >
          {value}
        </span>
      </div>

      <RadioGroup
        value={otpSystem}
        onValueChange={(next) => setOtpSystem(next as AbhaOtpSystem)}
        aria-label={t("abdm_auth_method_title")}
        className="gap-2"
      >
        {OTP_SYSTEMS.map((system) => (
          <Label
            key={system}
            htmlFor={`abdm-otp-system-${system}`}
            className="flex cursor-pointer items-start gap-3 rounded-md border border-gray-200 p-3 font-normal has-[button[data-state=checked]]:border-primary-500 has-[button[data-state=checked]]:bg-primary-50"
          >
            <RadioGroupItem
              id={`abdm-otp-system-${system}`}
              value={system}
              className="mt-0.5"
              data-testid={`abdm-otp-system-${system}`}
            />
            <span className="flex flex-col gap-1">
              <span className="text-sm font-medium text-gray-900">
                {t(`abdm_otp_system__${system}`)}
              </span>
              <span className="text-xs leading-snug text-gray-600">
                {t(`abdm_otp_system__${system}_description`)}
              </span>
            </span>
          </Label>
        ))}
      </RadioGroup>

      {otpMutation.error &&
        !isAbdmErrorType(otpMutation.error, "abha_not_found") && (
          <AbdmErrorAlert error={otpMutation.error} />
        )}
    </StepLayout>
  );
}
