import json,re,glob,os
en=json.load(open("public/locale/en.json"))
files=glob.glob("src/components/Abdm/**/*.ts*",recursive=True)+["src/components/Patient/PatientRegistration.tsx","src/components/Patient/PatientDetailsTab/Demography.tsx","src/hooks/useAbdmConfig.ts"]
keys=set(); templ=set()
for f in files:
    s=open(f).read()
    for m in re.finditer(r'\bt\(\s*"([^"]+)"',s): keys.add(m.group(1))
    for m in re.finditer(r'\bt\(\s*`([^`]+)`',s): templ.add((f.split('/')[-1],m.group(1)))
    for m in re.finditer(r'"((?:abdm|abha)_[a-z0-9_]+)"',s): keys.add(m.group(1))
    # ternary inside t(
    for m in re.finditer(r'\bt\(\s*\n?\s*[^,()]*\?\s*"([^"]+)"\s*:\s*"([^"]+)"',s): keys.update([m.group(1),m.group(2)])
def has(k):
    return k in en or (k+"_one") in en or (k+"_other") in en
missing=sorted(k for k in keys if not has(k))
print("MISSING", len(missing))
for k in missing: print(" ",k)
print("TEMPLATES")
for f,tp in sorted(templ): print(" ",f,tp)
EOF

