import { TFunction } from "i18next";

import { Fact, FactKey } from "@/components/Abdm/types";

import { HTTPError } from "@/Utils/request/types";
import { AbdmError, AbhaFile } from "@/types/abdm/abdm";

/**
 * ABDM requests render their errors inline on the step in view, so the global
 * toast handler is silenced for them. A 401 still reaches the global handler,
 * because it means the CARE session (not ABDM) has expired.
 */
export const abdmSilent = (res: Response) => res.status !== 401;

export function getAbdmError(error: unknown): AbdmError | undefined {
  if (!(error instanceof HTTPError)) {
    return undefined;
  }
  const errors = (error.cause as { errors?: unknown } | undefined)?.errors;
  if (Array.isArray(errors) && errors.length > 0) {
