    useAbhaFlow();

  const [aadhaar, setAadhaar] = useState(() => facts.aadhaar?.value ?? "");
  const [consented, setConsented] = useState(() => !!facts.aadhaar);
  const [showErrors, setShowErrors] = useState(false);

  const startMutation = useMutation({
    mutationFn: async (value: string) => {
      try {
        const otpSent = await callApi(abdmApi.requestOtp, {
          body: {
            identifier_type: "aadhaar",
            value,
            consent,
            facility: facilityId,
          },
          silent: abdmSilent,
        });
        return { exists: true, otpSent };
      } catch (error) {
        if (!isAbdmErrorType(error, "abha_not_found")) throw error;
        const otpSent = await callApi(abdmApi.createOtp, {
          body: { aadhaar: value, consent, facility: facilityId },
          silent: abdmSilent,
        });
        return { exists: false, otpSent };
      }
    },
    onSuccess: ({ exists, otpSent }, value) => {
      if (exists) {
        goTo({
          name: "otp",
          otpSent,
          identifierType: "aadhaar",
          value,
          notice: "abha_exists",
          backTo: "create_aadhaar",
        });
      } else {
        goTo({ name: "create_otp", otpSent });
      }
    },
  });

  const fieldError =
    showErrors && !isValidAadhaar(aadhaar)
      ? t("abdm_validation__aadhaar")
      : undefined;

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (!consented || !isValidAadhaar(aadhaar) || startMutation.isPending) {
      return;
    }
    rememberFact("aadhaar", aadhaar);
    startMutation.mutate(aadhaar);
  };

  return (
    <StepLayout
      title={t("abdm_create_title")}
      description={t("abdm_create_aadhaar_description")}
      onBack={onBack}
      testId="abdm-step-create-aadhaar"
    >
      <form className="flex flex-col gap-4" onSubmit={handleSubmit} noValidate>
        <AadhaarConsentInput
          value={aadhaar}
          onChange={(value) => {
            setAadhaar(value);
            if (facts.aadhaar && value !== facts.aadhaar.value) {
              setConsented(false);
            }
          }}
          consented={consented}
          onConsentChange={setConsented}
          consent={config.consent}
          error={fieldError}
          provenance={
