import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";

import query from "@/Utils/request/query";
import { AbdmConfig } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const DEFAULT_OTP_POLICY: AbdmConfig["otp"] = {
  length: 6,
  resend_wait_seconds: 60,
  max_resends: 2,
};

/**
 * Reads the deployment's ABDM configuration.
 *
 * Everything ABHA-related in the UI is gated on `enabled`. When the backend
 * has ABDM turned off, does not know the endpoint, or cannot be reached, the
 * hook reports `enabled: false` and CARE behaves exactly as it did before.
 */
export function useAbdmConfig() {
  const { data, isLoading } = useQuery({
    queryKey: ["abdm", "config"],
    queryFn: query(abdmApi.getConfig, { silent: true }),
    staleTime: 5 * 60 * 1000,
    retry: false,
  });

  const config = useMemo<AbdmConfig | undefined>(
    () =>
      data?.enabled
        ? { ...data, otp: { ...DEFAULT_OTP_POLICY, ...data.otp } }
        : undefined,
    [data],
  );

  return { config, enabled: !!config, isLoading };
}
import { TFunction } from "i18next";

import { Fact, FactKey } from "@/components/Abdm/types";

import { HTTPError } from "@/Utils/request/types";
import { AbdmError, AbhaFile } from "@/types/abdm/abdm";

/**
 * ABDM requests render their errors inline on the step in view, so the global
 * toast handler is silenced for them. A 401 still reaches the global handler,
 * because it means the CARE session (not ABDM) has expired.
 */
export const abdmSilent = (res: Response) => res.status !== 401;

export function getAbdmError(error: unknown): AbdmError | undefined {
  if (!(error instanceof HTTPError)) {
    return undefined;
  }
  const errors = (error.cause as { errors?: unknown } | undefined)?.errors;
  if (Array.isArray(errors) && errors.length > 0) {
    const first = errors[0];
    if (first && typeof first === "object" && "type" in first) {
      return first as AbdmError;
    }
  }
  return undefined;
}

export function isAbdmErrorType(error: unknown, ...types: string[]) {
  const type = getAbdmError(error)?.type;
  return !!type && types.includes(type);
}

/** Errors after which the current ABDM transaction cannot continue. */
export const RESTART_ERROR_TYPES = [
  "transaction_expired",
  "transaction_not_found",
  "invalid_state",
  "abdm_session_expired",
];

