import { PrinterIcon } from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import {
  FacilityAbdmCounter,
  FacilityAbdmShareUrl,
} from "@/types/abdm/abdm";

interface CounterShareQrCodesProps {
  counters: FacilityAbdmCounter[];
  shareUrls: FacilityAbdmShareUrl[];
  facilityName?: string;
  /** The form has changes that the codes shown here do not reflect yet. */
  hasUnsavedChanges: boolean;
}

interface PrintRequest {
  share: FacilityAbdmShareUrl;
  /** Lets the same counter be printed twice in a row. */
  requestedAt: number;
}

/**
 * The "scan and share" QR code of each counter. A patient scans it with an
 * ABHA app to share their profile with this facility and gets a token number
 * for that counter's queue.
 */
export function CounterShareQrCodes({
  counters,
  shareUrls,
  facilityName,
  hasUnsavedChanges,
}: CounterShareQrCodesProps) {
  const { t } = useTranslation();
  const [printRequest, setPrintRequest] = useState<PrintRequest | null>(null);

  useEffect(() => {
    if (!printRequest) {
      return;
    }
    const clear = () => setPrintRequest(null);
    window.addEventListener("afterprint", clear);
    window.print();
    return () => window.removeEventListener("afterprint", clear);
  }, [printRequest]);

  const counterName = (code: string) =>
    counters.find((counter) => counter.code === code)?.name || code;

  return (
    <Card data-testid="abdm-share-qr-codes">
      <CardHeader>
        <CardTitle className="text-lg">{t("abdm_share_qr_title")}</CardTitle>
        <CardDescription>{t("abdm_share_qr_description")}</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        {hasUnsavedChanges && (
          <Alert className="border-yellow-200 bg-yellow-50">
            <AlertDescription className="text-yellow-900">
              {t("abdm_share_qr_unsaved")}
            </AlertDescription>
          </Alert>
        )}
        {shareUrls.length === 0 ? (
          <p className="text-sm text-gray-600">{t("abdm_share_qr_none")}</p>
        ) : (
          <ul className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {shareUrls.map((share) => (
              <li
                key={share.counter}
                className="flex flex-col items-center gap-3 rounded-md border border-gray-200 p-4 text-center"
                data-testid="abdm-share-qr"
                data-counter={share.counter}
              >
                <QRCodeSVG
                  value={share.url}
                  size={160}
                  level="M"
                  marginSize={2}
                  title={t("abdm_share_qr_alt", {
                    counter: counterName(share.counter),
                  })}
                  className="bg-white"
                />
                <div className="flex flex-col gap-0.5">
                  <span className="font-semibold text-gray-900">
                    {counterName(share.counter)}
                  </span>
                  <span className="font-mono text-xs text-gray-600">
                    {share.counter}
                  </span>
                </div>
                <p className="break-all text-xs text-gray-500">{share.url}</p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    setPrintRequest({ share, requestedAt: Date.now() })
                  }
                  aria-label={t("abdm_print_qr_for", {
                    counter: counterName(share.counter),
                  })}
                  data-testid="abdm-share-qr-print"
                >
                  <PrinterIcon />
                  {t("abdm_print_qr")}
                </Button>
              </li>
            ))}
          </ul>
        )}
      </CardContent>

      {printRequest && (
        // Hidden on screen; the print stylesheet shows only #multi-print.
        <div
          id="multi-print"
          className="hidden"
          data-testid="abdm-share-qr-poster"
        >
          <div className="mx-auto flex max-w-xl flex-col items-center gap-6 px-8 py-12 text-center">
            {facilityName && (
              <p className="text-lg text-gray-700">{facilityName}</p>
            )}
            <h1 className="text-3xl font-bold text-gray-900">
              {t("abdm_share_poster_title")}
            </h1>
            <QRCodeSVG
              value={printRequest.share.url}
              size={320}
              level="M"
              marginSize={4}
              className="bg-white"
            />
            <p className="text-2xl font-semibold text-gray-900">
              {t("abdm_share_poster_counter", {
                counter: counterName(printRequest.share.counter),
              })}
            </p>
            <ol className="list-decimal space-y-2 pl-6 text-left text-lg text-gray-800">
              <li>{t("abdm_share_poster_step_1")}</li>
              <li>{t("abdm_share_poster_step_2")}</li>
              <li>{t("abdm_share_poster_step_3")}</li>
            </ol>
          </div>
        </div>
      )}
    </Card>
  );
}

