          data-testid="abdm-facility-form"
        >
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">{t("abdm_hip_details")}</CardTitle>
              <CardDescription>
                {t("abdm_hip_details_description")}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <fieldset
                disabled={!canEdit || isPending}
                className="flex flex-col gap-6"
              >
                {!canEdit && (
                  <Alert>
                    <AlertDescription>
                      {t("abdm_facility_settings_read_only")}
                    </AlertDescription>
                  </Alert>
                )}
                <div className="grid gap-4 md:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="hip_id"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel aria-required>{t("abdm_hip_id")}</FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            autoComplete="off"
                            data-testid="abdm-hip-id"
                          />
                        </FormControl>
                        <FormDescription>
                          {t("abdm_hip_id_description")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="hip_name"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel aria-required>
                          {t("abdm_hip_name")}
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            autoComplete="off"
                            data-testid="abdm-hip-name"
                          />
                        </FormControl>
                        <FormDescription>
                          {t("abdm_hip_name_description")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
