                                >
                                  {t("abdm_counter_code")}
                                </FormLabel>
                                <FormControl>
                                  <Input
                                    {...field}
                                    autoComplete="off"
                                    maxLength={20}
                                    placeholder={t(
                                      "abdm_counter_code_placeholder",
                                    )}
                                    data-testid="abdm-counter-code"
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={form.control}
                            name={`counters.${index}.name`}
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel
                                  aria-required
                                  className={index > 0 ? "sr-only" : undefined}
                                >
                                  {t("abdm_counter_name")}
                                </FormLabel>
                                <FormControl>
                                  <Input
                                    {...field}
                                    autoComplete="off"
                                    placeholder={t(
                                      "abdm_counter_name_placeholder",
                                    )}
                                    data-testid="abdm-counter-name"
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          {canEdit && (
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className={index === 0 ? "mt-[1.375rem]" : ""}
                              onClick={() => remove(index)}
                              aria-label={t("abdm_remove_counter", {
                                counter:
                                  form.getValues(`counters.${index}.code`) ||
                                  index + 1,
                              })}
                              data-testid="abdm-counter-remove"
                            >
                              <Trash2Icon className="text-red-600" />
                            </Button>
                          )}
                        </li>
                      ))}
                    </ul>
                  )}

                  {canEdit && (
                    <div>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => append({ code: "", name: "" })}
                        data-testid="abdm-counter-add"
                      >
