                        variant="outline"
                        size="sm"
                        onClick={() => append({ code: "", name: "" })}
                        data-testid="abdm-counter-add"
                      >
                        <PlusIcon />
                        {t("abdm_add_counter")}
                      </Button>
                    </div>
                  )}
                </section>

                <AbdmErrorAlert error={saveError} />

                {canEdit && (
                  <div className="flex justify-end gap-3">
                    <Button
                      type="button"
                      variant="outline"
                      disabled={!isDirty || isPending}
                      onClick={() => {
                        setSaveError(null);
                        form.reset();
                      }}
                    >
                      {t("cancel")}
