import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { PlusIcon, Trash2Icon } from "lucide-react";
import { useMemo, useState } from "react";
import { FieldPath, useFieldArray, useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { abdmSilent } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { HTTPError } from "@/Utils/request/types";
import { AbdmError, FacilityAbdmConfig } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

import { CounterShareQrCodes } from "./CounterShareQrCodes";

/** ABDM allows 1 to 20 letters or digits for a counter id. */
const COUNTER_CODE_PATTERN = /^[A-Za-z0-9]{1,20}$/;

/** Server error locations that map onto a field of this form. */
const FIELD_PATH_PATTERN = /^(hip_id|hip_name|counters(\.\d+\.(code|name))?)$/;

interface FormValues {
  hip_id: string;
  hip_name: string;
  counters: { code: string; name: string }[];
}

function toFormValues(
  config: FacilityAbdmConfig,
  defaultHipName?: string,
): FormValues {
  if (!config.configured) {
    return { hip_id: "", hip_name: defaultHipName ?? "", counters: [] };
  }
  return {
    hip_id: config.hip_id,
    hip_name: config.hip_name,
    counters: config.counters.map(({ code, name }) => ({ code, name })),
  };
}

interface FacilityAbdmConfigFormProps {
  facilityId: string;
  config: FacilityAbdmConfig;
  facilityName?: string;
  canEdit: boolean;
}

/** The facility's HIP details and counters, and each counter's share QR. */
export function FacilityAbdmConfigForm({
  facilityId,
  config,
  facilityName,
  canEdit,
}: FacilityAbdmConfigFormProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [saveError, setSaveError] = useState<unknown>(null);

  const schema = useMemo(
    () =>
      z
        .object({
          hip_id: z.string().trim().min(1, t("field_required")),
          hip_name: z.string().trim().min(1, t("field_required")),
          counters: z.array(
            z.object({
              code: z
                .string()
                .trim()
                .min(1, t("field_required"))
                .regex(COUNTER_CODE_PATTERN, t("abdm_counter_code_invalid")),
              name: z.string().trim().min(1, t("field_required")),
            }),
          ),
        })
        .superRefine((values, ctx) => {
          const reserved = [values.hip_id, values.hip_name].map((value) =>
            value.trim().toLowerCase(),
          );
          const seen = new Set<string>();
          values.counters.forEach((counter, index) => {
            const code = counter.code.trim().toLowerCase();
            if (!code) {
              return;
            }
            if (seen.has(code)) {
              ctx.addIssue({
                code: "custom",
                path: ["counters", index, "code"],
                message: t("abdm_counter_code_duplicate"),
              });
            } else if (reserved.includes(code)) {
              ctx.addIssue({
                code: "custom",
                path: ["counters", index, "code"],
                message: t("abdm_counter_code_not_hip"),
              });
            }
            seen.add(code);
          });
        }),
    [t],
  );

  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: toFormValues(config, facilityName),
  });
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "counters",
  });

  const { mutate: save, isPending } = useMutation({
    mutationFn: mutate(abdmApi.updateFacilityConfig, {
      pathParams: { facilityId },
      silent: abdmSilent,
    }),
    onSuccess: (saved: FacilityAbdmConfig) => {
      setSaveError(null);
      queryClient.setQueryData(["abdm", "facility", facilityId], saved);
      form.reset(toFormValues(saved, facilityName));
      toast.success(t("abdm_facility_settings_saved"));
    },
    onError: (error: unknown) => {
      // Errors that name a field are shown on that field; the rest above.
      const errors =
        error instanceof HTTPError
          ? ((error.cause as { errors?: AbdmError[] } | undefined)?.errors ??
            [])
          : [];
      const unplaced = errors.filter((item) => {
        const path = (item.loc ?? [])
          .filter((part) => part !== "body")
          .join(".");
        if (!FIELD_PATH_PATTERN.test(path)) {
          return true;
        }
        form.setError(path as FieldPath<FormValues>, { message: item.msg });
        return false;
      });
      setSaveError(errors.length && !unplaced.length ? null : error);
    },
  });

  const onSubmit = (values: FormValues) => {
    setSaveError(null);
    save({
      hip_id: values.hip_id.trim(),
      hip_name: values.hip_name.trim(),
      counters: values.counters.map((counter) => ({
        code: counter.code.trim(),
        name: counter.name.trim(),
      })),
    });
  };

  const isDirty = form.formState.isDirty;

  return (
    <div className="flex flex-col gap-6">
      <Form {...form}>
        <form
          onSubmit={form.handleSubmit(onSubmit)}
          noValidate
          data-testid="abdm-facility-form"
        >
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">{t("abdm_hip_details")}</CardTitle>
              <CardDescription>
                {t("abdm_hip_details_description")}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <fieldset
                disabled={!canEdit || isPending}
                className="flex flex-col gap-6"
              >
                {!canEdit && (
                  <Alert>
                    <AlertDescription>
                      {t("abdm_facility_settings_read_only")}
                    </AlertDescription>
                  </Alert>
                )}
                <div className="grid gap-4 md:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="hip_id"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel aria-required>{t("abdm_hip_id")}</FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            autoComplete="off"
                            data-testid="abdm-hip-id"
                          />
                        </FormControl>
                        <FormDescription>
                          {t("abdm_hip_id_description")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="hip_name"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel aria-required>
                          {t("abdm_hip_name")}
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            autoComplete="off"
                            data-testid="abdm-hip-name"
                          />
                        </FormControl>
                        <FormDescription>
                          {t("abdm_hip_name_description")}
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <section
                  className="flex flex-col gap-3"
                  aria-labelledby="abdm-counters-heading"
                >
                  <div className="flex flex-col gap-1">
                    <h3
                      id="abdm-counters-heading"
                      className="text-base font-semibold text-gray-900"
                    >
                      {t("abdm_counters")}
                    </h3>
                    <p className="text-sm text-gray-600">
                      {t("abdm_counters_description")}
                    </p>
                  </div>

                  {fields.length === 0 ? (
                    <p
                      className="rounded-md border border-dashed border-gray-300 p-4 text-sm text-gray-600"
                      data-testid="abdm-no-counters"
                    >
                      {t("abdm_no_counters")}
                    </p>
                  ) : (
                    <ul className="flex flex-col gap-3">
                      {fields.map((item, index) => (
                        <li
                          key={item.id}
                          className="grid grid-cols-[minmax(0,1fr)_minmax(0,2fr)_auto] items-start gap-3"
                          data-testid="abdm-counter-row"
                        >
                          <FormField
                            control={form.control}
                            name={`counters.${index}.code`}
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel
                                  aria-required
                                  className={index > 0 ? "sr-only" : undefined}
                                >
                                  {t("abdm_counter_code")}
                                </FormLabel>
                                <FormControl>
                                  <Input
                                    {...field}
                                    autoComplete="off"
                                    maxLength={20}
                                    placeholder={t(
                                      "abdm_counter_code_placeholder",
                                    )}
                                    data-testid="abdm-counter-code"
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          <FormField
                            control={form.control}
                            name={`counters.${index}.name`}
                            render={({ field }) => (
                              <FormItem>
                                <FormLabel
                                  aria-required
                                  className={index > 0 ? "sr-only" : undefined}
                                >
                                  {t("abdm_counter_name")}
                                </FormLabel>
                                <FormControl>
                                  <Input
                                    {...field}
                                    autoComplete="off"
                                    placeholder={t(
                                      "abdm_counter_name_placeholder",
                                    )}
                                    data-testid="abdm-counter-name"
                                  />
                                </FormControl>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                          {canEdit && (
                            <Button
                              type="button"
                              variant="ghost"
                              size="icon"
                              className={index === 0 ? "mt-[1.375rem]" : ""}
                              onClick={() => remove(index)}
                              aria-label={t("abdm_remove_counter", {
                                counter:
                                  form.getValues(`counters.${index}.code`) ||
                                  index + 1,
                              })}
                              data-testid="abdm-counter-remove"
                            >
                              <Trash2Icon className="text-red-600" />
                            </Button>
                          )}
                        </li>
                      ))}
                    </ul>
                  )}

                  {canEdit && (
                    <div>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => append({ code: "", name: "" })}
                        data-testid="abdm-counter-add"
                      >
                        <PlusIcon />
                        {t("abdm_add_counter")}
                      </Button>
                    </div>
                  )}
                </section>

                <AbdmErrorAlert error={saveError} />

                {canEdit && (
                  <div className="flex justify-end gap-3">
                    <Button
                      type="button"
                      variant="outline"
                      disabled={!isDirty || isPending}
                      onClick={() => {
                        setSaveError(null);
                        form.reset();
                      }}
                    >
                      {t("cancel")}
                    </Button>
                    <Button
                      type="submit"
                      disabled={isPending || (config.configured && !isDirty)}
                      data-testid="abdm-facility-save"
                    >
                      {isPending ? t("saving") : t("save")}
                    </Button>
                  </div>
                )}
              </fieldset>
            </CardContent>
          </Card>
        </form>
      </Form>

      {config.configured && (
        <CounterShareQrCodes
          counters={config.counters}
          shareUrls={config.share_urls}
          facilityName={facilityName}
          hasUnsavedChanges={isDirty}
        />
      )}
    </div>
  );
}

