import { useQuery } from "@tanstack/react-query";
import dayjs from "dayjs";
import {
  ExternalLinkIcon,
  IdCardIcon,
  RefreshCwIcon,
  SettingsIcon,
  UserPlusIcon,
} from "lucide-react";
import { Link, navigate } from "raviger";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { DatePicker } from "@/components/ui/date-picker";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

import Page from "@/components/Common/Page";
import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { getPatientUrl } from "@/components/Abdm/AbhaExistingPatientAlert";
import { abdmSilent } from "@/components/Abdm/utils";

import { useAbdmConfig } from "@/hooks/useAbdmConfig";
import useFilters from "@/hooks/useFilters";

import query from "@/Utils/request/query";
import { dateQueryString, formatDateTime, parseLocalDate } from "@/Utils/utils";
import { getPermissions } from "@/common/Permissions";
import { usePermissions } from "@/context/PermissionContext";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import {
  AbhaProfileShare,
  AbhaProfileShareStatus,
  FacilityAbdmCounter,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const SHARE_STATUSES: AbhaProfileShareStatus[] = [
  "pending",
  "registered",
  "linked",
  "failed",
];

const STATUS_BADGE = {
  pending: "yellow",
  registered: "blue",
  linked: "green",
  failed: "destructive",
} as const satisfies Record<AbhaProfileShareStatus, string>;

/** New shares arrive while the desk watches the queue. */
const REFRESH_INTERVAL_MS = 30 * 1000;

const isShareStatus = (value: unknown): value is AbhaProfileShareStatus =>
  SHARE_STATUSES.includes(value as AbhaProfileShareStatus);

/**
 * Today's "scan and share" queue: patients who scanned a counter QR code and
 * shared their ABHA profile with this facility. The desk finds a patient by
 * the token number shown in their app and registers them from the profile.
 */
export default function AbhaShares({ facilityId }: { facilityId: string }) {
  const { t } = useTranslation();
  const { config: abdmConfig, isLoading: isAbdmConfigLoading } =
    useAbdmConfig();
  const { facility } = useCurrentFacility();
  const { hasPermission } = usePermissions();
  const { canCreatePatient } = getPermissions(
    hasPermission,
    facility?.permissions ?? [],
  );

  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 20,
    disableCache: true,
  });
  const today = dateQueryString(new Date());
  // Without a date the server answers with its own "today".
  const date: string | undefined =
    qParams.date && qParams.date !== today ? qParams.date : undefined;
  const status = isShareStatus(qParams.status) ? qParams.status : undefined;
  const page = Number(qParams.page) || 1;

  const { data: facilityConfig } = useQuery({
    queryKey: ["abdm", "facility", facilityId],
    queryFn: query(abdmApi.getFacilityConfig, {
      pathParams: { facilityId },
      silent: true,
    }),
    enabled: !!abdmConfig,
    retry: false,
  });

  const {
    data: response,
    isLoading,
    isFetching,
    error,
    refetch,
    dataUpdatedAt,
  } = useQuery({
    queryKey: ["abdm", "shares", facilityId, "queue", { date, status, page }],
    queryFn: query(abdmApi.listShares, {
      pathParams: { facilityId },
      queryParams: {
        ...(date && { date }),
        ...(status && { status }),
        limit: resultsPerPage,
        offset: (page - 1) * resultsPerPage,
      },
      silent: abdmSilent,
    }),
    enabled: !!abdmConfig,
    refetchInterval: date ? false : REFRESH_INTERVAL_MS,
    retry: false,
  });

  const counters = facilityConfig?.configured ? facilityConfig.counters : [];
  const shares = response?.results ?? [];

  const registerFromShare = (share: AbhaProfileShare) =>
    navigate(`/facility/${facilityId}/patient/create`, {
      query: { profile_share: share.id, ...(date && { share_date: date }) },
    });

  return (
    <Page title={t("abdm_abha_shares")} hideTitleOnPage>
      <div className="container mx-auto flex flex-col gap-4">
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-bold text-gray-700">
            {t("abdm_abha_shares")}
          </h1>
          <p className="text-sm text-gray-600">
            {t("abdm_abha_shares_description")}
          </p>
        </div>

        {isAbdmConfigLoading ? (
          <TableSkeleton count={5} />
        ) : !abdmConfig ? (
          <EmptyState
            icon={<IdCardIcon className="size-6 text-primary" />}
            title={t("abdm_not_enabled_title")}
            description={t("abdm_not_enabled_description")}
          />
        ) : (
          <>
            {facilityConfig && !facilityConfig.configured && (
              <Alert data-testid="abdm-shares-not-configured">
                <SettingsIcon />
                <AlertTitle>{t("abdm_shares_not_configured_title")}</AlertTitle>
                <AlertDescription>
                  <p>{t("abdm_shares_not_configured_description")}</p>
                  <Link
                    href={`/facility/${facilityId}/settings/abdm`}
                    className={cn(
                      buttonVariants({ variant: "outline", size: "sm" }),
                      "mt-1",
                    )}
                  >
                    {t("abdm_open_abdm_settings")}
                  </Link>
                </AlertDescription>
              </Alert>
            )}

            <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
              <Tabs
                value={status ?? "all"}
                onValueChange={(value) =>
                  updateQuery({ status: value === "all" ? undefined : value })
                }
              >
                <TabsList>
                  <TabsTrigger value="all">{t("all")}</TabsTrigger>
                  {SHARE_STATUSES.map((value) => (
                    <TabsTrigger
                      key={value}
                      value={value}
                      data-testid={`abdm-shares-status-${value}`}
                    >
                      {t(`abdm_share_status__${value}`)}
                    </TabsTrigger>
                  ))}
                </TabsList>
              </Tabs>
              <div className="flex flex-wrap items-center gap-2">
                <DatePicker
                  date={parseLocalDate(date ?? today)}
                  onChange={(value) =>
                    updateQuery({
                      date:
                        value && dateQueryString(value) !== today
                          ? dateQueryString(value)
                          : undefined,
                    })
                  }
                  disabled={(day) => day > new Date()}
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => refetch()}
                  disabled={isFetching}
                  data-testid="abdm-shares-refresh"
                >
                  <RefreshCwIcon className={cn(isFetching && "animate-spin")} />
                  {t("refresh")}
                </Button>
              </div>
            </div>

            {!!dataUpdatedAt && (
              <p className="text-xs text-gray-500">
                {date
                  ? t("abdm_shares_updated_at", {
                      time: formatDateTime(dataUpdatedAt, "hh:mm A"),
                    })
                  : t("abdm_shares_updated_at_live", {
                      time: formatDateTime(dataUpdatedAt, "hh:mm A"),
                    })}
              </p>
            )}

            {isLoading ? (
              <TableSkeleton count={5} />
            ) : error ? (
              <AbdmErrorAlert error={error} />
            ) : shares.length === 0 ? (
              <EmptyState
                icon={<IdCardIcon className="size-6 text-primary" />}
                title={t("abdm_shares_empty_title")}
                description={
                  date
                    ? t("abdm_shares_empty_day_description")
                    : t("abdm_shares_empty_today_description")
                }
              />
            ) : (
              <>
                <div className="grid gap-3 md:hidden">
                  {shares.map((share) => (
                    <Card key={share.id} data-testid="abdm-share-card">
                      <CardContent className="flex flex-col gap-3 p-4">
                        <div className="flex items-start justify-between gap-3">
                          <ShareToken share={share} counters={counters} />
                          <ShareStatus share={share} />
                        </div>
                        <SharePatient share={share} />
                        <ShareAbha share={share} />
                        <div className="flex items-center justify-between gap-2">
                          <span className="text-xs text-gray-500">
                            {formatDateTime(share.created_date, "hh:mm A")}
                          </span>
                          <ShareAction
                            share={share}
                            facilityId={facilityId}
                            canRegister={canCreatePatient}
                            onRegister={registerFromShare}
                          />
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
                <div className="hidden overflow-hidden rounded-lg border md:block">
                  <Table data-testid="abdm-shares-table">
                    <TableHeader className="bg-gray-100">
                      <TableRow>
                        <TableHead>{t("abdm_share_token")}</TableHead>
                        <TableHead>{t("patient")}</TableHead>
                        <TableHead>{t("abdm_share_abha")}</TableHead>
                        <TableHead>{t("abdm_share_shared_at")}</TableHead>
                        <TableHead>{t("status")}</TableHead>
                        <TableHead>
                          <span className="sr-only">{t("actions")}</span>
                        </TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody className="bg-white">
                      {shares.map((share) => (
                        <TableRow
                          key={share.id}
                          data-testid="abdm-share-row"
                          data-share-id={share.id}
                        >
                          <TableCell>
                            <ShareToken share={share} counters={counters} />
                          </TableCell>
                          <TableCell>
                            <SharePatient share={share} />
                          </TableCell>
                          <TableCell>
                            <ShareAbha share={share} />
                          </TableCell>
                          <TableCell className="whitespace-nowrap text-sm text-gray-700">
                            {formatDateTime(share.created_date, "hh:mm A")}
                          </TableCell>
                          <TableCell>
                            <ShareStatus share={share} />
                          </TableCell>
                          <TableCell className="text-right">
                            <ShareAction
                              share={share}
                              facilityId={facilityId}
                              canRegister={canCreatePatient}
                              onRegister={registerFromShare}
                            />
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
                {!!response && response.count > resultsPerPage && (
                  <div className="flex justify-center">
                    <Pagination totalCount={response.count} />
                  </div>
                )}
              </>
            )}
          </>
        )}
      </div>
    </Page>
  );
}

function ShareToken({
  share,
  counters,
}: {
  share: AbhaProfileShare;
  counters: FacilityAbdmCounter[];
}) {
  const { t } = useTranslation();
  const counter = share.counter_code
    ? counters.find((item) => item.code === share.counter_code)?.name ||
      share.counter_code
    : null;

  return (
    <div className="flex flex-col">
      <span
        className="text-2xl font-bold text-gray-900"
        data-testid="abdm-share-token"
      >
        {share.token_number ?? "-"}
      </span>
      {counter && (
        <span className="text-xs text-gray-600">
          {t("abdm_share_counter", { counter })}
        </span>
      )}
    </div>
  );
}

function SharePatient({ share }: { share: AbhaProfileShare }) {
  const { t } = useTranslation();
  const profile = share.profile;
  if (!profile) {
    return <span className="text-sm text-gray-500">-</span>;
  }
  const details = [
    profile.gender ? t(`GENDER__${profile.gender}`) : null,
    profile.date_of_birth
      ? formatDateTime(profile.date_of_birth, "DD/MM/YYYY")
      : profile.year_of_birth,
    profile.mobile,
  ].filter(Boolean);

  return (
    <div className="flex flex-col">
      <span
        className="font-medium text-gray-900"
        data-testid="abdm-share-name"
      >
        {profile.name}
      </span>
      {details.length > 0 && (
        <span className="text-xs text-gray-600">{details.join(" · ")}</span>
      )}
    </div>
  );
}

function ShareAbha({ share }: { share: AbhaProfileShare }) {
  const abhaNumber = share.abha_number ?? share.profile?.abha_number;
  const abhaAddress = share.abha_address ?? share.profile?.abha_address;
  return (
    <div className="flex flex-col text-sm">
      {abhaNumber && (
        <span className="font-mono text-gray-900">{abhaNumber}</span>
      )}
      {abhaAddress && (
        <span className="break-all text-gray-600">{abhaAddress}</span>
      )}
    </div>
  );
}

function ShareStatus({ share }: { share: AbhaProfileShare }) {
  const { t } = useTranslation();
  const isExpired =
    share.status === "pending" &&
    !!share.expires_at &&
    dayjs(share.expires_at).isBefore(dayjs());

  return (
    <div className="flex flex-wrap gap-1">
      <Badge
        variant={STATUS_BADGE[share.status] ?? "secondary"}
        data-testid="abdm-share-status"
      >
        {t(`abdm_share_status__${share.status}`)}
      </Badge>
      {isExpired && (
        <Badge variant="secondary">{t("abdm_share_token_expired")}</Badge>
      )}
    </div>
  );
}

function ShareAction({
  share,
  facilityId,
  canRegister,
  onRegister,
}: {
  share: AbhaProfileShare;
  facilityId: string;
  canRegister: boolean;
  onRegister: (share: AbhaProfileShare) => void;
}) {
  const { t } = useTranslation();

  if (share.patient) {
    return (
      <Link
        href={getPatientUrl(share.patient.id, facilityId)}
        className={buttonVariants({ variant: "outline", size: "sm" })}
        data-testid="abdm-share-open-patient"
      >
        <ExternalLinkIcon />
        {t("abdm_open_patient")}
      </Link>
    );
  }

  if (!canRegister || !share.profile) {
    return null;
  }

  return (
    <Button
      type="button"
      size="sm"
      onClick={() => onRegister(share)}
      data-testid="abdm-share-register"
    >
      <UserPlusIcon />
      {t("abdm_share_register")}
    </Button>
  );
}

import { useQuery } from "@tanstack/react-query";
import dayjs from "dayjs";
import {
  ExternalLinkIcon,
  IdCardIcon,
  RefreshCwIcon,
  SettingsIcon,
  UserPlusIcon,
} from "lucide-react";
import { Link, navigate } from "raviger";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { DatePicker } from "@/components/ui/date-picker";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

import Page from "@/components/Common/Page";
import { TableSkeleton } from "@/components/Common/SkeletonLoading";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { getPatientUrl } from "@/components/Abdm/AbhaExistingPatientAlert";
import { abdmSilent } from "@/components/Abdm/utils";

import { useAbdmConfig } from "@/hooks/useAbdmConfig";
import useFilters from "@/hooks/useFilters";

import query from "@/Utils/request/query";
import { dateQueryString, formatDateTime, parseLocalDate } from "@/Utils/utils";
import { getPermissions } from "@/common/Permissions";
import { usePermissions } from "@/context/PermissionContext";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import {
  AbhaProfileShare,
  AbhaProfileShareStatus,
  FacilityAbdmCounter,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const SHARE_STATUSES: AbhaProfileShareStatus[] = [
  "pending",
  "registered",
  "linked",
  "failed",
];

const STATUS_BADGE = {
  pending: "yellow",
  registered: "blue",
  linked: "green",
  failed: "destructive",
} as const satisfies Record<AbhaProfileShareStatus, string>;

/** New shares arrive while the desk watches the queue. */
const REFRESH_INTERVAL_MS = 30 * 1000;

const isShareStatus = (value: unknown): value is AbhaProfileShareStatus =>
  SHARE_STATUSES.includes(value as AbhaProfileShareStatus);

/**
 * Today's "scan and share" queue: patients who scanned a counter QR code and
 * shared their ABHA profile with this facility. The desk finds a patient by
 * the token number shown in their app and registers them from the profile.
 */
export default function AbhaShares({ facilityId }: { facilityId: string }) {
  const { t } = useTranslation();
  const { config: abdmConfig, isLoading: isAbdmConfigLoading } =
    useAbdmConfig();
  const { facility } = useCurrentFacility();
  const { hasPermission } = usePermissions();
  const { canCreatePatient } = getPermissions(
    hasPermission,
    facility?.permissions ?? [],
  );

  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 20,
    disableCache: true,
  });
  const today = dateQueryString(new Date());
  // Without a date the server answers with its own "today".
  const date: string | undefined =
    qParams.date && qParams.date !== today ? qParams.date : undefined;
  const status = isShareStatus(qParams.status) ? qParams.status : undefined;
  const page = Number(qParams.page) || 1;

  const { data: facilityConfig } = useQuery({
    queryKey: ["abdm", "facility", facilityId],
    queryFn: query(abdmApi.getFacilityConfig, {
      pathParams: { facilityId },
      silent: true,
    }),
    enabled: !!abdmConfig,
    retry: false,
  });

  const {
    data: response,
    isLoading,
    isFetching,
    error,
    refetch,
    dataUpdatedAt,
  } = useQuery({
    queryKey: ["abdm", "shares", facilityId, "queue", { date, status, page }],
    queryFn: query(abdmApi.listShares, {
      pathParams: { facilityId },
      queryParams: {
        ...(date && { date }),
        ...(status && { status }),
        limit: resultsPerPage,
        offset: (page - 1) * resultsPerPage,
      },
      silent: abdmSilent,
    }),
    enabled: !!abdmConfig,
    refetchInterval: date ? false : REFRESH_INTERVAL_MS,
    retry: false,
  });

  const counters = facilityConfig?.configured ? facilityConfig.counters : [];
  const shares = response?.results ?? [];

  const registerFromShare = (share: AbhaProfileShare) =>
    navigate(`/facility/${facilityId}/patient/create`, {
      query: { profile_share: share.id, ...(date && { share_date: date }) },
    });

  return (
    <Page title={t("abdm_abha_shares")} hideTitleOnPage>
      <div className="container mx-auto flex flex-col gap-4">
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-bold text-gray-700">
            {t("abdm_abha_shares")}
          </h1>
          <p className="text-sm text-gray-600">
            {t("abdm_abha_shares_description")}
          </p>
        </div>

        {isAbdmConfigLoading ? (
          <TableSkeleton count={5} />
        ) : !abdmConfig ? (
          <EmptyState
            icon={<IdCardIcon className="size-6 text-primary" />}
            title={t("abdm_not_enabled_title")}
            description={t("abdm_not_enabled_description")}
          />
        ) : (
          <>
            {facilityConfig && !facilityConfig.configured && (
              <Alert data-testid="abdm-shares-not-configured">
                <SettingsIcon />
                <AlertTitle>{t("abdm_shares_not_configured_title")}</AlertTitle>
                <AlertDescription>
                  <p>{t("abdm_shares_not_configured_description")}</p>
                  <Link
                    href={`/facility/${facilityId}/settings/abdm`}
                    className={cn(
                      buttonVariants({ variant: "outline", size: "sm" }),
                      "mt-1",
                    )}
                  >
                    {t("abdm_open_abdm_settings")}
                  </Link>
                </AlertDescription>
              </Alert>
            )}

            <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
              <Tabs
                value={status ?? "all"}
                onValueChange={(value) =>
                  updateQuery({ status: value === "all" ? undefined : value })
                }
              >
                <TabsList>
                  <TabsTrigger value="all">{t("all")}</TabsTrigger>
                  {SHARE_STATUSES.map((value) => (
                    <TabsTrigger
                      key={value}
                      value={value}
                      data-testid={`abdm-shares-status-${value}`}
                    >
                      {t(`abdm_share_status__${value}`)}
                    </TabsTrigger>
                  ))}
                </TabsList>
              </Tabs>
              <div className="flex flex-wrap items-center gap-2">
                <DatePicker
                  date={parseLocalDate(date ?? today)}
                  onChange={(value) =>
                    updateQuery({
                      date:
                        value && dateQueryString(value) !== today
                          ? dateQueryString(value)
                          : undefined,
                    })
                  }
                  disabled={(day) => day > new Date()}
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => refetch()}
                  disabled={isFetching}
                  data-testid="abdm-shares-refresh"
                >
                  <RefreshCwIcon className={cn(isFetching && "animate-spin")} />
                  {t("refresh")}
                </Button>
              </div>
            </div>

            {!!dataUpdatedAt && (
              <p className="text-xs text-gray-500">
                {date
                  ? t("abdm_shares_updated_at", {
                      time: formatDateTime(dataUpdatedAt, "hh:mm A"),
                    })
                  : t("abdm_shares_updated_at_live", {
                      time: formatDateTime(dataUpdatedAt, "hh:mm A"),
                    })}
              </p>
            )}

            {isLoading ? (
              <TableSkeleton count={5} />
            ) : error ? (
              <AbdmErrorAlert error={error} />
            ) : shares.length === 0 ? (
              <EmptyState
                icon={<IdCardIcon className="size-6 text-primary" />}
                title={t("abdm_shares_empty_title")}
                description={
                  date
                    ? t("abdm_shares_empty_day_description")
                    : t("abdm_shares_empty_today_description")
                }
              />
            ) : (
              <>
                <div className="grid gap-3 md:hidden">
                  {shares.map((share) => (
                    <Card key={share.id} data-testid="abdm-share-card">
                      <CardContent className="flex flex-col gap-3 p-4">
                        <div className="flex items-start justify-between gap-3">
                          <ShareToken share={share} counters={counters} />
                          <ShareStatus share={share} />
                        </div>
                        <SharePatient share={share} />
                        <ShareAbha share={share} />
                        <div className="flex items-center justify-between gap-2">
                          <span className="text-xs text-gray-500">
                            {formatDateTime(share.created_date, "hh:mm A")}
                          </span>
                          <ShareAction
                            share={share}
                            facilityId={facilityId}
                            canRegister={canCreatePatient}
                            onRegister={registerFromShare}
                          />
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
                <div className="hidden overflow-hidden rounded-lg border md:block">
                  <Table data-testid="abdm-shares-table">
                    <TableHeader className="bg-gray-100">
                      <TableRow>
                        <TableHead>{t("abdm_share_token")}</TableHead>
                        <TableHead>{t("patient")}</TableHead>
                        <TableHead>{t("abdm_share_abha")}</TableHead>
                        <TableHead>{t("abdm_share_shared_at")}</TableHead>
                        <TableHead>{t("status")}</TableHead>
                        <TableHead>
                          <span className="sr-only">{t("actions")}</span>
                        </TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody className="bg-white">
                      {shares.map((share) => (
                        <TableRow
                          key={share.id}
                          data-testid="abdm-share-row"
                          data-share-id={share.id}
                        >
                          <TableCell>
                            <ShareToken share={share} counters={counters} />
                          </TableCell>
                          <TableCell>
                            <SharePatient share={share} />
                          </TableCell>
                          <TableCell>
                            <ShareAbha share={share} />
                          </TableCell>
                          <TableCell className="whitespace-nowrap text-sm text-gray-700">
                            {formatDateTime(share.created_date, "hh:mm A")}
                          </TableCell>
                          <TableCell>
                            <ShareStatus share={share} />
                          </TableCell>
                          <TableCell className="text-right">
                            <ShareAction
                              share={share}
                              facilityId={facilityId}
                              canRegister={canCreatePatient}
                              onRegister={registerFromShare}
                            />
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
                {!!response && response.count > resultsPerPage && (
                  <div className="flex justify-center">
                    <Pagination totalCount={response.count} />
                  </div>
                )}
              </>
            )}
          </>
        )}
      </div>
    </Page>
  );
}

function ShareToken({
  share,
  counters,
}: {
  share: AbhaProfileShare;
  counters: FacilityAbdmCounter[];
}) {
  const { t } = useTranslation();
  const counter = share.counter_code
    ? counters.find((item) => item.code === share.counter_code)?.name ||
      share.counter_code
    : null;

  return (
    <div className="flex flex-col">
      <span
        className="text-2xl font-bold text-gray-900"
        data-testid="abdm-share-token"
      >
        {share.token_number ?? "-"}
      </span>
      {counter && (
        <span className="text-xs text-gray-600">
          {t("abdm_share_counter", { counter })}
        </span>
      )}
    </div>
  );
}

function SharePatient({ share }: { share: AbhaProfileShare }) {
  const { t } = useTranslation();
  const profile = share.profile;
  if (!profile) {
    return <span className="text-sm text-gray-500">-</span>;
  }
  const details = [
    profile.gender ? t(`GENDER__${profile.gender}`) : null,
    profile.date_of_birth
      ? formatDateTime(profile.date_of_birth, "DD/MM/YYYY")
      : profile.year_of_birth,
    profile.mobile,
  ].filter(Boolean);

  return (
    <div className="flex flex-col">
      <span
        className="font-medium text-gray-900"
        data-testid="abdm-share-name"
      >
        {profile.name}
      </span>
      {details.length > 0 && (
        <span className="text-xs text-gray-600">{details.join(" · ")}</span>
      )}
    </div>
  );
}

function ShareAbha({ share }: { share: AbhaProfileShare }) {
  const abhaNumber = share.abha_number ?? share.profile?.abha_number;
  const abhaAddress = share.abha_address ?? share.profile?.abha_address;
  return (
    <div className="flex flex-col text-sm">
      {abhaNumber && (
        <span className="font-mono text-gray-900">{abhaNumber}</span>
      )}
      {abhaAddress && (
        <span className="break-all text-gray-600">{abhaAddress}</span>
      )}
    </div>
  );
}

function ShareStatus({ share }: { share: AbhaProfileShare }) {
  const { t } = useTranslation();
  const isExpired =
    share.status === "pending" &&
    !!share.expires_at &&
    dayjs(share.expires_at).isBefore(dayjs());

  return (
    <div className="flex flex-wrap gap-1">
      <Badge
        variant={STATUS_BADGE[share.status] ?? "secondary"}
        data-testid="abdm-share-status"
      >
        {t(`abdm_share_status__${share.status}`)}
      </Badge>
      {isExpired && (
        <Badge variant="secondary">{t("abdm_share_token_expired")}</Badge>
      )}
    </div>
  );
}

function ShareAction({
  share,
  facilityId,
  canRegister,
  onRegister,
}: {
  share: AbhaProfileShare;
  facilityId: string;
  canRegister: boolean;
  onRegister: (share: AbhaProfileShare) => void;
}) {
  const { t } = useTranslation();

  if (share.patient) {
    return (
      <Link
        href={getPatientUrl(share.patient.id, facilityId)}
        className={buttonVariants({ variant: "outline", size: "sm" })}
        data-testid="abdm-share-open-patient"
      >
        <ExternalLinkIcon />
        {t("abdm_open_patient")}
      </Link>
    );
  }

  if (!canRegister || !share.profile) {
    return null;
  }

  return (
    <Button
      type="button"
      size="sm"
      onClick={() => onRegister(share)}
      data-testid="abdm-share-register"
    >
      <UserPlusIcon />
      {t("abdm_share_register")}
    </Button>
  );
}

