import { useMutation } from "@tanstack/react-query";
import { Loader2Icon } from "lucide-react";
import { SubmitEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { AbhaOtpInput } from "@/components/Abdm/AbhaOtpInput";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import { AbhaFlowNotice } from "@/components/Abdm/types";
import { abdmSilent, isAbdmErrorType } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import {
  AbhaIdentifierType,
  AbhaOtpSent,
  AbhaVerified,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

/** Verifies a login OTP (identify by any identifier, or find by mobile). */
export function OtpStep({
  otpSent: initialOtpSent,
  identifierType,
  value,
  notice,
  onBack,
}: {
  otpSent: AbhaOtpSent;
  identifierType: AbhaIdentifierType;
  value: string;
  notice?: AbhaFlowNotice;
  onBack: () => void;
}) {
  const { t } = useTranslation();
  const { config, goTo, finish, restart } = useAbhaFlow();
  const [otpSent, setOtpSent] = useState(initialOtpSent);
  const [otp, setOtp] = useState("");

  const verifyMutation = useMutation({
    mutationFn: mutate(abdmApi.verifyOtp, { silent: abdmSilent }),
    onSuccess: (verified: AbhaVerified) => {
      if (verified.status === "select_account") {
        goTo({ name: "select_account", verified });
        return;
      }
      if (verified.profile) {
        finish(
          {
            transactionId: verified.transaction_id,
            profile: verified.profile,
            existingPatient: verified.existing_patient,
          },
          notice,
        );
      }
    },
    onError: (error) => {
      if (isAbdmErrorType(error, "abha_not_found")) {
        goTo({ name: "not_found", identifierType, value });
      }
    },
  });

  const isComplete = otp.length === config.otp.length;

  const handleSubmit = (event: SubmitEvent) => {
    event.preventDefault();
    if (!isComplete || verifyMutation.isPending) return;
    verifyMutation.mutate({ transaction_id: otpSent.transaction_id, otp });
  };

  return (
    <StepLayout
      title={t("abdm_otp_title")}
      onBack={onBack}
      testId="abdm-step-otp"
    >
      {notice === "abha_exists" && (
        <Alert className="border-primary-200 bg-primary-50">
          <AlertDescription className="text-gray-800">
            {t("abdm_notice__abha_exists_login")}
          </AlertDescription>
        </Alert>
      )}
      <form className="flex flex-col gap-4" onSubmit={handleSubmit} noValidate>
        <AbhaOtpInput
          otpSent={otpSent}
          onOtpSentChange={setOtpSent}
          otpLength={config.otp.length}
          value={otp}
          onChange={(next) => {
            setOtp(next);
            if (verifyMutation.error) verifyMutation.reset();
          }}
          disabled={verifyMutation.isPending}
          onRestart={restart}
        />
        {verifyMutation.error &&
          !isAbdmErrorType(verifyMutation.error, "abha_not_found") && (
            <AbdmErrorAlert error={verifyMutation.error} onRestart={restart} />
          )}
        <div className="flex justify-end">
          <Button
            type="submit"
            variant="primary"
            disabled={!isComplete || verifyMutation.isPending}
            data-testid="abdm-otp-submit"
          >
            {verifyMutation.isPending && (
              <Loader2Icon className="animate-spin" />
            )}
            {t("verify")}
          </Button>
        </div>
      </form>
    </StepLayout>
  );
}

