 import { useMutation } from "@tanstack/react-query";
 import { Loader2Icon, SearchXIcon } from "lucide-react";
 import { useTranslation } from "react-i18next";

 import { Button } from "@/components/ui/button";

 import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
 import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
 import { StepLayout } from "@/components/Abdm/steps/StepLayout";
 import { abdmSilent, maskAadhaar } from "@/components/Abdm/utils";

 import mutate from "@/Utils/request/mutate";
 import { AbhaIdentifierType, AbhaOtpSent } from "@/types/abdm/abdm";
 import abdmApi from "@/types/abdm/abdmApi";

 /**
  * Shown only for `abha_not_found`. The screen is worded for both outcomes:
  * the identifier may have been mistyped, or the patient may have no ABHA.
  */
 export function NotFoundStep({
   identifierType,
   value,
   onCheck,
 }: {
   identifierType: AbhaIdentifierType;
   value: string;
   /** Returns to the step where the identifier can be corrected. */
   onCheck: () => void;
 }) {
   const { t } = useTranslation();
   const { allowCreate, consent, facilityId, goTo } = useAbhaFlow();

   // Aadhaar was already entered with consent: create with it right away.
   const createMutation = useMutation({
     mutationFn: mutate(abdmApi.createOtp, { silent: abdmSilent }),
     onSuccess: (otpSent: AbhaOtpSent) => goTo({ name: "create_otp", otpSent }),
   });

   const isAadhaar = identifierType === "aadhaar";
   // A typo is the likelier cause for an ABHA number or address.
   const checkFirst =
     identifierType === "abha_number" || identifierType === "abha_address";

   const checkButton = (
     <Button
       type="button"
       variant={checkFirst || !allowCreate ? "primary" : "outline"}
       onClick={onCheck}
       data-testid="abdm-not-found-check"
     >
       {t(`abdm_not_found_check__${identifierType}`)}
     </Button>
   );

   const createButton = allowCreate && (
     <Button
       type="button"
       variant={checkFirst ? "outline" : "primary"}
       disabled={createMutation.isPending}
       onClick={() =>
         isAadhaar
           ? createMutation.mutate({
               aadhaar: value,
               consent,
               facility: facilityId,
             })
           : goTo({ name: "create_aadhaar" })
       }
       data-testid="abdm-not-found-create"
     >
       {createMutation.isPending && <Loader2Icon className="animate-spin" />}
       {isAadhaar
         ? t("abdm_create_with_this_aadhaar")
         : t("abdm_create_with_aadhaar")}
     </Button>
   );

   return (
     <StepLayout
       title={t(`abdm_not_found_title__${identifierType}`)}
       description={
         allowCreate
           ? t(`abdm_not_found_description__${identifierType}`)
           : t("abdm_not_found_description_verify")
       }
       testId="abdm-step-not-found"
       footer={
         checkFirst || !allowCreate ? (
           <>
             {createButton}
             {checkButton}
           </>
         ) : (
           <>
             {checkButton}
             {createButton}
           </>
         )
       }
     >
       <div className="flex items-center gap-3 rounded-md border border-gray-200 bg-gray-50 p-3">
         <SearchXIcon className="size-5 shrink-0 text-gray-500" />
         <div className="flex min-w-0 flex-col">
           <span className="text-xs text-gray-500">
             {t(`abdm_identifier__${identifierType}`)}
           </span>
           <span
             className="font-medium break-all text-gray-900"
             data-testid="abdm-not-found-value"
           >
             {isAadhaar ? maskAadhaar(value) : value}
           </span>
         </div>
       </div>
       {createMutation.error && <AbdmErrorAlert error={createMutation.error} />}
     </StepLayout>
   );
 }

