import { useMutation } from "@tanstack/react-query";
import { BadgeCheckIcon, ChevronRightIcon, Loader2Icon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { Avatar } from "@/components/Common/Avatar";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import { abdmSilent, photoToDataUrl } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { AbhaVerified } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

/** Shown when one mobile carries several ABHAs; asks nothing but "which one". */
export function AccountChooserStep({
  verified,
  onBack,
}: {
  verified: AbhaVerified;
  onBack: () => void;
}) {
  const { t } = useTranslation();
  const { finish, restart } = useAbhaFlow();

  const selectMutation = useMutation({
    mutationFn: mutate(abdmApi.selectAccount, { silent: abdmSilent }),
    onSuccess: (result: AbhaVerified) => {
      if (result.profile) {
        finish({
          transactionId: result.transaction_id,
          profile: result.profile,
          existingPatient: result.existing_patient,
        });
      }
    },
  });

  return (
    <StepLayout
      title={t("abdm_select_account_title")}
      description={t("abdm_select_account_description", {
        count: verified.accounts.length,
      })}
      onBack={onBack}
      testId="abdm-step-select-account"
    >
      <ul className="flex flex-col gap-2">
        {verified.accounts.map((account, index) => {
          const isSelecting =
            selectMutation.isPending &&
            selectMutation.variables?.abha_number === account.abha_number;
          return (
            <li key={account.abha_number ?? account.abha_address ?? index}>
              <button
                type="button"
                className="flex w-full items-center gap-3 rounded-md border border-gray-200 bg-white p-3 text-left transition-colors hover:border-primary-400 hover:bg-primary-50 focus-visible:ring-2 focus-visible:ring-primary-500 focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-60"
                disabled={!account.abha_number || selectMutation.isPending}
                onClick={() =>
                  account.abha_number &&
                  selectMutation.mutate({
                    transaction_id: verified.transaction_id,
                    abha_number: account.abha_number,
                  })
                }
                data-testid="abdm-account-option"
              >
                <div className="size-10 shrink-0">
                  <Avatar
                    name={account.name}
                    imageUrl={photoToDataUrl(account.photo)}
                  />
                </div>
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="text-sm font-semibold break-words text-gray-900">
                    {account.name}
                  </span>
                  {account.abha_number && (
                    <span className="text-xs text-gray-700">
                      {account.abha_number}
                    </span>
                  )}
                  {account.abha_address && (
                    <span className="text-xs break-all text-gray-600">
                      {account.abha_address}
                    </span>
                  )}
                  {account.kyc_verified && (
                    <Badge variant="green" size="xs" className="mt-1 w-fit">
                      <BadgeCheckIcon className="size-3" />
                      {t("abha_kyc_verified")}
                    </Badge>
                  )}
                </span>
                {isSelecting ? (
                  <Loader2Icon className="size-4 animate-spin text-gray-500" />
                ) : (
                  <ChevronRightIcon className="size-4 text-gray-400" />
                )}
              </button>
            </li>
          );
        })}
      </ul>
      {selectMutation.error && (
        <AbdmErrorAlert error={selectMutation.error} onRestart={restart} />
      )}
    </StepLayout>
  );
}

