import { useMutation } from "@tanstack/react-query";
import { Loader2Icon } from "lucide-react";
import { SubmitEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { AadhaarConsentInput } from "@/components/Abdm/AadhaarConsentInput";
import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import {
  abdmSilent,
  isAbdmErrorType,
  isValidAadhaar,
  provenanceFor,
} from "@/components/Abdm/utils";

import { callApi } from "@/Utils/request/query";
import abdmApi from "@/types/abdm/abdmApi";

/**
 * Collects Aadhaar and consent to create an ABHA after another identifier
 * found none. The Aadhaar is still looked up first (no OTP is sent when it
 * holds no ABHA), so a patient who already has an ABHA logs in instead of
 * getting a duplicate. Creation starts only on a second `abha_not_found`.
 */
export function CreateAadhaarStep({ onBack }: { onBack: () => void }) {
  const { t } = useTranslation();
  const { config, consent, facilityId, facts, rememberFact, goTo } =
    useAbhaFlow();

  const [aadhaar, setAadhaar] = useState(() => facts.aadhaar?.value ?? "");
  const [consented, setConsented] = useState(() => !!facts.aadhaar);
  const [showErrors, setShowErrors] = useState(false);

  const startMutation = useMutation({
    mutationFn: async (value: string) => {
      try {
        const otpSent = await callApi(abdmApi.requestOtp, {
          body: {
            identifier_type: "aadhaar",
            value,
            consent,
            facility: facilityId,
          },
          silent: abdmSilent,
        });
        return { exists: true, otpSent };
      } catch (error) {
        if (!isAbdmErrorType(error, "abha_not_found")) throw error;
        const otpSent = await callApi(abdmApi.createOtp, {
          body: { aadhaar: value, consent, facility: facilityId },
          silent: abdmSilent,
        });
        return { exists: false, otpSent };
      }
    },
    onSuccess: ({ exists, otpSent }, value) => {
      if (exists) {
        goTo({
          name: "otp",
          otpSent,
          identifierType: "aadhaar",
          value,
          notice: "abha_exists",
          backTo: "create_aadhaar",
        });
      } else {
        goTo({ name: "create_otp", otpSent });
      }
    },
  });

  const fieldError =
    showErrors && !isValidAadhaar(aadhaar)
      ? t("abdm_validation__aadhaar")
      : undefined;

  const handleSubmit = (event: SubmitEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (!consented || !isValidAadhaar(aadhaar) || startMutation.isPending) {
      return;
    }
    rememberFact("aadhaar", aadhaar);
    startMutation.mutate(aadhaar);
  };

  return (
    <StepLayout
      title={t("abdm_create_title")}
      description={t("abdm_create_aadhaar_description")}
      onBack={onBack}
      testId="abdm-step-create-aadhaar"
    >
      <form className="flex flex-col gap-4" onSubmit={handleSubmit} noValidate>
        <AadhaarConsentInput
          value={aadhaar}
          onChange={(value) => {
            setAadhaar(value);
            if (facts.aadhaar && value !== facts.aadhaar.value) {
              setConsented(false);
            }
          }}
          consented={consented}
          onConsentChange={setConsented}
          consent={config.consent}
          error={fieldError}
          provenance={
            provenanceFor(facts.aadhaar, aadhaar, "aadhaar")?.provenance
          }
          autoFocus={!facts.aadhaar}
        />
        {startMutation.error && <AbdmErrorAlert error={startMutation.error} />}
        <div className="flex justify-end">
          <Button
            type="submit"
            variant="primary"
            disabled={!consented || startMutation.isPending}
            data-testid="abdm-create-aadhaar-submit"
          >
            {startMutation.isPending && (
              <Loader2Icon className="animate-spin" />
            )}
            {t("abdm_send_otp")}
          </Button>
        </div>
      </form>
    </StepLayout>
  );
}

