import { useMutation } from "@tanstack/react-query";
import { Loader2Icon } from "lucide-react";
import { SubmitEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbdmField } from "@/components/Abdm/AbdmField";
import { useAbhaFlow } from "@/components/Abdm/AbhaFlowContext";
import { AbhaOtpInput } from "@/components/Abdm/AbhaOtpInput";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import {
  abdmSilent,
  isValidMobile,
  provenanceFor,
} from "@/components/Abdm/utils";

import { callApi } from "@/Utils/request/query";
import { AbhaCreateVerified, AbhaOtpSent } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

interface CreateVerifyOutcome {
  created: AbhaCreateVerified;
  mobileOtpSent?: AbhaOtpSent;
  mobileOtpError?: unknown;
}

/** Aadhaar OTP for creation, plus the mobile number for ABHA communication. */
export function CreateOtpStep({
  otpSent: initialOtpSent,
  onBack,
}: {
  otpSent: AbhaOtpSent;
  onBack: () => void;
}) {
  const { t } = useTranslation();
  const { config, facts, rememberFact, goTo, finish, restart } = useAbhaFlow();

  const [otpSent, setOtpSent] = useState(initialOtpSent);
  const [otp, setOtp] = useState("");
  const [mobile, setMobile] = useState(() => facts.mobile?.value ?? "");
  const [showErrors, setShowErrors] = useState(false);

  const verifyMutation = useMutation({
    mutationFn: async (body: {
      transaction_id: string;
      otp: string;
      mobile: string;
    }): Promise<CreateVerifyOutcome> => {
      const created = await callApi(abdmApi.createVerify, {
        body,
        silent: abdmSilent,
      });
      if (!created.is_new || !created.mobile_verification_required) {
        return { created };
      }
      // Sent from this handler (not an effect) so it can never fire twice.
      try {
        const mobileOtpSent = await callApi(abdmApi.createMobileOtp, {
          body: { transaction_id: created.transaction_id, mobile: body.mobile },
          silent: abdmSilent,
        });
        return { created, mobileOtpSent };
      } catch (mobileOtpError) {
        return { created, mobileOtpError };
      }
    },
    onSuccess: ({ created, mobileOtpSent, mobileOtpError }, { mobile }) => {
      // An Aadhaar that already has an ABHA returns that account: say so,
      // and skip the steps that only apply to a new one.
      const notice = created.is_new ? undefined : "abha_exists";
      if (created.is_new && created.mobile_verification_required) {
        goTo({
          name: "create_mobile",
          created,
          mobile,
          otpSent: mobileOtpSent ?? null,
          sendError: mobileOtpError,
        });
        return;
      }
      if (created.abha_address_required) {
        goTo({
          name: "address",
          transactionId: created.transaction_id,
          existingPatient: created.existing_patient,
          isNew: created.is_new,
          notice,
        });
        return;
      }
      finish(
        {
          transactionId: created.transaction_id,
          profile: created.profile,
          existingPatient: created.existing_patient,
          isNew: created.is_new,
        },
        notice,
      );
    },
  });

  const mobileError =
    showErrors && !isValidMobile(mobile)
      ? t("abdm_validation__mobile")
