          value={otp}
          onChange={(next) => {
            setOtp(next);
            if (verifyMutation.error) verifyMutation.reset();
          }}
          disabled={verifyMutation.isPending}
          onRestart={restart}
        />
        <AbdmField
          label={t("abdm_communication_mobile")}
          prefix="+91"
          inputMode="numeric"
          maxLength={10}
          placeholder={t("abdm_mobile_placeholder")}
          value={mobile}
          onChange={(e) =>
            setMobile(e.target.value.replace(/\D/g, "").slice(0, 10))
          }
          hint={t("abdm_communication_mobile_hint")}
          error={mobileError}
          provenance={provenanceFor(facts.mobile, mobile, "mobile")}
          data-testid="abdm-create-mobile-input"
        />
