import { useMutation } from "@tanstack/react-query";
import { REGEXP_ONLY_DIGITS } from "input-otp";
import { MessageSquareIcon, RotateCwIcon } from "lucide-react";
import { useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { abdmSilent, getAbdmError } from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { AbhaOtpSent } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

interface AbhaOtpInputProps {
  otpSent: AbhaOtpSent;
  /** Called with the server's fresh `OtpSent` after a resend. */
  onOtpSentChange: (otpSent: AbhaOtpSent) => void;
  otpLength: number;
  value: string;
  onChange: (value: string) => void;
  disabled?: boolean;
  onRestart?: () => void;
}

/**
 * OTP entry for any ABHA OTP step. The resend countdown and the number of
 * resends left are driven entirely by the server's `resend` object, and a
 * resend always reuses the current transaction (`otp/resend`).
 */
export function AbhaOtpInput({
  otpSent,
  onOtpSentChange,
  otpLength,
  value,
  onChange,
  disabled,
  onRestart,
}: AbhaOtpInputProps) {
  const { t } = useTranslation();
  const id = useId();

  const [resendAt, setResendAt] = useState(
    () => Date.now() + otpSent.resend.available_in_seconds * 1000,
  );
  const [remaining, setRemaining] = useState(otpSent.resend.remaining);
  const [now, setNow] = useState(() => Date.now());

  const secondsLeft = Math.max(0, Math.ceil((resendAt - now) / 1000));

  useEffect(() => {
    const timer = setInterval(() => {
      const current = Date.now();
      setNow(current);
      if (current >= resendAt) {
        clearInterval(timer);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [resendAt]);

  const waitUntil = (seconds: number) => {
    const current = Date.now();
    setNow(current);
    setResendAt(current + seconds * 1000);
  };

  const resendMutation = useMutation({
    mutationFn: mutate(abdmApi.resendOtp, { silent: abdmSilent }),
    onSuccess: (data: AbhaOtpSent) => {
      onChange("");
      waitUntil(data.resend.available_in_seconds);
      setRemaining(data.resend.remaining);
      onOtpSentChange(data);
    },
    onError: (error) => {
      const abdmError = getAbdmError(error);
      if (abdmError?.type === "resend_too_soon") {
        waitUntil(
          abdmError.retry_after_seconds ?? otpSent.resend.available_in_seconds,
        );
      }
      if (abdmError?.type === "resend_limit_reached") {
        setRemaining(0);
      }
    },
  });

  return (
    <div className="flex flex-col gap-4">
      <div
        className="flex items-start gap-3 rounded-md border border-primary-200 bg-primary-50 p-3 text-sm"
        data-testid="abdm-otp-sent"
      >
        <MessageSquareIcon className="mt-0.5 size-4 shrink-0 text-primary-700" />
        <div className="flex flex-col gap-1">
          <p className="font-medium text-gray-900">
            {otpSent.masked_mobile
              ? t(
                  otpSent.otp_system === "aadhaar"
                    ? "abdm_otp_sent_aadhaar_mobile"
                    : "abdm_otp_sent_mobile",
                  { mobile: otpSent.masked_mobile },
                )
              : otpSent.message || t("abdm_otp_sent")}
          </p>
          {otpSent.masked_mobile && otpSent.message && (
            <p className="text-xs text-gray-600">{otpSent.message}</p>
          )}
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <Label htmlFor={`${id}-otp`}>{t("abdm_enter_otp")}</Label>
        <InputOTP
          id={`${id}-otp`}
          data-testid="abdm-otp-input"
          aria-label={t("abdm_enter_otp")}
          maxLength={otpLength}
          pattern={REGEXP_ONLY_DIGITS}
          value={value}
          onChange={onChange}
          disabled={disabled}
          autoFocus
        >
          <InputOTPGroup>
            {Array.from({ length: otpLength }).map((_, index) => (
              <InputOTPSlot key={index} index={index} className="size-10" />
            ))}
          </InputOTPGroup>
        </InputOTP>
      </div>

      <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-sm">
        {remaining > 0 ? (
          <>
            <Button
              type="button"
              variant="outline"
              size="sm"
              data-testid="abdm-resend-otp"
              disabled={secondsLeft > 0 || resendMutation.isPending || disabled}
              onClick={() =>
                resendMutation.mutate({
                  transaction_id: otpSent.transaction_id,
                })
              }
            >
              <RotateCwIcon />
              {secondsLeft > 0
                ? t("abdm_resend_otp_in", { seconds: secondsLeft })
                : t("abdm_resend_otp")}
            </Button>
            <span className="text-xs text-gray-500" aria-live="polite">
              {t("abdm_resends_left", { count: remaining })}
            </span>
          </>
        ) : (
          <span className="text-xs text-gray-500" aria-live="polite">
            {t("abdm_no_resends_left")}
          </span>
        )}
      </div>

      {resendMutation.error &&
        getAbdmError(resendMutation.error)?.type !== "resend_too_soon" && (
          <AbdmErrorAlert error={resendMutation.error} onRestart={onRestart} />
        )}
    </div>
  );
}

