import { TFunction } from "i18next";
import { toast } from "sonner";

import {
  abdmSilent,
  getAbdmErrorMessage,
  mobileToPhone,
} from "@/components/Abdm/utils";

import { callApi } from "@/Utils/request/query";
import {
  AbhaGender,
  AbhaProfile,
  PatientAbhaLinkRequest,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";
import {
  Organization,
  OrganizationParent,
} from "@/types/organization/organization";
import organizationApi from "@/types/organization/organizationApi";

/** Registration values taken from an ABHA profile. */
export interface AbhaRegistrationPrefill {
  name?: string;
  gender?: AbhaGender;
  date_of_birth?: string;
  age?: number;
  phone_number?: string;
  address?: string;
  pincode?: number;
}

/** The ABHA chosen at registration; it is linked once the patient exists. */
export interface RegistrationAbha {
  profile: AbhaProfile;
  link: PatientAbhaLinkRequest;
}

export interface RegistrationAbhaState extends RegistrationAbha {
  prefill: AbhaRegistrationPrefill;
  /** Name, date of birth and gender are locked for a KYC-verified ABHA. */
  locked: boolean;
  /** The government organization matched from the ABHA's state/district. */
  geoOrganizationId?: string;
}

export function getRegistrationPrefill(
  profile: AbhaProfile,
): AbhaRegistrationPrefill {
  const prefill: AbhaRegistrationPrefill = {};

  if (profile.name?.trim()) prefill.name = profile.name.trim();
  if (profile.gender) prefill.gender = profile.gender;

  if (profile.date_of_birth) {
    prefill.date_of_birth = profile.date_of_birth;
  } else if (profile.year_of_birth) {
    const age = new Date().getFullYear() - profile.year_of_birth;
    if (age >= 1) prefill.age = age;
  }

  if (profile.mobile) prefill.phone_number = mobileToPhone(profile.mobile);
  if (profile.address?.trim()) prefill.address = profile.address.trim();
  if (profile.pincode && /^\d{6}$/.test(profile.pincode)) {
    prefill.pincode = Number(profile.pincode);
  }

  return prefill;
}

const normalizeName = (name: string) =>
  name.toLowerCase().replace(/[^a-z0-9]/g, "");

async function findGovtOrganization(name: string, parent?: Organization) {
  const { results } = await callApi(organizationApi.list, {
    queryParams: {
      org_type: "govt",
      parent: parent?.id ?? "",
      name,
      limit: 50,
    },
    silent: true,
  });
  const target = normalizeName(name);
  return results.find(
    (organization) =>
      normalizeName(organization.name) === target &&
      (parent
        ? organization.level_cache === parent.level_cache + 1
        : organization.level_cache === 0),
  );
}

/**
 * Best-effort match of the ABHA's state and district to CARE's government
 * organizations, by name. Returns the deepest level that matched, or
 * undefined; the user can always change the selection.
 */
export async function matchAbhaGeoOrganization(
  profile: AbhaProfile,
): Promise<Organization | undefined> {
  if (!profile.state_name) return undefined;
  try {
    const state = await findGovtOrganization(profile.state_name);
    if (!state || !profile.district_name || !state.has_children) {
      return state;
    }
    const district = await findGovtOrganization(profile.district_name, state);
    return district ?? state;
  } catch {
    return undefined;
  }
}

/** True when `organization` is `ancestorId` or lies below it. */
export function isWithinOrganization(
  organization: Organization | OrganizationParent | undefined,
  ancestorId: string,
) {
  let current = organization;
  while (current) {
    if (current.id === ancestorId) return true;
    current = current.parent;
  }
  return false;
}

/**
 * Links the ABHA chosen at registration to the newly created patient. The
 * patient is kept even when linking fails; it can be retried from the
 * patient's page.
 */
export async function linkAbhaAfterRegistration(
  t: TFunction,
  patientId: string,
  link: PatientAbhaLinkRequest,
) {
  try {
    await callApi(abdmApi.linkPatientAbha, {
      pathParams: { patientId },
      body: link,
      silent: abdmSilent,
    });
    toast.success(t("abdm_abha_linked"));
  } catch (error) {
    toast.error(t("abdm_link_failed_after_registration"), {
      description: getAbdmErrorMessage(t, error).title,
    });
  }
}

