import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  BadgeCheckIcon,
  IdCardIcon,
  Link2Icon,
  SmartphoneIcon,
  UnlinkIcon,
} from "lucide-react";
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

import ConfirmActionDialog from "@/components/Common/ConfirmActionDialog";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbhaIdentifyFlowProps } from "@/components/Abdm/AbhaIdentifyFlow";
import { AbhaIdentifySheet } from "@/components/Abdm/AbhaIdentifySheet";
import { AbhaLinkReview } from "@/components/Abdm/AbhaLinkReview";
import { AbhaUpdateMobile } from "@/components/Abdm/AbhaUpdateMobile";
import { AbhaFacts, AbhaVerifyIdentifierType } from "@/components/Abdm/types";
import {
  abdmSilent,
  isValidMobile,
  phoneToMobile,
} from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime, formatName } from "@/Utils/utils";
import { AbdmConfig, PatientAbhaLinked } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";
import { PatientRead } from "@/types/emr/patient/patient";

type SheetMode = "link" | "card" | "mobile";

const humanize = (value: string) =>
  value.charAt(0).toUpperCase() + value.slice(1).replace(/_/g, " ");

/** The ABHA section of a patient's demography: its link and actions. */
export function PatientAbhaSection({
  patient,
  facilityId,
  config,
  canWrite,
}: {
  patient: PatientRead;
  facilityId?: string;
  config: AbdmConfig;
  canWrite: boolean;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [sheet, setSheet] = useState<SheetMode | null>(null);
  const [isUnlinkOpen, setIsUnlinkOpen] = useState(false);

  const abhaQuery = useQuery({
    queryKey: ["patient-abha", patient.id],
    queryFn: query(abdmApi.getPatientAbha, {
      pathParams: { patientId: patient.id },
      silent: abdmSilent,
    }),
    retry: false,
  });

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: ["patient-abha", patient.id] });
    queryClient.invalidateQueries({ queryKey: ["patient", patient.id] });
  };

  const unlinkMutation = useMutation({
    mutationFn: mutate(abdmApi.unlinkPatientAbha, {
      pathParams: { patientId: patient.id },
      silent: abdmSilent,
    }),
    onSuccess: () => {
      toast.success(t("abdm_abha_unlinked"));
      invalidate();
    },
  });

  const patientMobile = phoneToMobile(patient.phone_number);
  const mobileFacts: AbhaFacts =
    patientMobile && isValidMobile(patientMobile)
      ? { mobile: { value: patientMobile, provenance: "patient_record" } }
      : {};

  const closeSheet = () => setSheet(null);

  if (abhaQuery.isLoading) {
    return (
      <div className="flex flex-col gap-3 pr-5 sm:col-span-2">
        <Skeleton className="h-5 w-48" />
        <Skeleton className="h-5 w-64" />
      </div>
    );
  }

  if (abhaQuery.error || !abhaQuery.data) {
    return (
      <div className="pr-5 sm:col-span-2" data-testid="patient-abha-section">
        <AbdmErrorAlert error={abhaQuery.error} />
      </div>
    );
  }

  const link = abhaQuery.data.linked ? abhaQuery.data : null;
  const verifyIdentifier = link ? getVerifyIdentifier(link) : undefined;

  // "Show ABHA card" and "Update mobile" first re-verify the linked ABHA, so
  // the browser only ever works with a fresh, server-held transaction.
  const verifyFacts: AbhaFacts = verifyIdentifier
    ? {
        ...mobileFacts,
        [verifyIdentifier.type]: {
          value: verifyIdentifier.value,
          provenance: "patient_record",
        },
      }
    : mobileFacts;

  const sheets: Record<
    SheetMode,
    {
      title: string;
      description: string;
      flow: Pick<
        AbhaIdentifyFlowProps,
        "initialFacts" | "allowCreate" | "renderResultAction" | "exitLabel"
      >;
    }
  > = {
    link: {
      title: t("abdm_link_abha"),
      description: t("abdm_link_abha_description"),
      flow: {
        initialFacts: mobileFacts,
        renderResultAction: (result) => (
          <AbhaLinkReview
            patient={patient}
            facilityId={facilityId}
            result={result}
            onLinked={closeSheet}
          />
        ),
        exitLabel: t("abdm_not_now"),
      },
    },
    card: {
      title: t("abdm_show_abha_card"),
      description: t("abdm_show_abha_card_description"),
      flow: {
        allowCreate: false,
        initialFacts: verifyFacts,
        exitLabel: t("close"),
      },
    },
    mobile: {
      title: t("abdm_update_mobile"),
      description: t("abdm_update_mobile_description"),
      flow: {
        allowCreate: false,
        initialFacts: verifyFacts,
        renderResultAction: (result) => (
          <AbhaUpdateMobile
            result={result}
            patientMobile={mobileFacts.mobile?.value}
            onUpdated={invalidate}
            onDone={closeSheet}
          />
        ),
        exitLabel: t("close"),
      },
    },
  };

  const activeSheet = sheet ? sheets[sheet] : undefined;

  return (
    <div
      className="flex flex-col gap-4 pr-5 sm:col-span-2"
      data-testid="patient-abha-section"
      data-linked={!!link}
    >
      {link ? (
        <>
          <dl className="grid grid-cols-1 gap-x-4 gap-y-4 sm:grid-cols-2">
            <AbhaDetail
              label={t("abha_number")}
              testId="patient-abha-number"
              value={link.abha_number}
            />
            <AbhaDetail
              label={t("abha_address")}
              testId="patient-abha-address"
              value={
                link.abha_address && (
                  <span className="break-all">{link.abha_address}</span>
                )
              }
            />
            {link.abha_addresses.filter((a) => a !== link.abha_address).length >
              0 && (
              <AbhaDetail
                label={t("abdm_other_abha_addresses")}
                testId="patient-abha-other-addresses"
                value={
                  <span className="break-all">
                    {link.abha_addresses
                      .filter((a) => a !== link.abha_address)
                      .join(", ")}
                  </span>
                }
              />
            )}
            <AbhaDetail
              label={t("abdm_kyc")}
              testId="patient-abha-kyc"
              value={
                link.kyc_verified ? (
                  <Badge variant="green">
                    <BadgeCheckIcon className="size-3" />
                    {t("abha_kyc_verified")}
                  </Badge>
                ) : (
                  <Badge variant="yellow">{t("abha_kyc_not_verified")}</Badge>
                )
              }
            />
            <AbhaDetail
              label={t("abdm_link_source")}
              testId="patient-abha-source"
              value={[
                t(`abdm_link_source__${link.source}`),
