import { Page, Route } from "@playwright/test";

/**
 * Browser-side mocks for ABDM (ABHA) specs.
 *
 * Every ABDM call is answered in the browser, so no spec ever reaches ABDM or
 * sends an OTP. A call without a registered response fails with HTTP 501 and
 * is recorded in `unhandled`; it is never passed through to the backend.
 */

/** A synthetic, Verhoeff-valid Aadhaar number. */
export const TEST_AADHAAR = "234567890124";

export const ABDM_CONSENT_TEXT =
  "I, hereby declare that I am voluntarily sharing my Aadhaar number and demographic information issued by UIDAI, with National Health Authority (NHA) for the sole purpose of creation of ABHA number.";

export const ABDM_CONFIG = {
  enabled: true,
  cm_id: "sbx",
  abha_address_suffix: "@sbx",
  consent: {
    code: "abha-enrollment",
    version: "1.4",
    title: "Terms and Conditions",
    text: ABDM_CONSENT_TEXT,
  },
  otp: { length: 6, resend_wait_seconds: 60, max_resends: 2 },
};

export function abhaProfile(overrides: Record<string, unknown> = {}) {
  return {
    abha_number: "91-1111-2222-3333",
    abha_address: "asha.kumari@sbx",
    abha_addresses: ["asha.kumari@sbx"],
    name: "Asha Kumari",
    first_name: "Asha",
    middle_name: null,
    last_name: "Kumari",
    gender: "female",
    abdm_gender: "F",
    date_of_birth: "1990-04-12",
    year_of_birth: 1990,
    mobile: "9000000001",
    email: null,
    address: "[REDACTED_ADDRESS], Kochi",
    pincode: "682001",
    state_name: "KERALA",
    state_code: "32",
    district_name: "ERNAKULAM",
    district_code: "591",
    kyc_verified: true,
    status: "ACTIVE",
    photo: null,
    ...overrides,
  };
}

export function otpSent(overrides: Record<string, unknown> = {}) {
  return {
    transaction_id: "txn-otp",
    message: "OTP sent",
    masked_mobile: "******0001",
    otp_system: "abdm",
    resend: { available_in_seconds: 60, remaining: 2 },
    ...overrides,
  };
}

export function verified(
  profile: ReturnType<typeof abhaProfile>,
  overrides: Record<string, unknown> = {},
) {
  return {
    transaction_id: "txn-verified",
    status: "verified",
    accounts: [],
    profile,
    existing_patient: null,
    ...overrides,
  };
}

/** A 1x1 PNG, standing in for the ABHA card and QR images. */
export const TEST_PNG_BASE64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";

export interface MockResponse {
  status?: number;
  json: unknown;
}

export function abdmError(status: number, type: string): MockResponse {
  return {
    status,
    json: {
      errors: [
        {
          type,
          msg: type,
          abdm_code: null,
          loc: null,
          retry_after_seconds: null,
        },
      ],
    },
  };
}

export interface AbdmRequest {
  method: string;
  /** Path below `/api/v1/`, e.g. `abdm/abha/otp/request/`. */
  path: string;
  query: URLSearchParams;
  body: Record<string, unknown> | null;
}

type Responder = MockResponse | ((request: AbdmRequest) => MockResponse);

interface Handler {
  method: string;
  path: string | RegExp;
  respond: Responder;
}

const MOCKED_PATHS =
  /\/api\/v1\/(abdm\/|patient\/[^/]+\/abha\/|facility\/[^/]+\/abdm\/)/;

const matches = (handler: Handler, request: AbdmRequest) =>
  handler.method === request.method &&
  (typeof handler.path === "string"
    ? handler.path === request.path
    : handler.path.test(request.path));

export class AbdmMock {
  /** Every mocked call, in order. */
  readonly requests: AbdmRequest[] = [];
  /** Calls that had no registered response. */
  readonly unhandled: string[] = [];
  private handlers: Handler[] = [];

  /** Registers a response; a later registration for the same call wins. */
  on(method: string, path: string | RegExp, respond: Responder) {
    this.handlers.unshift({ method, path, respond });
    return this;
  }

  /** The calls made to an endpoint, e.g. `calls("POST", "abdm/abha/find/")`. */
  calls(method: string, path: string | RegExp) {
    return this.requests.filter((request) =>
      matches({ method, path, respond: { json: null } }, request),
    );
  }

  async handle(route: Route) {
    const request = route.request();
    const url = new URL(request.url());
    let body: AbdmRequest["body"] = null;
    try {
      body = request.postDataJSON();
    } catch {
      body = null;
    }
    const call: AbdmRequest = {
      method: request.method(),
      path: url.pathname.replace(/^\/api\/v1\//, ""),
      query: url.searchParams,
      body,
    };
    if (call.method === "OPTIONS") {
      return route.fulfill({ status: 204 });
    }
    this.requests.push(call);

    const handler = this.handlers.find((item) => matches(item, call));
    if (!handler) {
      this.unhandled.push(`${call.method} ${call.path}`);
      return route.fulfill({
        status: 501,
        json: { errors: [{ type: "unmocked", msg: call.path }] },
      });
    }
    const response =
      typeof handler.respond === "function"
        ? handler.respond(call)
        : handler.respond;
    return route.fulfill({ status: response.status ?? 200, json: response.json });
  }
}

/**
 * Routes every ABDM call of `page` to a new mock, with ABDM enabled by
 * default. Register responses with `mock.on(...)`.
 */
export async function mockAbdm(page: Page, config: unknown = ABDM_CONFIG) {
  const mock = new AbdmMock();
  mock.on("GET", "abdm/config/", { json: config });
  await page.route(MOCKED_PATHS, (route) => mock.handle(route));
  return mock;
}

