  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";

export interface MockResponse {
  status?: number;
  json: unknown;
}

export function abdmError(status: number, type: string): MockResponse {
  return {
    status,
    json: {
      errors: [
        {
          type,
          msg: type,
          abdm_code: null,
          loc: null,
          retry_after_seconds: null,
        },
      ],
    },
  };
}

export interface AbdmRequest {
  method: string;
  /** Path below `/api/v1/`, e.g. `abdm/abha/otp/request/`. */
  path: string;
  query: URLSearchParams;
  body: Record<string, unknown> | null;
}

type Responder = MockResponse | ((request: AbdmRequest) => MockResponse);

interface Handler {
  method: string;
  path: string | RegExp;
  respond: Responder;
}

const MOCKED_PATHS =
  /\/api\/v1\/(abdm\/|patient\/[^/]+\/abha\/|facility\/[^/]+\/abdm\/)/;

const matches = (handler: Handler, request: AbdmRequest) =>
  handler.method === request.method &&
  (typeof handler.path === "string"
    ? handler.path === request.path
    : handler.path.test(request.path));

export class AbdmMock {
  /** Every mocked call, in order. */
  readonly requests: AbdmRequest[] = [];
  /** Calls that had no registered response. */
  readonly unhandled: string[] = [];
  private handlers: Handler[] = [];

  /** Registers a response; a later registration for the same call wins. */
  on(method: string, path: string | RegExp, respond: Responder) {
    this.handlers.unshift({ method, path, respond });
    return this;
  }

  /** The calls made to an endpoint, e.g. `calls("POST", "abdm/abha/find/")`. */
  calls(method: string, path: string | RegExp) {
    return this.requests.filter((request) =>
      matches({ method, path, respond: { json: null } }, request),
    );
  }

  async handle(route: Route) {
    const request = route.request();
    const url = new URL(request.url());
    let body: AbdmRequest["body"] = null;
    try {
      body = request.postDataJSON();
    } catch {
      body = null;
    }
    const call: AbdmRequest = {
      method: request.method(),
      path: url.pathname.replace(/^\/api\/v1\//, ""),
      query: url.searchParams,
      body,
    };
    if (call.method === "OPTIONS") {
      return route.fulfill({ status: 204 });
    }
    this.requests.push(call);

    const handler = this.handlers.find((item) => matches(item, call));
    if (!handler) {
      this.unhandled.push(`${call.method} ${call.path}`);
      return route.fulfill({
        status: 501,
        json: { errors: [{ type: "unmocked", msg: call.path }] },
      });
    }
    const response =
      typeof handler.respond === "function"
        ? handler.respond(call)
        : handler.respond;
    return route.fulfill({ status: response.status ?? 200, json: response.json });
  }
}

/**
 * Routes every ABDM call of `page` to a new mock, with ABDM enabled by
 * default. Register responses with `mock.on(...)`.
 */
export async function mockAbdm(page: Page, config: unknown = ABDM_CONFIG) {
  const mock = new AbdmMock();
  mock.on("GET", "abdm/config/", { json: config });
  await page.route(MOCKED_PATHS, (route) => mock.handle(route));
  return mock;
}

