async function waitForCall(mock: AbdmMock, method: string, path: string) {
  await expect
    .poll(() => mock.calls(method, path).length, {
      message: `${method} ${path}`,
    })
    .toBeGreaterThan(0);
  return mock.calls(method, path)[0];
}

