import { expect, test } from "@playwright/test";
import {
  ABDM_CONSENT_TEXT,
  AbdmMock,
  abdmError,
  abhaProfile,
  mockAbdm,
  otpSent,
  TEST_AADHAAR,
  verified,
} from "tests/helper/abdm";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

const CONSENT = { agreed: true, version: "1.4" };

test.describe("ABHA identify flow", () => {
  let mock: AbdmMock;
  let facilityId: string;

  test.beforeEach(async ({ page }) => {
    facilityId = getFacilityId();
    mock = await mockAbdm(page);
    await page.goto(`/facility/${facilityId}/patient/create`);
    await expect(page.getByTestId("abdm-step-identifier")).toBeVisible();
  });

  test.afterEach(() => {
    expect(mock.unhandled).toEqual([]);
  });

  test("does not send the Aadhaar until the consent is agreed", async ({
    page,
  }) => {
    mock.on("POST", "abdm/abha/otp/request/", {
      json: otpSent({ otp_system: "aadhaar", masked_mobile: "******4321" }),
    });
    const submit = page.getByTestId("abdm-identifier-submit");
    const consent = page.getByTestId("abdm-consent-checkbox");

    await test.step("Show the consent text verbatim", async () => {
      await page.getByTestId("abdm-identifier-aadhaar").click();
      await expect(page.getByTestId("abdm-consent-text")).toHaveText(
        ABDM_CONSENT_TEXT,
      );
    });

    await test.step("Keep Send OTP disabled until I agree", async () => {
      await page.getByTestId("abdm-aadhaar-input").fill(TEST_AADHAAR);
      await expect(submit).toBeDisabled();
      await consent.click();
      await expect(submit).toBeEnabled();
      await consent.click();
      await expect(submit).toBeDisabled();
      expect(mock.calls("POST", "abdm/abha/otp/request/")).toHaveLength(0);
    });

    await test.step("Mask the Aadhaar to its last 4 digits", async () => {
      await consent.click();
      await expect(page.getByTestId("abdm-aadhaar-input")).toHaveValue(
        "XXXX XXXX 0124",
      );
    });

    await test.step("Send the Aadhaar with the consent", async () => {
      await submit.click();
      await expect(page.getByTestId("abdm-step-otp")).toBeVisible();
      expect(mock.calls("POST", "abdm/abha/otp/request/")[0].body).toEqual({
        identifier_type: "aadhaar",
        value: TEST_AADHAAR,
        consent: CONSENT,
        facility: facilityId,
      });
    });

    await test.step("Show the masked mobile and the resend countdown", async () => {
      await expect(page.getByTestId("abdm-otp-sent")).toContainText(
        "******4321",
      );
      const resend = page.getByTestId("abdm-resend-otp");
      await expect(resend).toBeDisabled();
      await expect(resend).toHaveText(/Resend OTP in \d+s/);
      await expect(page.getByText("2 resends left")).toBeVisible();
    });
  });

  test("logs in with a mobile number and picks one of its ABHAs", async ({
    page,
  }) => {
    const accounts = [
      {
        abha_number: "91-1111-2222-3333",
        abha_address: "asha.kumari@sbx",
        name: "Asha Kumari",
        gender: "F",
        kyc_verified: true,
        status: "ACTIVE",
        photo: null,
      },
      {
        abha_number: "91-4444-5555-6666",
        abha_address: "ravi.kumar@sbx",
        name: "Ravi Kumar",
        gender: "M",
        kyc_verified: false,
        status: "ACTIVE",
        photo: null,
      },
    ];
    mock
      .on("POST", "abdm/abha/otp/request/", { json: otpSent() })
      .on("POST", "abdm/abha/otp/verify/", {
        json: {
          transaction_id: "txn-login",
          status: "select_account",
          accounts,
          profile: null,
          existing_patient: null,
        },
      })
      .on("POST", "abdm/abha/select-account/", {
        json: verified(
          abhaProfile({
            name: "Ravi Kumar",
            abha_number: "91-4444-5555-6666",
            abha_address: "ravi.kumar@sbx",
            gender: "male",
          }),
          { transaction_id: "txn-login" },
        ),
      });

    await test.step("Request an OTP for the mobile", async () => {
      await page.getByTestId("abdm-identifier-mobile").click();
      await page.getByTestId("abdm-mobile-input").fill("9000000001");
      await page.getByTestId("abdm-identifier-submit").click();
      await expect(page.getByTestId("abdm-step-otp")).toBeVisible();
      expect(mock.calls("POST", "abdm/abha/otp/request/")[0].body).toEqual({
        identifier_type: "mobile",
        value: "9000000001",
        facility: facilityId,
      });
    });

    await test.step("Verify the OTP", async () => {
      await page.getByTestId("abdm-otp-input").fill("123456");
      await page.getByTestId("abdm-otp-submit").click();
      expect(
        (await waitForCall(mock, "POST", "abdm/abha/otp/verify/")).body,
      ).toEqual({ transaction_id: "txn-otp", otp: "123456" });
    });

    await test.step("Choose the second ABHA", async () => {
      const options = page.getByTestId("abdm-account-option");
      await expect(options).toHaveCount(2);
      await expect(options.nth(0)).toContainText("Asha Kumari");
      await expect(options.nth(0)).toContainText("asha.kumari@sbx");
      await options.nth(1).click();
    });

    await test.step("Show the chosen ABHA", async () => {
      await expect(page.getByTestId("abdm-step-result")).toBeVisible();
      await expect(page.getByTestId("abha-profile-name")).toHaveText(
        "Ravi Kumar",
      );
      await expect(page.getByTestId("abdm-use-for-registration")).toBeVisible();
      expect(mock.calls("POST", "abdm/abha/select-account/")[0].body).toEqual({
        transaction_id: "txn-login",
        abha_number: "91-4444-5555-6666",
      });
    });
  });

  test("finds a forgotten ABHA by mobile without sending an OTP first", async ({
    page,
  }) => {
    mock
      .on("POST", "abdm/abha/find/", {
        json: {
          transaction_id: "txn-find",
          accounts: [
            {
              index: 1,
              abha_number: "91-XXXX-XXXX-3333",
              name: "A**** K*****",
              gender: "F",
              kyc_verified: true,
              auth_methods: ["AADHAAR_OTP", "MOBILE_OTP"],
            },
            {
              index: 2,
              abha_number: "91-XXXX-XXXX-6666",
              name: "R*** K****",
              gender: "M",
              kyc_verified: false,
              auth_methods: ["MOBILE_OTP"],
            },
          ],
        },
      })
      .on("POST", "abdm/abha/find/otp/", {
        json: otpSent({ transaction_id: "txn-find" }),
      });

    await test.step("List the masked ABHAs on the mobile", async () => {
      await page.getByTestId("abdm-find-by-mobile").click();
      await page.getByTestId("abdm-find-mobile-input").fill("9000000001");
      await page.getByTestId("abdm-find-submit").click();
      const accounts = page.getByTestId("abdm-find-account");
      await expect(accounts).toHaveCount(2);
      await expect(accounts.nth(1)).toContainText("91-XXXX-XXXX-6666");
      expect(mock.calls("POST", "abdm/abha/find/otp/")).toHaveLength(0);
    });

    await test.step("Pick an ABHA and an OTP method", async () => {
      await page.getByTestId("abdm-find-account").nth(1).click();
      await expect(page.getByTestId("abdm-find-otp-system-abdm")).toBeChecked();
      await expect(
        page.getByTestId("abdm-find-otp-system-aadhaar"),
      ).toHaveCount(0);
      await page.getByTestId("abdm-find-send-otp").click();
    });

    await test.step("Go on to the OTP step", async () => {
      await expect(page.getByTestId("abdm-step-otp")).toBeVisible();
      expect(mock.calls("POST", "abdm/abha/find/otp/")[0].body).toEqual({
        transaction_id: "txn-find",
        index: 2,
        otp_system: "abdm",
      });
    });
  });

  test("offers creation when no ABHA is found, after looking up the Aadhaar", async ({
    page,
  }) => {
    mock
      .on("POST", "abdm/abha/otp/request/", abdmError(404, "abha_not_found"))
      .on("POST", "abdm/abha/create/otp/", {
        json: otpSent({
          transaction_id: "txn-create",
          otp_system: "aadhaar",
          masked_mobile: "******4321",
        }),
      });

    await test.step("Look up an unknown ABHA address", async () => {
      await page.getByTestId("abdm-identifier-abha_address").click();
      await page
        .getByTestId("abdm-abha-address-input")
        .fill("no.such.address@sbx");
      await page.getByTestId("abdm-identifier-submit").click();
      await expect(page.getByTestId("abdm-auth-method-identifier")).toHaveText(
        "no.such.address@sbx",
      );
      await page.getByTestId("abdm-auth-method-submit").click();
    });

    await test.step("Offer to check the address or create an ABHA", async () => {
      await expect(page.getByTestId("abdm-step-not-found")).toBeVisible();
      await expect(page.getByTestId("abdm-not-found-value")).toHaveText(
        "no.such.address@sbx",
      );
      await expect(page.getByTestId("abdm-not-found-check")).toBeVisible();
      await page.getByTestId("abdm-not-found-create").click();
    });

    await test.step("Ask for the Aadhaar and consent", async () => {
      await expect(page.getByTestId("abdm-step-create-aadhaar")).toBeVisible();
      await expect(page.getByTestId("abdm-consent-text")).toHaveText(
        ABDM_CONSENT_TEXT,
      );
      await page.getByTestId("abdm-aadhaar-input").fill(TEST_AADHAAR);
      await expect(page.getByTestId("abdm-create-aadhaar-submit")).toBeDisabled();
      await page.getByTestId("abdm-consent-checkbox").click();
      await page.getByTestId("abdm-create-aadhaar-submit").click();
    });

    await test.step("Create only after the Aadhaar is not found either", async () => {
      await expect(page.getByTestId("abdm-step-create-otp")).toBeVisible();
      const lookups = mock.calls("POST", "abdm/abha/otp/request/");
      expect(lookups.map((call) => call.body?.identifier_type)).toEqual([
        "abha_address",
        "aadhaar",
      ]);
      expect(lookups[1].body?.consent).toEqual(CONSENT);
      expect(mock.calls("POST", "abdm/abha/create/otp/")[0].body).toEqual({
        aadhaar: TEST_AADHAAR,
        consent: CONSENT,
        facility: facilityId,
      });
    });
  });

  test("creates an ABHA, verifying the mobile and asking for an ABHA address", async ({
    page,
  }) => {
    const created = abhaProfile({
      abha_address: "91111122223333@sbx",
      abha_addresses: ["91111122223333@sbx"],
      mobile: "9000000002",
    });
    mock
      .on("POST", "abdm/abha/otp/request/", abdmError(404, "abha_not_found"))
      .on("POST", "abdm/abha/create/otp/", {
        json: otpSent({
          transaction_id: "txn-create",
          otp_system: "aadhaar",
          masked_mobile: "******4321",
        }),
      })
      .on("POST", "abdm/abha/create/verify/", {
        json: {
          transaction_id: "txn-create",
          is_new: true,
          profile: created,
          mobile_verification_required: true,
          abha_address_required: true,
          existing_patient: null,
        },
      })
      .on("POST", "abdm/abha/create/mobile/otp/", {
        json: otpSent({
          transaction_id: "txn-create",
          masked_mobile: "******0002",
        }),
      })
      .on("POST", "abdm/abha/create/mobile/verify/", {
        json: { transaction_id: "txn-create", profile: created },
      })
      .on("GET", "abdm/abha/create/address-suggestions/", {
        json: { suggestions: ["asha.kumari", "asha1990"] },
      })
      .on("POST", "abdm/abha/create/address/", {
        json: {
          transaction_id: "txn-create",
          profile: {
            ...created,
            abha_address: "asha.kumari@sbx",
            abha_addresses: ["asha.kumari@sbx", "91111122223333@sbx"],
          },
        },
      });

    await test.step("Create with the Aadhaar already entered", async () => {
      await page.getByTestId("abdm-identifier-aadhaar").click();
      await page.getByTestId("abdm-aadhaar-input").fill(TEST_AADHAAR);
      await page.getByTestId("abdm-consent-checkbox").click();
      await page.getByTestId("abdm-identifier-submit").click();
      await expect(page.getByTestId("abdm-step-not-found")).toBeVisible();
      await expect(page.getByTestId("abdm-not-found-value")).toHaveText(
        "XXXX XXXX 0124",
      );
      await expect(page.getByTestId("abdm-aadhaar-input")).toHaveCount(0);
      await page.getByTestId("abdm-not-found-create").click();
    });

    await test.step("Verify the Aadhaar OTP with a mobile number", async () => {
      await expect(page.getByTestId("abdm-step-create-otp")).toBeVisible();
      expect(mock.calls("POST", "abdm/abha/create/otp/")[0].body).toEqual({
        aadhaar: TEST_AADHAAR,
        consent: CONSENT,
        facility: facilityId,
      });
      await page.getByTestId("abdm-otp-input").fill("123456");
      await page.getByTestId("abdm-create-mobile-input").fill("9000000002");
      await page.getByTestId("abdm-create-otp-submit").click();
    });

    await test.step("Verify the new mobile", async () => {
      await expect(page.getByTestId("abdm-step-create-mobile")).toBeVisible();
      await expect(page.getByTestId("abdm-otp-sent")).toContainText(
        "******0002",
      );
      expect(mock.calls("POST", "abdm/abha/create/verify/")[0].body).toEqual({
        transaction_id: "txn-create",
        otp: "123456",
        mobile: "9000000002",
      });
      expect(mock.calls("POST", "abdm/abha/create/mobile/otp/")).toHaveLength(
        1,
      );
      await page.getByTestId("abdm-otp-input").fill("654321");
      await page.getByTestId("abdm-create-mobile-submit").click();
    });

    await test.step("Choose an ABHA address; it cannot be skipped", async () => {
      const step = page.getByTestId("abdm-step-address");
      await expect(step).toBeVisible();
      await expect(step.getByRole("button", { name: /skip/i })).toHaveCount(0);
      await expect(page.getByTestId("abdm-address-suggestion")).toHaveCount(2);
      await page
        .getByTestId("abdm-address-suggestion")
        .filter({ hasText: "asha.kumari@sbx" })
        .click();
      await expect(page.getByTestId("abdm-address-input")).toHaveValue(
        "asha.kumari",
      );
      await page.getByTestId("abdm-address-submit").click();
    });

    await test.step("Show the new ABHA", async () => {
      await expect(page.getByTestId("abdm-step-result")).toBeVisible();
      await expect(
        page.getByText("A new ABHA was created for the patient."),
      ).toBeVisible();
      await expect(page.getByTestId("abha-profile-address")).toHaveText(
        "asha.kumari@sbx",
      );
      expect(mock.calls("POST", "abdm/abha/create/address/")[0].body).toEqual({
        transaction_id: "txn-create",
        abha_address: "asha.kumari",
      });
      expect(
        mock
          .calls("GET", "abdm/abha/create/address-suggestions/")[0]
          .query.get("transaction_id"),
      ).toBe("txn-create");
    });
  });

  test("shows the existing ABHA when the Aadhaar already has one", async ({
    page,
  }) => {
    mock
      .on("POST", "abdm/abha/otp/request/", abdmError(404, "abha_not_found"))
      .on("POST", "abdm/abha/create/otp/", {
        json: otpSent({ transaction_id: "txn-create", otp_system: "aadhaar" }),
      })
      .on("POST", "abdm/abha/create/verify/", {
        json: {
          transaction_id: "txn-create",
          is_new: false,
          profile: abhaProfile(),
          mobile_verification_required: false,
          abha_address_required: false,
          existing_patient: null,
        },
      });

    await page.getByTestId("abdm-identifier-aadhaar").click();
    await page.getByTestId("abdm-aadhaar-input").fill(TEST_AADHAAR);
    await page.getByTestId("abdm-consent-checkbox").click();
    await page.getByTestId("abdm-identifier-submit").click();
    await page.getByTestId("abdm-not-found-create").click();
    await page.getByTestId("abdm-otp-input").fill("123456");
    await page.getByTestId("abdm-create-mobile-input").fill("9000000001");
    await page.getByTestId("abdm-create-otp-submit").click();

    await expect(page.getByTestId("abdm-step-result")).toBeVisible();
    await expect(
      page.getByText(/An ABHA already exists for this Aadhaar/),
    ).toBeVisible();
    await expect(page.getByTestId("abha-profile-name")).toHaveText(
      "Asha Kumari",
    );
    expect(mock.calls("POST", "abdm/abha/create/mobile/otp/")).toHaveLength(0);
    expect(
      mock.calls("GET", "abdm/abha/create/address-suggestions/"),
    ).toHaveLength(0);
  });
});

