/** Waits for the `count`-th call to an endpoint and returns it. */
export async function waitForCall(
  mock: AbdmMock,
  method: string,
  path: string | RegExp,
  count = 1,
) {
  await expect
    .poll(() => mock.calls(method, path).length, {
      message: `${method} ${path}`,
    })
    .toBeGreaterThanOrEqual(count);
  return mock.calls(method, path)[count - 1];
}

