   isValidAbhaAddressLogin,
   isValidAbhaNumber,
   isValidMobile,
   provenanceFor,
 } from "@/components/Abdm/utils";

 import mutate from "@/Utils/request/mutate";
 import {
   AbhaIdentifierType,
   AbhaOtpRequest,
   AbhaOtpSent,
 } from "@/types/abdm/abdm";
 import abdmApi from "@/types/abdm/abdmApi";

 const IDENTIFIER_TYPES: AbhaIdentifierType[] = [
   "abha_number",
   "abha_address",
   "mobile",
   "aadhaar",
 ];

 export function IdentifierStep({
   initialType,
 }: {
   initialType?: AbhaIdentifierType;
 }) {
   const { t } = useTranslation();
   const { config, facilityId, facts, rememberFact, consent, goTo } =
     useAbhaFlow();

   const [identifierType, setIdentifierType] = useState<AbhaIdentifierType>(
     () => initialType ?? (facts.mobile ? "mobile" : "abha_number"),
   );
   const [abhaNumber, setAbhaNumber] = useState(
     () => facts.abha_number?.value ?? "",
   );
   const [abhaAddress, setAbhaAddress] = useState(
     () => facts.abha_address?.value ?? "",
   );
   const [mobile, setMobile] = useState(() => facts.mobile?.value ?? "");
   const [aadhaar, setAadhaar] = useState(() => facts.aadhaar?.value ?? "");
   const [consented, setConsented] = useState(() => !!facts.aadhaar);
   const [showErrors, setShowErrors] = useState(false);

   const otpMutation = useMutation({
     mutationFn: mutate(abdmApi.requestOtp, { silent: abdmSilent }),
     onSuccess: (otpSent: AbhaOtpSent, variables: AbhaOtpRequest) =>
       goTo({
         name: "otp",
         otpSent,
         identifierType: variables.identifier_type,
         value: variables.value,
       }),
     onError: (error: Error, variables: AbhaOtpRequest) => {
       if (isAbdmErrorType(error, "abha_not_found")) {
         goTo({
           name: "not_found",
           identifierType: variables.identifier_type,
           value: variables.value,
         });
       }
     },
   });

   const fieldError = (() => {
     switch (identifierType) {
       case "abha_number":
         return isValidAbhaNumber(abhaNumber)
           ? undefined
           : t("abdm_validation__abha_number");
       case "abha_address":
         return isValidAbhaAddressLogin(abhaAddress)
           ? undefined
           : t("abdm_validation__abha_address");
       case "mobile":
         return isValidMobile(mobile) ? undefined : t("abdm_validation__mobile");
       case "aadhaar":
         return isValidAadhaar(aadhaar)
           ? undefined
           : t("abdm_validation__aadhaar");
     }
   })();

   const canSubmit =
     !otpMutation.isPending && (identifierType !== "aadhaar" || consented);

   const handleSubmit = (event: SubmitEvent) => {
     event.preventDefault();
     setShowErrors(true);
     if (fieldError || !canSubmit) return;

     switch (identifierType) {
       case "abha_number": {
         const value = formatAbhaNumber(abhaNumber);
         rememberFact("abha_number", value);
         goTo({ name: "auth_method", identifierType, value });
         return;
       }
       case "abha_address": {
         const value = abhaAddress.trim();
         rememberFact("abha_address", value);
         goTo({ name: "auth_method", identifierType, value });
         return;
       }
       case "mobile":
         rememberFact("mobile", mobile);
         otpMutation.mutate({
           identifier_type: "mobile",
           value: mobile,
           facility: facilityId,
         });
         return;
       case "aadhaar":
         rememberFact("aadhaar", aadhaar);
         otpMutation.mutate({
           identifier_type: "aadhaar",
           value: aadhaar,
           consent,
           facility: facilityId,
         });
         return;
     }
   };

   const error = showErrors ? fieldError : undefined;
   const requestError = isAbdmErrorType(otpMutation.error, "abha_not_found")
     ? null
     : otpMutation.error;

   return (
     <StepLayout
       title={t("abdm_identify_title")}
       description={t("abdm_identify_description")}
       testId="abdm-step-identifier"
     >
       <form className="flex flex-col gap-4" onSubmit={handleSubmit} noValidate>
         <Tabs
           value={identifierType}
           onValueChange={(value) => {
             setIdentifierType(value as AbhaIdentifierType);
             setShowErrors(false);
             otpMutation.reset();
           }}
         >
           <TabsList
             className="h-auto w-full flex-wrap"
             aria-label={t("abdm_identifier_type")}
           >
             {IDENTIFIER_TYPES.map((type) => (
               <TabsTrigger
                 key={type}
                 value={type}
                 className="flex-1"
                 data-testid={`abdm-identifier-${type}`}
               >
                 {t(`abdm_identifier__${type}`)}
               </TabsTrigger>
             ))}
           </TabsList>

           <TabsContent value="abha_number" className="pt-2">
             <AbdmField
               label={t("abha_number")}
               placeholder={t("abdm_abha_number_placeholder")}
               inputMode="numeric"
               maxLength={17}
               value={abhaNumber}
               onChange={(e) =>
                 setAbhaNumber(e.target.value.replace(/[^\d-]/g, ""))
               }
               onBlur={() => setAbhaNumber((v) => formatAbhaNumber(v))}
               error={error}
               provenance={provenanceFor(
                 facts.abha_number,
                 abhaNumber,
                 "abha_number",
               )}
               data-testid="abdm-abha-number-input"
             />
           </TabsContent>

           <TabsContent value="abha_address" className="pt-2">
             <AbdmField
               label={t("abha_address")}
               placeholder={t("abdm_abha_address_placeholder")}
               value={abhaAddress}
               onChange={(e) => setAbhaAddress(e.target.value.trim())}
               hint={t("abdm_abha_address_login_hint", {
                 suffix: getAbhaAddressSuffix(config),
               })}
               error={error}
               provenance={provenanceFor(
                 facts.abha_address,
                 abhaAddress,
                 "abha_address",
               )}
               data-testid="abdm-abha-address-input"
             />
           </TabsContent>

           <TabsContent value="mobile" className="pt-2">
             <AbdmField
               label={t("mobile_number")}
               prefix="+91"
               inputMode="numeric"
               maxLength={10}
               placeholder={t("abdm_mobile_placeholder")}
               value={mobile}
               onChange={(e) =>
                 setMobile(e.target.value.replace(/\D/g, "").slice(0, 10))
               }
               hint={t("abdm_mobile_login_hint")}
               error={error}
               provenance={provenanceFor(facts.mobile, mobile, "mobile")}
               data-testid="abdm-mobile-input"
             />
           </TabsContent>

           <TabsContent value="aadhaar" className="pt-2">
             <AadhaarConsentInput
               value={aadhaar}
               onChange={(value) => {
                 setAadhaar(value);
                 if (facts.aadhaar && value !== facts.aadhaar.value) {
                   setConsented(false);
                 }
               }}
               consented={consented}
               onConsentChange={setConsented}
               consent={config.consent}
               error={error}
               provenance={
                 provenanceFor(facts.aadhaar, aadhaar, "aadhaar")?.provenance
               }
             />
           </TabsContent>
         </Tabs>

         {requestError && <AbdmErrorAlert error={requestError} />}

         <div className="flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-between">
           <Button
             type="button"
             variant="link"
             className="h-auto justify-start px-0"
             onClick={() => goTo({ name: "find" })}
             data-testid="abdm-find-by-mobile"
           >
             <SearchIcon />
             {t("abdm_forgot_abha_find_by_mobile")}
           </Button>
           <Button
             type="submit"
             variant="primary"
             disabled={!canSubmit}
             data-testid="abdm-identifier-submit"
           >
             {otpMutation.isPending && <Loader2Icon className="animate-spin" />}
             {identifierType === "mobile" || identifierType === "aadhaar"
               ? t("abdm_send_otp")
               : t("continue")}
           </Button>
         </div>
       </form>
     </StepLayout>
   );
 }

