/**
 * Types for ABDM Milestone 1 (ABHA creation and verification).
 *
 * The browser never talks to ABDM directly: CARE's backend keeps every ABDM
 * token server-side and hands the frontend an opaque `transaction_id` per
 * flow. All shapes mirror the contract served under `/api/v1/abdm/`.
 */

export type AbhaIdentifierType =
  "mobile" | "aadhaar" | "abha_number" | "abha_address";

/** `aadhaar` = OTP to the Aadhaar-linked mobile, `abdm` = OTP to the ABHA mobile. */
export type AbhaOtpSystem = "aadhaar" | "abdm";

export type AbhaGender = "male" | "female" | "transgender" | "non_binary";

export interface AbdmConsentText {
  code: string;
  version: string;
  /** e.g. "Terms and Conditions" */
  title?: string;
  /** Shown verbatim; the patient agrees to exactly this text. */
  text: string;
}

export interface AbdmOtpPolicy {
  length: number;
  resend_wait_seconds: number;
  max_resends: number;
}

export interface AbdmConfig {
  enabled: boolean;
  cm_id: string;
  /** e.g. "@sbx"; appended by the backend when an ABHA address omits it. */
  abha_address_suffix: string;
  consent: AbdmConsentText;
  otp: AbdmOtpPolicy;
}

export interface AbhaConsentAgreement {
  agreed: true;
  version: string;
}

export interface AbhaProfile {
  /** Hyphenated, e.g. "91-1234-5678-9012". */
  abha_number: string | null;
  /** Preferred ABHA address, e.g. "john.doe@sbx". */
  abha_address: string | null;
  abha_addresses: string[];
  name: string;
  first_name: string | null;
  middle_name: string | null;
  last_name: string | null;
  /** Mapped to CARE's gender vocabulary. */
  gender: AbhaGender | null;
  /** Raw ABDM gender code: "M" | "F" | "O" | "T" | "D" | "U". */
  abdm_gender: string | null;
  /** "YYYY-MM-DD" when the full date of birth is known. */
  date_of_birth: string | null;
  year_of_birth: number | null;
  /** 10 digits, without a country code. */
  mobile: string | null;
  email: string | null;
  address: string | null;
  pincode: string | null;
  state_name: string | null;
  state_code: string | null;
  district_name: string | null;
  district_code: string | null;
  kyc_verified: boolean;
  status: string | null;
  /** Base64 JPEG; returned live by the backend and never stored. */
  photo: string | null;
}

/** A row in the account chooser when one mobile carries several ABHAs. */
export interface AbhaAccount {
  abha_number: string | null;
  abha_address: string | null;
  name: string;
  gender: string | null;
  kyc_verified: boolean | null;
  status: string | null;
  photo: string | null;
}

export interface AbhaOtpResend {
  available_in_seconds: number;
  remaining: number;
}

export interface AbhaOtpSent {
  transaction_id: string;
  /** ABDM's message; safe to show to the user. */
  message: string;
  /** e.g. "******1234" */
  masked_mobile: string | null;
  otp_system: AbhaOtpSystem;
  resend: AbhaOtpResend;
}

export interface AbhaExistingPatient {
  id: string;
  name: string;
  can_view: boolean;
}

export interface AbhaVerified {
  transaction_id: string;
  status: "verified" | "select_account";
  accounts: AbhaAccount[];
  profile: AbhaProfile | null;
  existing_patient: AbhaExistingPatient | null;
}

/** A masked row returned by "find ABHA by mobile" (no OTP is sent). */
export interface AbhaFindAccount {
  index: number | string;
  abha_number: string;
  name: string;
  gender: string | null;
  kyc_verified: boolean | null;
  /** e.g. ["AADHAAR_OTP", "MOBILE_OTP"] */
  auth_methods: string[];
}

export interface AbhaFindResponse {
  transaction_id: string;
  accounts: AbhaFindAccount[];
}

export interface AbhaCreateVerified {
  transaction_id: string;
  is_new: boolean;
  profile: AbhaProfile;
  mobile_verification_required: boolean;
  abha_address_required: boolean;
  existing_patient: AbhaExistingPatient | null;
}

export interface AbhaTransactionProfile {
  transaction_id: string;
  profile: AbhaProfile;
}

export interface AbhaFile {
  content_type: string;
  /** Base64-encoded file contents. */
  data: string;
}

export interface AbhaOtpRequest {
  identifier_type: AbhaIdentifierType;
  value: string;
  otp_system?: AbhaOtpSystem;
  consent?: AbhaConsentAgreement;
  facility?: string;
}

export interface AbhaCreateOtpRequest {
  aadhaar: string;
  consent: AbhaConsentAgreement;
  facility?: string;
}

export type AbhaLinkSource = "verification" | "creation" | "profile_share";

export interface AbhaLinkedBy {
  id: string;
  username: string;
  first_name: string;
  last_name: string;
}

export interface PatientAbhaLinked {
  linked: true;
  id: string;
  abha_number: string | null;
  abha_address: string | null;
  abha_addresses: string[];
  kyc_verified: boolean;
  profile: AbhaProfile | null;
  source: AbhaLinkSource;
  verification_method: string | null;
  linked_by: AbhaLinkedBy | null;
  linked_at: string;
}

export type PatientAbha = { linked: false } | PatientAbhaLinked;

export type PatientAbhaLinkRequest =
  { transaction_id: string } | { profile_share: string };

export interface AbdmError {
  /** e.g. "abha_not_found", "invalid_otp", "resend_too_soon" */
  type: string;
  msg: string;
  abdm_code?: string | null;
  loc?: (string | number)[] | null;
  retry_after_seconds?: number | null;
  /** Set for `abha_linked_to_other_patient`. */
  patient?: AbhaExistingPatient | null;
}

/* Phase B: facility HIP configuration and scan & share */

export interface FacilityAbdmCounter {
  code: string;
  name: string;
}

export interface FacilityAbdmShareUrl {
  counter: string;
  url: string;
}

export type FacilityAbdmConfig =
  | { configured: false }
  | {
      configured: true;
      hip_id: string;
      hip_name: string;
      counters: FacilityAbdmCounter[];
      share_urls: FacilityAbdmShareUrl[];
    };

export interface FacilityAbdmConfigUpdate {
  hip_id: string;
  hip_name: string;
  counters: FacilityAbdmCounter[];
}

export type AbhaProfileShareStatus =
  "pending" | "registered" | "linked" | "failed";

export interface AbhaProfileShare {
  id: string;
  token_number: string | number | null;
  counter_code: string | null;
  abha_number: string | null;
  abha_address: string | null;
  profile: AbhaProfile | null;
  status: AbhaProfileShareStatus;
  patient: { id: string; name: string } | null;
  created_date: string;
  expires_at: string | null;
}

