import { FileCheck2Icon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { FactKey, FactProvenance } from "@/components/Abdm/types";

interface ProvenanceHintProps {
  provenance: FactProvenance;
  /** Which value was reused; words the "entered earlier" hint. */
  field?: FactKey;
  className?: string;
}

/**
 * A small marker telling the user where a prefilled value came from, so a
 * value is never reused silently ("never ask twice").
 */
export function ProvenanceHint({
  provenance,
  field,
  className,
}: ProvenanceHintProps) {
  const { t } = useTranslation();

  const label =
    provenance === "entered" && field
      ? t(`abdm_provenance__entered_${field}`)
      : t(`abdm_provenance__${provenance}`);

  return (
    <span
      data-slot="provenance-hint"
      className={cn(
        "inline-flex items-center gap-1 rounded-sm bg-primary-50 px-1.5 py-0.5 text-xs font-normal text-primary-800",
        className,
      )}
    >
      <FileCheck2Icon className="size-3" aria-hidden />
      {label}
    </span>
  );
}
