import { useMutation, useQueryClient } from "@tanstack/react-query";
import { AlertTriangleIcon, CheckIcon, Link2Icon } from "lucide-react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbhaExistingPatientAlert } from "@/components/Abdm/AbhaExistingPatientAlert";
import { AbhaFlowResult } from "@/components/Abdm/types";
import {
  abdmSilent,
  getAbdmError,
  phoneToMobile,
} from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import { formatDateTime } from "@/Utils/utils";
import abdmApi from "@/types/abdm/abdmApi";
import { PatientRead } from "@/types/emr/patient/patient";

const normalizeName = (name?: string | null) =>
  (name ?? "").toLowerCase().replace(/\s+/g, " ").trim();

const yearOf = (date?: string | null, year?: number | null) =>
  date ? Number(date.slice(0, 4)) : (year ?? undefined);

/**
 * The last step of "Link ABHA" on a patient's page: compares the verified
 * ABHA with the patient record so a mismatch is seen before the two are
 * linked.
 */
export function AbhaLinkReview({
  patient,
  facilityId,
  result,
  onLinked,
}: {
  patient: PatientRead;
  facilityId?: string;
  result: AbhaFlowResult;
  onLinked: () => void;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { profile } = result;

  const linkMutation = useMutation({
    mutationFn: mutate(abdmApi.linkPatientAbha, {
      pathParams: { patientId: patient.id },
      silent: abdmSilent,
    }),
    onSuccess: () => {
      toast.success(t("abdm_abha_linked"));
      queryClient.invalidateQueries({ queryKey: ["patient-abha", patient.id] });
      queryClient.invalidateQueries({ queryKey: ["patient", patient.id] });
      onLinked();
    },
  });

  if (result.existingPatient && result.existingPatient.id !== patient.id) {
    return (
      <AbhaExistingPatientAlert
        patient={result.existingPatient}
        facilityId={facilityId}
      />
    );
  }

  const formatDob = (date?: string | null, year?: number | null) =>
    date ? formatDateTime(date, "DD/MM/YYYY") : year ? String(year) : "-";

  const patientYear = yearOf(patient.date_of_birth, patient.year_of_birth);
  const abhaYear = yearOf(profile.date_of_birth, profile.year_of_birth);
  const patientMobile = phoneToMobile(patient.phone_number);

  const rows = [
    {
      key: "name",
      label: t("name"),
      record: patient.name,
      abha: profile.name,
      matches: normalizeName(patient.name) === normalizeName(profile.name),
    },
    {
      key: "gender",
      label: t("gender"),
      record: patient.gender ? t(`GENDER__${patient.gender}`) : "-",
      abha: profile.gender ? t(`GENDER__${profile.gender}`) : "-",
      matches: !profile.gender || profile.gender === patient.gender,
    },
    {
      key: "date_of_birth",
      label: t("date_of_birth"),
      record: formatDob(patient.date_of_birth, patient.year_of_birth),
      abha: formatDob(profile.date_of_birth, profile.year_of_birth),
      matches:
        patient.date_of_birth && profile.date_of_birth
          ? patient.date_of_birth === profile.date_of_birth
          : !abhaYear || patientYear === abhaYear,
    },
    {
      key: "mobile",
      label: t("mobile_number"),
      record: patientMobile ?? patient.phone_number ?? "-",
      abha: profile.mobile ?? "-",
      matches: !profile.mobile || patientMobile === profile.mobile,
    },
  ];
  const mismatches = rows.filter((row) => !row.matches).length;

  const linkError = linkMutation.error;
  const otherPatient = getAbdmError(linkError)?.patient;

  return (
    <div className="flex flex-col gap-3" data-testid="abdm-link-review">
      <div className="overflow-x-auto rounded-md border border-gray-200">
        <table className="w-full text-left text-sm">
          <caption className="sr-only">{t("abdm_link_review_caption")}</caption>
          <thead className="bg-gray-50 text-xs text-gray-600">
            <tr>
              <th scope="col" className="px-3 py-2 font-medium">
                <span className="sr-only">{t("abdm_link_review_field")}</span>
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                {t("abdm_link_review_patient_record")}
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                {t("abdm_link_review_abha")}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr
                key={row.key}
                className={cn(
                  "border-t border-gray-200",
                  !row.matches && "bg-yellow-50",
                )}
                data-testid={`abdm-link-review-${row.key}`}
                data-matches={row.matches}
              >
                <th
                  scope="row"
                  className="px-3 py-2 font-normal whitespace-nowrap text-gray-600"
                >
                  {row.label}
                </th>
                <td className="px-3 py-2 font-medium text-gray-900">
                  {row.record}
                </td>
                <td className="px-3 py-2 font-medium text-gray-900">
                  <span className="inline-flex items-center gap-1.5">
                    {row.abha}
                    {row.matches ? (
                      <CheckIcon
                        className="size-4 text-green-700"
                        aria-label={t("abdm_link_review_matches")}
                      />
                    ) : (
                      <AlertTriangleIcon
                        className="size-4 text-yellow-700"
                        aria-label={t("abdm_link_review_differs")}
                      />
                    )}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {mismatches > 0 && (
        <Alert className="border-yellow-200 bg-yellow-50">
          <AlertTriangleIcon className="text-yellow-700" />
          <AlertDescription className="text-yellow-900">
            {t("abdm_link_review_mismatch", { count: mismatches })}
          </AlertDescription>
        </Alert>
      )}

      {linkError &&
        (otherPatient ? (
          <AbhaExistingPatientAlert
            patient={otherPatient}
            facilityId={facilityId}
          />
        ) : (
          <AbdmErrorAlert error={linkError} />
        ))}

      <Button
        type="button"
        onClick={() =>
          linkMutation.mutate({ transaction_id: result.transactionId })
        }
        disabled={linkMutation.isPending || !!otherPatient}
        data-testid="abdm-link-patient"
      >
        <Link2Icon />
        {t("abdm_link_to_patient")}
      </Button>
    </div>
  );
}

