import { ExternalLinkIcon, UserRoundCheckIcon } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { buttonVariants } from "@/components/ui/button";

import { AbhaExistingPatient } from "@/types/abdm/abdm";

export function getPatientUrl(patientId: string, facilityId?: string) {
  return facilityId
    ? `/facility/${facilityId}/patient/${patientId}`
    : `/patient/${patientId}`;
}

/**
 * Shown when the ABHA in hand already belongs to a CARE patient: one ABHA is
 * linked to at most one patient, so the user is pointed to that record.
 */
export function AbhaExistingPatientAlert({
  patient,
  facilityId,
  className,
}: {
  patient: AbhaExistingPatient;
  facilityId?: string;
  className?: string;
}) {
  const { t } = useTranslation();

  return (
    <Alert
      className={cn("border-yellow-200 bg-yellow-50", className)}
      data-testid="abdm-existing-patient"
    >
      <UserRoundCheckIcon className="text-yellow-800" />
      <AlertTitle className="line-clamp-none text-yellow-900">
        {t("abdm_abha_already_linked_title")}
      </AlertTitle>
      <AlertDescription className="text-yellow-900">
        <p>
          {t("abdm_abha_already_linked_description", { name: patient.name })}
        </p>
        {patient.can_view && (
          <Link
            href={getPatientUrl(patient.id, facilityId)}
            className={cn(
              buttonVariants({ variant: "outline", size: "sm" }),
              "mt-1",
            )}
            data-testid="abdm-open-patient"
          >
            <ExternalLinkIcon />
            {t("abdm_open_patient")}
          </Link>
        )}
      </AlertDescription>
    </Alert>
  );
}
