import { faker } from "@faker-js/faker";
import { expect, Page, test } from "@playwright/test";
import {
  AbdmMock,
  abdmError,
  abhaProfile,
  mockAbdm,
  otpSent,
  verified,
  waitForCall,
} from "tests/helper/abdm";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

const LINK_PATH = /^patient\/[^/]+\/abha\/link\/$/;

async function verifyByMobile(page: Page, mobile: string) {
  await test.step("Verify the ABHA with a mobile OTP", async () => {
    await page.getByTestId("abdm-identifier-mobile").click();
    await page.getByTestId("abdm-mobile-input").fill(mobile);
    await page.getByTestId("abdm-identifier-submit").click();
    await page.getByTestId("abdm-otp-input").fill("123456");
    await page.getByTestId("abdm-otp-submit").click();
    await expect(page.getByTestId("abdm-step-result")).toBeVisible();
  });
}

async function openAdditionalDetails(page: Page) {
  const section = page.getByRole("button", { name: "Additional Details" });
  if ((await section.textContent())?.toLowerCase().includes("optional")) {
    await section.click();
  }
}

test.describe("ABHA in patient registration", () => {
  let mock: AbdmMock;
  let facilityId: string;

  test.beforeEach(async ({ page }) => {
    facilityId = getFacilityId();
    mock = await mockAbdm(page);
    mock.on("POST", "abdm/abha/otp/request/", { json: otpSent() });
    await page.goto(`/facility/${facilityId}/patient/create`);
    await expect(page.getByTestId("abdm-registration-step")).toBeVisible();
  });

  test.afterEach(() => {
    expect(mock.unhandled).toEqual([]);
  });

  test("fills the form from a KYC-verified ABHA and links it after registering", async ({
    page,
  }) => {
    const profile = abhaProfile({
      name: faker.person.fullName(),
      mobile: `9${faker.string.numeric(9)}`,
    });
    mock
      .on("POST", "abdm/abha/otp/verify/", { json: verified(profile) })
      .on("POST", LINK_PATH, {
        json: { linked: true, abha_number: profile.abha_number },
      });

    await verifyByMobile(page, profile.mobile);
    await page.getByTestId("abdm-use-for-registration").click();

    await test.step("Lock name, sex and date of birth", async () => {
      await expect(page.getByTestId("abdm-registration-abha")).toContainText(
        profile.abha_number,
      );
      const name = page.getByRole("textbox", { name: /name.*\*/i });
      await expect(name).toHaveValue(profile.name);
      await expect(name).toBeDisabled();
      const female = page.getByRole("radio", { name: "Female", exact: true });
      await expect(female).toBeChecked();
      await expect(female).toBeDisabled();
      for (const [placeholder, value] of [
        ["DD", "12"],
        ["MM", "04"],
        ["YYYY", "1990"],
      ]) {
        const input = page.getByPlaceholder(placeholder, { exact: true });
        await expect(input).toHaveValue(value);
        await expect(input).toBeDisabled();
      }
    });

    await test.step("Keep phone and address editable", async () => {
      const phone = page.getByRole("textbox", { name: /phone number.*\*/i });
      await expect(phone).toBeEditable();
      await expect(phone).toHaveValue(
        new RegExp(profile.mobile.slice(-4).split("").join("\\s?") + "$"),
      );
      await openAdditionalDetails(page);
      const address = page.getByRole("textbox", { name: "Address" });
      await expect(address).toHaveValue("[REDACTED_ADDRESS], Kochi");
      await expect(address).toBeEditable();
      const pincode = page.getByRole("spinbutton", { name: "PIN Code" });
      await expect(pincode).toHaveValue("682001");
      await expect(pincode).toBeEditable();
    });

    await test.step("Mark the values that came from the ABHA", async () => {
      await expect(
        page.getByText(
          "State and district matched from the ABHA address. Please confirm.",
        ),
      ).toBeVisible();
      await expect(
        page.locator("form").getByText("From ABHA", { exact: true }),
      ).toHaveCount(7);
    });

    await test.step("Register the patient, then link the ABHA", async () => {
      const createRequest = page.waitForRequest(
        (request) =>
          request.method() === "POST" &&
          new URL(request.url()).pathname === "/api/v1/patient/",
      );
      await page.getByRole("button", { name: /register patient/i }).click();
      const created = (await createRequest).postDataJSON();
      expect(created).toMatchObject({
        name: profile.name,
        gender: "female",
        date_of_birth: "1990-04-12",
        address: "[REDACTED_ADDRESS], Kochi",
        pincode: 682001,
      });
      expect(created.geo_organization).toBeTruthy();

      await expectToast(page, "Patient Registered Successfully");
      await expectToast(page, "ABHA linked to the patient");
      const link = await waitForCall(mock, "POST", LINK_PATH);
      expect(link.body).toEqual({ transaction_id: "txn-verified" });
      await expect(page).toHaveURL(/\/patients\/home/);
    });
  });

  test("keeps the patient when the ABHA cannot be linked", async ({ page }) => {
    const profile = abhaProfile({
      name: faker.person.fullName(),
      mobile: `9${faker.string.numeric(9)}`,
    });
    mock
      .on("POST", "abdm/abha/otp/verify/", { json: verified(profile) })
      .on("POST", LINK_PATH, abdmError(400, "abdm_unavailable"));

    await verifyByMobile(page, profile.mobile);
    await page.getByTestId("abdm-use-for-registration").click();
    await openAdditionalDetails(page);
    await expect(
      page.getByText(
        "State and district matched from the ABHA address. Please confirm.",
      ),
    ).toBeVisible();
    await page.getByRole("button", { name: /register patient/i }).click();

    await expectToast(page, "Patient Registered Successfully");
    await expectToast(
      page,
      "The patient was registered, but the ABHA could not be linked. Link it from the patient's page.",
    );
    await expect(page).toHaveURL(/\/patients\/home/);
    expect(mock.calls("POST", LINK_PATH)).toHaveLength(1);
  });

  test("points to the patient who already has the ABHA", async ({ page }) => {
    const patientId = getPatientId();
    mock
      .on("POST", "abdm/abha/otp/verify/", {
        json: verified(abhaProfile(), {
          existing_patient: {
            id: patientId,
            name: "Asha Kumari",
            can_view: true,
          },
        }),
      })
      .on("GET", /^patient\/[^/]+\/abha\/$/, { json: { linked: false } });

    await verifyByMobile(page, "9000000001");

    await expect(page.getByTestId("abdm-existing-patient")).toContainText(
      "Asha Kumari",
    );
    await expect(page.getByTestId("abdm-use-for-registration")).toHaveCount(0);
    await expect(
      page.getByRole("button", { name: /register patient/i }),
    ).toBeHidden();

    await page.getByTestId("abdm-open-patient").click();
    await expect(page).toHaveURL(
      new RegExp(`/facility/${facilityId}/patient/${patientId}$`),
    );
    await expect(page.getByTestId("patient-abha-section")).toBeVisible();
  });
});

