}: {
  result: AbhaFlowResult;
  /** The patient record's mobile, offered as the new number. */
  patientMobile?: string;
  onUpdated?: (profile: AbhaProfile) => void;
  onDone: () => void;
}) {
  const { t } = useTranslation();
  const { config, restart } = useAbhaFlow();
  const currentMobile = result.profile.mobile;

  const [mobile, setMobile] = useState(() =>
    patientMobile && patientMobile !== currentMobile ? patientMobile : "",
  );
  const [showErrors, setShowErrors] = useState(false);
  const [otpSent, setOtpSent] = useState<AbhaOtpSent | null>(null);
  const [otp, setOtp] = useState("");
  const [updated, setUpdated] = useState<AbhaProfile | null>(null);

  const sendMutation = useMutation({
    mutationFn: mutate(abdmApi.profileMobileOtp, { silent: abdmSilent }),
    onSuccess: (data: AbhaOtpSent) => {
      setOtp("");
      setOtpSent(data);
    },
  });

  const verifyMutation = useMutation({
    mutationFn: mutate(abdmApi.profileMobileVerify, { silent: abdmSilent }),
    onSuccess: ({ profile }: { profile: AbhaProfile }) => {
      setUpdated(profile);
      onUpdated?.(profile);
    },
  });

  const mobileError = !isValidMobile(mobile)
    ? t("abdm_validation__mobile")
    : mobile === currentMobile
      ? t("abdm_update_mobile_same")
      : undefined;

  const handleSend = (event: SubmitEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (mobileError || sendMutation.isPending) return;
    sendMutation.mutate({ transaction_id: result.transactionId, mobile });
  };

  const handleVerify = (event: SubmitEvent) => {
    event.preventDefault();
    if (!otpSent || otp.length !== config.otp.length) return;
    if (verifyMutation.isPending) return;
    verifyMutation.mutate({ transaction_id: otpSent.transaction_id, otp });
  };

  if (updated) {
    return (
      <div className="flex flex-col gap-3" data-testid="abdm-update-mobile">
        <Alert
          className="border-green-200 bg-green-50"
          data-testid="abdm-update-mobile-success"
        >
          <CheckCircle2Icon className="text-green-700" />
          <AlertTitle className="line-clamp-none text-green-900">
            {t("abdm_update_mobile_success", {
              mobile: `+91 ${updated.mobile ?? mobile}`,
            })}
          </AlertTitle>
        </Alert>
        <div className="flex justify-end">
          <Button
            type="button"
            variant="primary"
            onClick={onDone}
            data-testid="abdm-update-mobile-done"
          >
            {t("done")}
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-4" data-testid="abdm-update-mobile">
      <p className="text-sm font-medium text-gray-900">
        {t("abdm_update_mobile_title")}
      </p>
      {otpSent ? (
        <form
          className="flex flex-col gap-4"
          onSubmit={handleVerify}
          noValidate
        >
          <AbhaOtpInput
            otpSent={otpSent}
            onOtpSentChange={setOtpSent}
            otpLength={config.otp.length}
            value={otp}
            onChange={(next) => {
              setOtp(next);
              if (verifyMutation.error) verifyMutation.reset();
            }}
            disabled={verifyMutation.isPending}
            onRestart={restart}
          />
          {verifyMutation.error && (
            <AbdmErrorAlert error={verifyMutation.error} onRestart={restart} />
          )}
          <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            <Button
              type="button"
              variant="outline"
              disabled={verifyMutation.isPending}
              onClick={() => {
                setOtpSent(null);
                verifyMutation.reset();
              }}
            >
              {t("abdm_change_mobile")}
            </Button>
            <Button
              type="submit"
              variant="primary"
              disabled={
                otp.length !== config.otp.length || verifyMutation.isPending
              }
              data-testid="abdm-update-mobile-verify"
            >
              {verifyMutation.isPending && (
                <Loader2Icon className="animate-spin" />
              )}
              {t("abdm_update_mobile_confirm")}
            </Button>
          </div>
        </form>
      ) : (
        <form className="flex flex-col gap-4" onSubmit={handleSend} noValidate>
          <AbdmField
            label={t("abdm_new_mobile")}
            prefix="+91"
            inputMode="numeric"
            maxLength={10}
            value={mobile}
            onChange={(event) => {
              setMobile(event.target.value.replace(/\D/g, ""));
              sendMutation.reset();
            }}
            provenance={
              patientMobile && mobile === patientMobile
                ? { provenance: "patient_record" }
                : undefined
            }
            hint={t("abdm_update_mobile_hint")}
            error={showErrors ? mobileError : undefined}
            data-testid="abdm-update-mobile-input"
          />
          {sendMutation.error && (
            <AbdmErrorAlert error={sendMutation.error} onRestart={restart} />
          )}
          <div className="flex justify-end">
            <Button
              type="submit"
              variant="primary"
              disabled={sendMutation.isPending}
              data-testid="abdm-update-mobile-send"
            >
              {sendMutation.isPending ? (
                <Loader2Icon className="animate-spin" />
              ) : (
                <SendIcon />
              )}
              {t("abdm_send_otp")}
            </Button>
          </div>
        </form>
      )}
    </div>
  );
}

