import { expect, test } from "@playwright/test";
import {
  AbdmMock,
  abhaProfile,
  mockAbdm,
  otpSent,
  TEST_PNG_BASE64,
  verified,
  waitForCall,
} from "tests/helper/abdm";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

const ABHA_NUMBER = "91-1111-2222-3333";

function linkedAbha() {
  return {
    linked: true,
    id: "abha-link-1",
    abha_number: ABHA_NUMBER,
    abha_address: "asha.kumari@sbx",
    abha_addresses: ["asha.kumari@sbx", "asha1990@sbx"],
    kyc_verified: true,
    profile: abhaProfile(),
    source: "verification",
    verification_method: "mobile_otp",
    linked_by: {
      id: "user-1",
      username: "care-admin",
      first_name: "Care",
      last_name: "Admin",
    },
    linked_at: "2026-01-15T09:30:00Z",
  };
}

test.describe("ABHA on the patient page", () => {
  let mock: AbdmMock;
  let facilityId: string;
  let patientId: string;
  let isLinked: boolean;

  test.beforeEach(async ({ page }) => {
    facilityId = getFacilityId();
    patientId = getPatientId();
    mock = await mockAbdm(page);
    isLinked = true;
    mock.on("GET", `patient/${patientId}/abha/`, () => ({
      json: isLinked ? linkedAbha() : { linked: false },
    }));
  });

  test.afterEach(() => {
    expect(mock.unhandled).toEqual([]);
  });

  test("shows the linked ABHA and unlinks it after confirmation", async ({
    page,
  }) => {
    mock.on("POST", `patient/${patientId}/abha/unlink/`, () => {
      isLinked = false;
      return { json: { linked: false } };
    });
    await page.goto(`/facility/${facilityId}/patient/${patientId}`);
    const section = page.getByTestId("patient-abha-section");

    await test.step("Show the link details", async () => {
      await expect(section).toHaveAttribute("data-linked", "true");
      await expect(page.getByTestId("patient-abha-number")).toHaveText(
        ABHA_NUMBER,
      );
      await expect(page.getByTestId("patient-abha-address")).toHaveText(
        "asha.kumari@sbx",
      );
      await expect(
        page.getByTestId("patient-abha-other-addresses"),
      ).toHaveText("asha1990@sbx");
      await expect(page.getByTestId("patient-abha-kyc")).toHaveText(
        "KYC verified",
      );
      await expect(page.getByTestId("patient-abha-source")).toHaveText(
        "ABHA verification · Mobile OTP",
      );
      await expect(page.getByTestId("patient-abha-linked-by")).toContainText(
        "Care Admin",
      );
    });

    await test.step("Ask before unlinking", async () => {
      await page.getByTestId("patient-abha-unlink").click();
      const dialog = page.getByRole("alertdialog");
      await expect(dialog).toContainText("Unlink ABHA?");
      await expect(dialog).toContainText(ABHA_NUMBER);
      await dialog.getByRole("button", { name: "Cancel" }).click();
      await expect(dialog).toBeHidden();
      expect(mock.calls("POST", `patient/${patientId}/abha/unlink/`)).toEqual(
        [],
      );
    });

    await test.step("Unlink the ABHA", async () => {
      await page.getByTestId("patient-abha-unlink").click();
      await page
        .getByRole("alertdialog")
        .getByRole("button", { name: "Unlink ABHA" })
        .click();
      await expectToast(page, "ABHA unlinked");
      await expect(section).toHaveAttribute("data-linked", "false");
      await expect(page.getByTestId("patient-abha-none")).toBeVisible();
      await expect(page.getByTestId("patient-abha-link")).toBeVisible();
    });
  });

  test("re-verifies the linked ABHA to show its card and QR code", async ({
    page,
  }) => {
    mock
      .on("POST", "abdm/abha/otp/request/", {
        json: otpSent({ otp_system: "aadhaar", masked_mobile: "******4321" }),
      })
      .on("POST", "abdm/abha/otp/verify/", {
        json: verified(abhaProfile(), { transaction_id: "txn-card" }),
      })
      .on("GET", "abdm/abha/qr/", {
        json: { content_type: "image/png", data: TEST_PNG_BASE64 },
      })
      .on("GET", "abdm/abha/card/", {
        json: { content_type: "image/png", data: TEST_PNG_BASE64 },
      });
    await page.goto(`/facility/${facilityId}/patient/${patientId}`);

    await test.step("Verify the linked ABHA number", async () => {
      await page.getByTestId("patient-abha-show-card").click();
      await expect(page.getByTestId("abdm-auth-method-identifier")).toHaveText(
        ABHA_NUMBER,
      );
      await page.getByTestId("abdm-otp-system-aadhaar").click();
      await page.getByTestId("abdm-auth-method-submit").click();
      expect(
        (await waitForCall(mock, "POST", "abdm/abha/otp/request/")).body,
      ).toEqual({
        identifier_type: "abha_number",
        value: ABHA_NUMBER,
        otp_system: "aadhaar",
        facility: facilityId,
      });
      await page.getByTestId("abdm-otp-input").fill("123456");
      await page.getByTestId("abdm-otp-submit").click();
      await expect(page.getByTestId("abha-profile-card")).toBeVisible();
    });

    await test.step("Show the QR code", async () => {
      await page.getByTestId("abha-show-qr").click();
      await expect(page.getByTestId("abha-qr-image")).toHaveAttribute(
        "src",
        /^data:image\/png;base64,/,
      );
      const qr = await waitForCall(mock, "GET", "abdm/abha/qr/");
      expect(qr.query.get("transaction_id")).toBe("txn-card");
      await page.keyboard.press("Escape");
      await expect(page.getByTestId("abha-qr-image")).toBeHidden();
    });

    await test.step("Download the ABHA card", async () => {
      const download = page.waitForEvent("download");
      await page.getByTestId("abha-download-card").click();
      expect((await download).suggestedFilename()).toBe(
        "abha-card-91111122223333.png",
      );
      const card = await waitForCall(mock, "GET", "abdm/abha/card/");
      expect(card.query.get("transaction_id")).toBe("txn-card");
    });
  });

  test("updates the ABHA mobile with a second OTP", async ({ page }) => {
    mock
      .on("POST", "abdm/abha/otp/request/", { json: otpSent() })
      .on("POST", "abdm/abha/otp/verify/", {
        json: verified(abhaProfile(), { transaction_id: "txn-verified" }),
      })
      .on("POST", "abdm/abha/profile/mobile/otp/", {
        json: otpSent({
          transaction_id: "txn-mobile",
          masked_mobile: "******0009",
        }),
      })
      .on("POST", "abdm/abha/profile/mobile/verify/", {
        json: { profile: abhaProfile({ mobile: "9000000009" }) },
      });
    await page.goto(`/facility/${facilityId}/patient/${patientId}`);

    await page.getByTestId("patient-abha-update-mobile").click();
    await page.getByTestId("abdm-auth-method-submit").click();
    await page.getByTestId("abdm-otp-input").fill("123456");
    await page.getByTestId("abdm-otp-submit").click();

    await test.step("Send an OTP to the new mobile", async () => {
      await page.getByTestId("abdm-update-mobile-input").fill("9000000009");
      await page.getByTestId("abdm-update-mobile-send").click();
      await expect(page.getByTestId("abdm-otp-sent")).toContainText(
        "******0009",
      );
      expect(
        mock.calls("POST", "abdm/abha/profile/mobile/otp/")[0].body,
      ).toEqual({ transaction_id: "txn-verified", mobile: "9000000009" });
    });

    await test.step("Confirm the new mobile", async () => {
      await page.getByTestId("abdm-otp-input").fill("654321");
      await page.getByTestId("abdm-update-mobile-verify").click();
      await expect(page.getByTestId("abdm-update-mobile-success")).toHaveText(
        "The ABHA's mobile number is now +91 9000000009",
      );
      expect(
        mock.calls("POST", "abdm/abha/profile/mobile/verify/")[0].body,
      ).toEqual({ transaction_id: "txn-mobile", otp: "654321" });
    });
  });

  test("links an ABHA after showing how it differs from the record", async ({
    page,
  }) => {
    isLinked = false;
    mock
      .on("POST", "abdm/abha/otp/request/", { json: otpSent() })
      .on("POST", "abdm/abha/otp/verify/", {
        json: verified(abhaProfile({ name: "Someone Else Entirely" })),
      })
      .on("POST", `patient/${patientId}/abha/link/`, () => {
        isLinked = true;
