      await expect(dialog).toContainText("Unlink ABHA?");
      await expect(dialog).toContainText(ABHA_NUMBER);
      await dialog.getByRole("button", { name: "Cancel" }).click();
      await expect(dialog).toBeHidden();
      expect(mock.calls("POST", `patient/${patientId}/abha/unlink/`)).toEqual(
        [],
      );
    });

