import { expect, test } from "@playwright/test";
import {
  AbdmMock,
  abhaProfile,
  AbdmRequest,
  mockAbdm,
  waitForCall,
} from "tests/helper/abdm";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

test.describe("ABHA shares queue", () => {
  let mock: AbdmMock;
  let facilityId: string;
  let patientId: string;

  test.beforeEach(async ({ page }) => {
    facilityId = getFacilityId();
    patientId = getPatientId();
    const shares = [
      {
        id: "share-waiting",
        token_number: 12,
        counter_code: "OPD1",
        abha_number: "91-1111-2222-3333",
        abha_address: "asha.kumari@sbx",
        profile: abhaProfile(),
        status: "pending",
        patient: null,
        created_date: new Date().toISOString(),
        expires_at: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
      },
      {
        id: "share-linked",
        token_number: 11,
        counter_code: "OPD1",
        abha_number: "91-4444-5555-6666",
        abha_address: "ravi.kumar@sbx",
        profile: abhaProfile({
          name: "Ravi Kumar",
          abha_number: "91-4444-5555-6666",
          abha_address: "ravi.kumar@sbx",
          gender: "male",
        }),
        status: "linked",
        patient: { id: patientId, name: "Ravi Kumar" },
        created_date: new Date().toISOString(),
        expires_at: null,
      },
    ];
    mock = await mockAbdm(page);
    mock
      .on("GET", `facility/${facilityId}/abdm/`, {
        json: {
          configured: true,
          hip_id: "IN3210000001",
          hip_name: "M1 Test Hospital",
          counters: [{ code: "OPD1", name: "Outpatient desk" }],
          share_urls: [],
        },
      })
      .on("GET", `facility/${facilityId}/abdm/shares/`, (request) => {
        const status = request.query.get("status");
        const results = shares.filter(
          (share) => !status || share.status === status,
        );
        return {
          json: { count: results.length, next: null, previous: null, results },
        };
      });
  });

  test.afterEach(() => {
    expect(mock.unhandled).toEqual([]);
  });

  test("lists today's shares and opens registration from one", async ({
    page,
  }) => {
    await page.goto(`/facility/${facilityId}/abha_shares`);
    const rows = page
      .getByTestId("abdm-shares-table")
      .getByTestId("abdm-share-row");

    await test.step("List the shares with their token and status", async () => {
      await expect(rows).toHaveCount(2);
      const waiting = rows.filter({ hasText: "Asha Kumari" });
      await expect(waiting.getByTestId("abdm-share-token")).toHaveText("12");
      await expect(waiting).toContainText("Counter: Outpatient desk");
      await expect(waiting).toContainText("91-1111-2222-3333");
      await expect(waiting.getByTestId("abdm-share-status")).toHaveText(
        "Waiting",
      );
      await expect(waiting.getByTestId("abdm-share-register")).toBeVisible();
    });

    await test.step("Open the patient of a linked share", async () => {
      const linked = rows.filter({ hasText: "Ravi Kumar" });
      await expect(linked.getByTestId("abdm-share-status")).toHaveText(
        "Linked",
      );
      await expect(linked.getByTestId("abdm-share-register")).toHaveCount(0);
      await expect(
        linked.getByTestId("abdm-share-open-patient"),
      ).toHaveAttribute("href", `/facility/${facilityId}/patient/${patientId}`);
    });

    await test.step("Filter by status", async () => {
      await page.getByTestId("abdm-shares-status-pending").click();
      await expect(rows).toHaveCount(1);
      const isPendingFilter = (call: AbdmRequest) =>
        call.query.get("status") === "pending";
      expect(
        mock
          .calls("GET", `facility/${facilityId}/abdm/shares/`)
          .some(isPendingFilter),
      ).toBe(true);
    });

    await test.step("Register the patient from the share", async () => {
      await rows.getByTestId("abdm-share-register").click();
      await expect(page).toHaveURL(
        new RegExp(
          `/facility/${facilityId}/patient/create\\?profile_share=share-waiting$`,
        ),
      );
      await expect(page.getByTestId("abdm-profile-share")).toContainText(
        "Shared at the counter, token 12",
      );
      await expect(page.getByTestId("abha-profile-name")).toHaveText(
        "Asha Kumari",
      );
      await expect(page.getByTestId("abdm-use-for-registration")).toBeVisible();
      const lookup = await waitForCall(
        mock,
        "GET",
        `facility/${facilityId}/abdm/shares/`,
        3,
      );
      expect(lookup.query.get("limit")).toBe("100");
    });
  });
});

