import { useQuery } from "@tanstack/react-query";
import { IdCardIcon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { EmptyState } from "@/components/ui/empty-state";

import Page from "@/components/Common/Page";
import { FormSkeleton } from "@/components/Common/SkeletonLoading";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { abdmSilent } from "@/components/Abdm/utils";

import { useAbdmConfig } from "@/hooks/useAbdmConfig";

import query from "@/Utils/request/query";
import { getPermissions } from "@/common/Permissions";
import { usePermissions } from "@/context/PermissionContext";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import abdmApi from "@/types/abdm/abdmApi";

import { FacilityAbdmConfigForm } from "./FacilityAbdmConfigForm";

/**
 * Facility settings for ABDM: the facility's HIP details, its registration
 * counters, and the "scan and share" QR code printed at each counter.
 */
export default function AbdmSettings({ facilityId }: { facilityId: string }) {
  const { t } = useTranslation();
  const { config: abdmConfig, isLoading: isAbdmConfigLoading } =
    useAbdmConfig();
  const { facility, isFacilityLoading } = useCurrentFacility();
  const { hasPermission } = usePermissions();
  const { canUpdateFacility } = getPermissions(
    hasPermission,
    facility?.root_org_permissions ?? [],
  );

  const { data, isLoading, error } = useQuery({
    queryKey: ["abdm", "facility", facilityId],
    queryFn: query(abdmApi.getFacilityConfig, {
      pathParams: { facilityId },
      silent: abdmSilent,
    }),
    enabled: !!abdmConfig,
    retry: false,
  });

  return (
    <Page title={t("abdm_facility_settings_title")} hideTitleOnPage>
      <div className="container mx-auto flex max-w-4xl flex-col gap-6">
        <div className="flex flex-col gap-1">
          <h1 className="text-2xl font-bold text-gray-700">
            {t("abdm_facility_settings_title")}
          </h1>
          <p className="text-sm text-gray-600">
            {t("abdm_facility_settings_description")}
          </p>
        </div>

        {isAbdmConfigLoading ||
        isFacilityLoading ||
        (abdmConfig && isLoading) ? (
          <FormSkeleton rows={4} />
        ) : !abdmConfig ? (
          <EmptyState
            icon={<IdCardIcon className="size-6 text-primary" />}
            title={t("abdm_not_enabled_title")}
            description={t("abdm_not_enabled_description")}
          />
        ) : error || !data ? (
          <AbdmErrorAlert error={error} />
        ) : (
          <FacilityAbdmConfigForm
            facilityId={facilityId}
            config={data}
            facilityName={facility?.name}
            canEdit={canUpdateFacility}
          />
        )}
      </div>
    </Page>
  );
}

