import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";

import { callApi } from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";
import { AbdmConfig } from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

const DEFAULT_OTP_POLICY: AbdmConfig["otp"] = {
  length: 6,
  resend_wait_seconds: 60,
  max_resends: 2,
};

/**
 * Reads the deployment's ABDM configuration.
 *
 * Everything ABHA-related in the UI is gated on `enabled`. When the backend
 * has ABDM turned off, does not know the endpoint, or cannot be reached, the
 * hook reports `enabled: false` and CARE behaves exactly as it did before.
 */
export function useAbdmConfig() {
  const { data, isLoading } = useQuery({
    queryKey: ["abdm", "config"],
    queryFn: async ({ signal }) => {
      try {
        return await callApi(abdmApi.getConfig, { signal, silent: true });
      } catch (error) {
        // A backend without ABDM has no such endpoint. That is an answer
        // ("disabled"), so it is cached instead of being asked again.
        if (error instanceof HTTPError && error.status === 404) {
          return null;
        }
        throw error;
      }
    },
    staleTime: 5 * 60 * 1000,
    retry: false,
  });

  const config = useMemo<AbdmConfig | undefined>(
    () =>
      data?.enabled
        ? { ...data, otp: { ...DEFAULT_OTP_POLICY, ...data.otp } }
        : undefined,
    [data],
  );

  return { config, enabled: !!config, isLoading };
}
