// Live no-OTP smoke checks against the real backend on :9100 (via the dev server on :4100).
// Fences: every ABDM / patient-ABHA call is aborted unless explicitly allowed below.
// - otp/request is allowed ONLY for the random (non-existent) ABHA address.
// - find/ (search by mobile; sends no OTP) is allowed ONLY for FIND_MOBILES.
// - Nothing that can send an OTP or create/link anything is allowed.
const WT = "/Users/jacob/copilot-worktrees/care_fe/jacobjeevan-expert-doodle";
const { chromium, expect } = require(WT + "/node_modules/@playwright/test");
const SHOTS = __dirname + "/shots";
const BASE = "http://localhost:4100";
const FAC = "d53f2a67-894b-450d-a633-de9ba1e9c9b9";
