const log = (ok, name, detail = "") => {
  results.push({ ok, name, detail });
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? " — " + detail : ""}`);
};
async function check(name, fn) {
  try {
    const detail = await fn();
    log(true, name, detail || "");
  } catch (e) {
    log(false, name, (e.message || String(e)).split("\n").slice(0, 4).join(" | "));
  }
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });
  const blocked = [];
  const allowed = [];
  const pageErrors = [];
  page.on("pageerror", (e) => pageErrors.push(e.message));

  await page.route(/\/api\/v1\/(abdm\/|patient\/[^/]+\/abha\/|facility\/[^/]+\/abdm\/)/, async (route) => {
    const req = route.request();
    const url = new URL(req.url());
    const path = url.pathname.replace(/^\/api\/v1\//, "");
    const method = req.method();
    let body = null;
    try { body = req.postDataJSON(); } catch { body = null; }
    const ok =
      (method === "GET" && path === "abdm/config/") ||
      (method === "GET" && /^patient\/[^/]+\/abha\/$/.test(path)) ||
      (method === "GET" && /^facility\/[^/]+\/abdm\/(shares\/)?$/.test(path)) ||
      (method === "POST" && path === "abdm/abha/otp/request/" &&
        body && body.identifier_type === "abha_address" && body.value === RANDOM_ADDR) ||
      (method === "POST" && path === "abdm/abha/find/" && body && FIND_MOBILES.includes(body.mobile));
    if (!ok) {
      blocked.push(`${method} ${path} ${body ? JSON.stringify(body) : ""}`);
      return route.abort();
    }
    const response = await route.fetch();
    let json = null;
    try { json = await response.json(); } catch { json = null; }
    allowed.push({ method, path, status: response.status(), json });
    return route.fulfill({ response });
  });

  const lastCall = (method, path) => [...allowed].reverse().find((c) => c.method === method && c.path === path);

  await check("login as admin", async () => {
