(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });
  const blocked = [];
  const allowed = [];
  const pageErrors = [];
  page.on("pageerror", (e) => pageErrors.push(e.message));

  await page.route(/\/api\/v1\/(abdm\/|patient\/[^/]+\/abha\/|facility\/[^/]+\/abdm\/)/, async (route) => {
    const req = route.request();
    const url = new URL(req.url());
    const path = url.pathname.replace(/^\/api\/v1\//, "");
    const method = req.method();
    let body = null;
    try { body = req.postDataJSON(); } catch { body = null; }
    const ok =
      (method === "GET" && path === "abdm/config/") ||
      (method === "GET" && /^patient\/[^/]+\/abha\/$/.test(path)) ||
      (method === "GET" && /^facility\/[^/]+\/abdm\/(shares\/)?$/.test(path)) ||
      (method === "POST" && path === "abdm/abha/otp/request/" &&
        body && body.identifier_type === "abha_address" && body.value === RANDOM_ADDR) ||
      (method === "POST" && path === "abdm/abha/find/" && body && FIND_MOBILES.includes(body.mobile));
    if (!ok) {
      blocked.push(`${method} ${path} ${body ? JSON.stringify(body) : ""}`);
      return route.abort();
    }
    const response = await route.fetch();
    let json = null;
    try { json = await response.json(); } catch { json = null; }
    allowed.push({ method, path, status: response.status(), json });
    return route.fulfill({ response });
  });

  const lastCall = (method, path) => [...allowed].reverse().find((c) => c.method === method && c.path === path);

  await check("login as admin", async () => {
    await page.goto(`${BASE}/login`);
    await page.getByRole("textbox", { name: /username/i }).fill("admin");
    await page.getByLabel(/password/i).fill("admin");
    await page.getByRole("button", { name: /login/i }).click();
    await page.waitForURL((u) => !u.pathname.includes("login"), { timeout: 20000 });
  });

  let config;
  await check("ABDM config loads and is enabled", async () => {
    await page.goto(`${BASE}/facility/${FAC}/patient/create`);
    await expect(page.getByTestId("abdm-registration-step")).toBeVisible({ timeout: 20000 });
    await expect(page.getByTestId("abdm-step-identifier")).toBeVisible();
    config = lastCall("GET", "abdm/config/");
    if (!config || config.status !== 200 || !config.json.enabled) throw new Error(JSON.stringify(config));
    await page.screenshot({ path: SHOTS + "/live-1-registration-step.png" });
    return `status 200, enabled, consent v${config.json.consent?.version}, suffix ${config.json.abha_address_suffix ?? config.json.cm_id}`;
  });

  await check("unknown ABHA address → not-found → create path", async () => {
    await page.getByTestId("abdm-identifier-abha_address").click();
    await page.getByTestId("abdm-abha-address-input").fill(RANDOM_ADDR);
    await page.getByTestId("abdm-identifier-submit").click();
    await expect(page.getByTestId("abdm-auth-method-identifier")).toHaveText(RANDOM_ADDR);
    const mobileOtp = page.getByTestId("abdm-otp-system-abdm");
    if (await mobileOtp.count()) await mobileOtp.click();
    await page.getByTestId("abdm-auth-method-submit").click();
    await expect(page.getByTestId("abdm-step-not-found")).toBeVisible({ timeout: 30000 });
    await expect(page.getByTestId("abdm-not-found-value")).toHaveText(RANDOM_ADDR);
    await page.screenshot({ path: SHOTS + "/live-2-not-found.png" });
    const call = lastCall("POST", "abdm/abha/otp/request/");
    return `otp/request → ${call?.status} ${call?.json?.errors?.[0]?.type} (${call?.json?.errors?.[0]?.abdm_code ?? "-"})`;
  });

  await check("create path shows verbatim consent and gates the Aadhaar submit", async () => {
    await page.getByTestId("abdm-not-found-create").click();
    await expect(page.getByTestId("abdm-step-create-aadhaar")).toBeVisible();
    await expect(page.getByTestId("abdm-consent-text")).toHaveText(config.json.consent.text);
    await page.getByTestId("abdm-aadhaar-input").fill(UNISSUABLE_AADHAAR);
    const submit = page.getByTestId("abdm-create-aadhaar-submit");
    await expect(submit).toBeDisabled();
    await page.getByTestId("abdm-consent-checkbox").click();
    await expect(submit).toBeEnabled();
    await page.screenshot({ path: SHOTS + "/live-3-consent-agreed.png" });
    await page.getByTestId("abdm-consent-checkbox").click();
    await expect(submit).toBeDisabled();
    return "submit disabled → enabled on 'I agree' → disabled again (never clicked)";
  });

  await check("find ABHA by mobile renders the masked list (no OTP)", async () => {
    await page.goto(`${BASE}/facility/${FAC}/patient/create`);
    await expect(page.getByTestId("abdm-step-identifier")).toBeVisible({ timeout: 20000 });
    await page.getByTestId("abdm-find-by-mobile").click();
    const outcomes = [];
    for (const mobile of FIND_MOBILES) {
      await page.getByTestId("abdm-find-mobile-input").fill(mobile);
      await page.getByTestId("abdm-find-submit").click();
      const accounts = page.getByTestId("abdm-find-account");
      const error = page.getByTestId("abdm-error");
      const notFound = page.getByTestId("abdm-step-not-found");
      await expect(accounts.first().or(error).or(notFound)).toBeVisible({ timeout: 30000 });
      const call = lastCall("POST", "abdm/abha/find/");
      const n = await accounts.count();
      outcomes.push(`${mobile.slice(0, 2)}******${mobile.slice(-2)}: find → ${call?.status} ${n ? `${n} account(s)` : call?.json?.errors?.[0]?.type}`);
      await page.screenshot({ path: SHOTS + `/live-4-find-${mobile.slice(-4)}.png` });
      if (n) {
        const first = await accounts.first().innerText();
        outcomes.push(`first entry: ${first.replace(/\s+/g, " ").slice(0, 80)}`);
        break;
      }
    }
    return outcomes.join("; ");
  });

