    return `GET patient abha → ${call?.status} linked=${call?.json?.linked}; link button: ${await page.getByTestId("patient-abha-link").count()}`;
  });

  await check("seeded facility ABDM settings render (read-only)", async () => {
    await page.goto(`${BASE}/facility/${SEEDED_FAC}/settings/abdm`);
    await expect(page.getByTestId("abdm-facility-form")).toBeVisible({ timeout: 20000 });
