import {
  AbhaCreateVerified,
  AbhaExistingPatient,
  AbhaIdentifierType,
  AbhaOtpSent,
  AbhaProfile,
  AbhaVerified,
} from "@/types/abdm/abdm";

/** Where a reused value came from; shown next to every prefilled field. */
export type FactProvenance = "entered" | "patient_record" | "abha";

export type FactKey = "aadhaar" | "mobile" | "abha_number" | "abha_address";

export interface Fact {
  value: string;
  provenance: FactProvenance;
}

/**
 * Values collected once in a flow and reused by later steps and fallback
 * paths ("never ask twice"). The Aadhaar fact is only recorded together with
 * the patient's consent, so its presence means consent was given.
 */
export type AbhaFacts = Partial<Record<FactKey, Fact>>;

export type RememberFact = (
  key: FactKey,
  value: string,
  provenance?: FactProvenance,
) => void;

export interface AbhaFlowResult {
  /** A verified (or enrolled) server-side transaction, usable for linking. */
  transactionId: string;
  profile: AbhaProfile;
  existingPatient: AbhaExistingPatient | null;
  /** Set when the ABHA came from the Aadhaar enrolment endpoints. */
  isNew?: boolean;
}

export type AbhaVerifyIdentifierType = "abha_number" | "abha_address";

/** Shown above a step when the flow took a turn the user should know about. */
export type AbhaFlowNotice = "abha_exists";

/**
 * The steps of the identify flow. Only the active step is rendered, so a
 * hidden step can never sit in the tab order.
 */
export type AbhaFlowStep =
  | { name: "identifier"; identifierType?: AbhaIdentifierType }
  | {
      name: "auth_method";
      identifierType: AbhaVerifyIdentifierType;
      value: string;
    }
  | { name: "find" }
  | {
      name: "otp";
      otpSent: AbhaOtpSent;
      identifierType: AbhaIdentifierType;
      value: string;
      notice?: AbhaFlowNotice;
      /** Where "back" leads, when not the identifier's own step. */
      backTo?: "find" | "create_aadhaar";
    }
  | { name: "select_account"; verified: AbhaVerified }
  | { name: "not_found"; identifierType: AbhaIdentifierType; value: string }
  | { name: "create_aadhaar" }
  | { name: "create_otp"; otpSent: AbhaOtpSent }
  | {
      name: "create_mobile";
      created: AbhaCreateVerified;
      mobile: string;
      otpSent: AbhaOtpSent | null;
      sendError?: unknown;
    }
  | {
      /** Mandatory whenever ABDM reports `abha_address_required`. */
