import { CheckCircle2Icon, RotateCcwIcon } from "lucide-react";
import { ReactNode, useCallback, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { AbhaFlowContext } from "@/components/Abdm/AbhaFlowContext";
import { AbhaProfileCard } from "@/components/Abdm/AbhaProfileCard";
import { AccountChooserStep } from "@/components/Abdm/steps/AccountChooserStep";
import { AddressStep } from "@/components/Abdm/steps/AddressStep";
import { AuthMethodStep } from "@/components/Abdm/steps/AuthMethodStep";
import { CreateAadhaarStep } from "@/components/Abdm/steps/CreateAadhaarStep";
import { CreateMobileStep } from "@/components/Abdm/steps/CreateMobileStep";
import { CreateOtpStep } from "@/components/Abdm/steps/CreateOtpStep";
import { FindStep } from "@/components/Abdm/steps/FindStep";
import { IdentifierStep } from "@/components/Abdm/steps/IdentifierStep";
import { NotFoundStep } from "@/components/Abdm/steps/NotFoundStep";
import { OtpStep } from "@/components/Abdm/steps/OtpStep";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import {
  AbhaFacts,
  AbhaFlowNotice,
  AbhaFlowResult,
  AbhaFlowStep,
  AbhaVerifyIdentifierType,
  FactKey,
  FactProvenance,
} from "@/components/Abdm/types";

import { AbdmConfig, AbhaIdentifierType } from "@/types/abdm/abdm";

export interface AbhaIdentifyFlowProps {
  config: AbdmConfig;
  facilityId?: string;
  /** Facts known before the flow starts, e.g. the patient's mobile. */
  initialFacts?: AbhaFacts;
  /**
   * Verifies a known ABHA instead of asking for an identifier: the flow
   * starts at the OTP-method step with this identifier locked.
   */
  verifyIdentifier?: { type: AbhaVerifyIdentifierType; value: string };
  /** Offer ABHA creation when nothing is found (default true). */
  allowCreate?: boolean;
  /** Called to discard the flow; the host remounts it with a new key. */
  onRestart: () => void;
  /** The placement's primary action under the verified profile. */
  renderResultAction?: (result: AbhaFlowResult) => ReactNode;
  exitLabel?: string;
  onExit?: () => void;
}

/**
 * The reusable "identify an ABHA" journey: verify an existing ABHA by any
 * identifier, find a forgotten one by mobile, or create one with Aadhaar
 * when (and only when) ABDM reports that none exists.
 */
export function AbhaIdentifyFlow({
  config,
  facilityId,
  initialFacts,
  verifyIdentifier,
  allowCreate = true,
  onRestart,
  renderResultAction,
  exitLabel,
  onExit,
}: AbhaIdentifyFlowProps) {
  const { t } = useTranslation();
  const [facts, setFacts] = useState<AbhaFacts>(() => ({ ...initialFacts }));
  const [step, setStep] = useState<AbhaFlowStep>(() =>
    verifyIdentifier
      ? {
          name: "auth_method",
          identifierType: verifyIdentifier.type,
          value: verifyIdentifier.value,
        }
      : { name: "identifier" },
  );

  // Facts are write-once: a system-sourced value never replaces one already
  // held, while an explicit user entry always wins.
  const rememberFact = useCallback(
    (key: FactKey, value: string, provenance: FactProvenance = "entered") => {
      setFacts((current) => {
        const existing = current[key];
        if (existing?.value === value) return current;
        if (existing && provenance !== "entered") return current;
        return { ...current, [key]: { value, provenance } };
      });
    },
    [],
  );

  const finish = useCallback(
    (result: AbhaFlowResult, notice?: AbhaFlowNotice) =>
      setStep({ name: "result", result, notice }),
    [],
  );

  // Where the user corrects an identifier; its value comes back from the
  // fact store.
  const correctionStep = (identifierType: AbhaIdentifierType): AbhaFlowStep =>
    verifyIdentifier
      ? {
          name: "auth_method",
          identifierType: verifyIdentifier.type,
          value: verifyIdentifier.value,
        }
      : { name: "identifier", identifierType };

  const renderStep = () => {
    switch (step.name) {
      case "identifier":
        return <IdentifierStep initialType={step.identifierType} />;
      case "auth_method":
        return (
          <AuthMethodStep
            identifierType={step.identifierType}
            value={step.value}
            canGoBack={!verifyIdentifier}
          />
        );
      case "find":
        return <FindStep />;
      case "otp":
        return (
          <OtpStep
            key={step.otpSent.transaction_id}
            otpSent={step.otpSent}
            identifierType={step.identifierType}
            value={step.value}
            notice={step.notice}
            onBack={() => {
              if (step.backTo === "find") {
                setStep({ name: "find" });
              } else if (step.backTo === "create_aadhaar") {
                setStep({ name: "create_aadhaar" });
              } else if (
                step.identifierType === "abha_number" ||
                step.identifierType === "abha_address"
              ) {
                setStep({
                  name: "auth_method",
                  identifierType: step.identifierType,
                  value: step.value,
                });
              } else {
                setStep({
                  name: "identifier",
                  identifierType: step.identifierType,
                });
              }
            }}
          />
        );
      case "select_account":
        return (
          <AccountChooserStep
            verified={step.verified}
            onBack={() => setStep({ name: "identifier" })}
          />
        );
      case "not_found":
        return (
          <NotFoundStep
            identifierType={step.identifierType}
            value={step.value}
            onCheck={() => setStep(correctionStep(step.identifierType))}
          />
        );
      case "create_aadhaar":
        return (
          <CreateAadhaarStep onBack={() => setStep({ name: "identifier" })} />
        );
      case "create_otp":
        return (
          <CreateOtpStep
            key={step.otpSent.transaction_id}
            otpSent={step.otpSent}
            onBack={() => setStep({ name: "create_aadhaar" })}
          />
        );
      case "create_mobile":
        return (
          <CreateMobileStep
            created={step.created}
            mobile={step.mobile}
            otpSent={step.otpSent}
            sendError={step.sendError}
          />
        );
      case "address":
        return (
          <AddressStep
            transactionId={step.transactionId}
            existingPatient={step.existingPatient}
            isNew={step.isNew}
            notice={step.notice}
          />
        );
      case "result":
        return (
          <StepLayout
            title={
              step.result.isNew
                ? t("abdm_result_title_created")
                : t("abdm_result_title_verified")
            }
            testId="abdm-step-result"
          >
            {step.notice === "abha_exists" && (
              <Alert className="border-primary-200 bg-primary-50">
                <AlertDescription className="text-gray-800">
                  {t("abdm_notice__abha_exists")}
                </AlertDescription>
              </Alert>
            )}
            {step.result.isNew && (
              <Alert className="border-green-200 bg-green-50">
                <CheckCircle2Icon className="text-green-700" />
                <AlertTitle className="line-clamp-none text-green-900">
                  {t("abdm_abha_created")}
                </AlertTitle>
              </Alert>
            )}
            <AbhaProfileCard
              profile={step.result.profile}
              transactionId={step.result.transactionId}
            >
              {renderResultAction?.(step.result)}
            </AbhaProfileCard>
          </StepLayout>
        );
    }
  };

  const isInitialStep =
    step.name === "identifier" ||
    (!!verifyIdentifier && step.name === "auth_method");

  return (
    <AbhaFlowContext.Provider
      value={{
        config,
        facilityId,
        facts,
        rememberFact,
        allowCreate,
        consent: { agreed: true, version: config.consent.version },
        goTo: setStep,
        finish,
        restart: onRestart,
      }}
    >
      <div className="flex flex-col gap-4" data-testid="abdm-flow">
        {renderStep()}
        {(onExit || !isInitialStep) && (
          <div className="flex flex-wrap items-center justify-between gap-2 border-t border-gray-200 pt-3">
            {!isInitialStep ? (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={onRestart}
                data-testid="abdm-start-again"
              >
                <RotateCcwIcon />
                {t("abdm_start_again")}
              </Button>
            ) : (
              <span />
            )}
            {onExit && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={onExit}
                data-testid="abdm-exit"
              >
                {exitLabel ?? t("abdm_not_now")}
              </Button>
            )}
          </div>
        )}
      </div>
    </AbhaFlowContext.Provider>
  );
}

