import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";
import {
  AbdmConfig,
  AbhaCreateOtpRequest,
  AbhaCreateVerified,
  AbhaFile,
  AbhaFindResponse,
  AbhaOtpRequest,
  AbhaOtpSent,
  AbhaOtpSystem,
  AbhaProfile,
  AbhaProfileShare,
  AbhaProfileShareStatus,
  AbhaTransactionProfile,
  AbhaVerified,
  FacilityAbdmConfig,
  FacilityAbdmConfigUpdate,
  PatientAbha,
  PatientAbhaLinked,
  PatientAbhaLinkRequest,
} from "./abdm";

export default {
  // Configuration
  getConfig: {
    path: "/api/v1/abdm/config/",
    method: HttpMethod.GET,
    TRes: Type<AbdmConfig>(),
  },

  // Identify (login / verify an existing ABHA)
  requestOtp: {
    path: "/api/v1/abdm/abha/otp/request/",
    method: HttpMethod.POST,
    TBody: Type<AbhaOtpRequest>(),
    TRes: Type<AbhaOtpSent>(),
  },
  resendOtp: {
    path: "/api/v1/abdm/abha/otp/resend/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string }>(),
    TRes: Type<AbhaOtpSent>(),
  },
  verifyOtp: {
    path: "/api/v1/abdm/abha/otp/verify/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; otp: string }>(),
    TRes: Type<AbhaVerified>(),
  },
  selectAccount: {
    path: "/api/v1/abdm/abha/select-account/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; abha_number: string }>(),
    TRes: Type<AbhaVerified>(),
  },

  // Find a forgotten ABHA by mobile (returns a masked list, sends no OTP)
  find: {
    path: "/api/v1/abdm/abha/find/",
    method: HttpMethod.POST,
    TBody: Type<{ mobile: string }>(),
    TRes: Type<AbhaFindResponse>(),
  },
  findOtp: {
    path: "/api/v1/abdm/abha/find/otp/",
    method: HttpMethod.POST,
    TBody: Type<{
      transaction_id: string;
      index: number | string;
      otp_system: AbhaOtpSystem;
    }>(),
    TRes: Type<AbhaOtpSent>(),
  },

  // Create (Aadhaar only)
  createOtp: {
    path: "/api/v1/abdm/abha/create/otp/",
    method: HttpMethod.POST,
    TBody: Type<AbhaCreateOtpRequest>(),
    TRes: Type<AbhaOtpSent>(),
  },
  createVerify: {
    path: "/api/v1/abdm/abha/create/verify/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; otp: string; mobile: string }>(),
    TRes: Type<AbhaCreateVerified>(),
  },
  createMobileOtp: {
    path: "/api/v1/abdm/abha/create/mobile/otp/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; mobile: string }>(),
    TRes: Type<AbhaOtpSent>(),
  },
  createMobileVerify: {
    path: "/api/v1/abdm/abha/create/mobile/verify/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; otp: string }>(),
    TRes: Type<AbhaTransactionProfile>(),
  },
  addressSuggestions: {
    path: "/api/v1/abdm/abha/create/address-suggestions/",
    method: HttpMethod.GET,
    TRes: Type<{ suggestions: string[] }>(),
    TQuery: Type<{ transaction_id: string }>(),
  },
  createAddress: {
    path: "/api/v1/abdm/abha/create/address/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; abha_address: string }>(),
    TRes: Type<AbhaTransactionProfile>(),
  },

  // Verified-session operations
  getProfile: {
    path: "/api/v1/abdm/abha/profile/",
    method: HttpMethod.GET,
    TRes: Type<{ profile: AbhaProfile }>(),
    TQuery: Type<{ transaction_id: string }>(),
  },
  getCard: {
    path: "/api/v1/abdm/abha/card/",
    method: HttpMethod.GET,
    TRes: Type<AbhaFile>(),
    TQuery: Type<{ transaction_id: string }>(),
  },
  getQr: {
    path: "/api/v1/abdm/abha/qr/",
    method: HttpMethod.GET,
    TRes: Type<AbhaFile>(),
    TQuery: Type<{ transaction_id: string }>(),
  },
  profileMobileOtp: {
    path: "/api/v1/abdm/abha/profile/mobile/otp/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; mobile: string }>(),
    TRes: Type<AbhaOtpSent>(),
  },
  profileMobileVerify: {
    path: "/api/v1/abdm/abha/profile/mobile/verify/",
    method: HttpMethod.POST,
    TBody: Type<{ transaction_id: string; otp: string }>(),
    TRes: Type<{ profile: AbhaProfile }>(),
  },

  // Patient ABHA link
  getPatientAbha: {
    path: "/api/v1/patient/{patientId}/abha/",
