import { ArrowLeftIcon } from "lucide-react";
import { ReactNode, useEffect, useId, useRef } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";

interface StepLayoutProps {
  title: string;
  description?: ReactNode;
  onBack?: () => void;
  children: ReactNode;
  /** The step's actions; the primary action goes last. */
  footer?: ReactNode;
  className?: string;
  testId?: string;
}

/**
 * Common frame for a step of the ABHA flow. When a step opens and nothing in
 * it has taken focus (e.g. an autofocused input), focus moves to its heading
 * so screen reader and keyboard users land on the new step.
 */
export function StepLayout({
  title,
  description,
  onBack,
  children,
  footer,
  className,
  testId,
}: StepLayoutProps) {
  const { t } = useTranslation();
  const headingId = useId();
  const sectionRef = useRef<HTMLElement>(null);
  const headingRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    if (!sectionRef.current?.contains(document.activeElement)) {
      headingRef.current?.focus({ preventScroll: true });
    }
  }, []);

  return (
    <section
      ref={sectionRef}
      aria-labelledby={headingId}
      className={cn("flex flex-col gap-4", className)}
      data-testid={testId}
    >
      <div className="flex items-start gap-2">
        {onBack && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="-ml-2 size-8 shrink-0"
            onClick={onBack}
            aria-label={t("back")}
            data-testid="abdm-step-back"
          >
            <ArrowLeftIcon />
          </Button>
        )}
        <div className="flex min-w-0 flex-col gap-1">
          <h3
            id={headingId}
            ref={headingRef}
            tabIndex={-1}
            className="text-base font-semibold text-gray-900 outline-none"
          >
            {title}
          </h3>
          {description && (
            <div className="text-sm text-gray-600">{description}</div>
          )}
        </div>
      </div>
      {children}
      {footer && (
        <div className="flex flex-col-reverse gap-2 sm:flex-row sm:flex-wrap sm:justify-end">
          {footer}
        </div>
      )}
    </section>
  );
}

