import { ComponentProps, ReactNode, useId } from "react";

import { cn } from "@/lib/utils";

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { ProvenanceHint } from "@/components/Abdm/ProvenanceHint";
import { FactKey, FactProvenance } from "@/components/Abdm/types";

interface AbdmFieldProps extends Omit<ComponentProps<"input">, "prefix"> {
  label: string;
  error?: string;
  hint?: ReactNode;
  /** Shown beside the label while the value is a reused fact. */
  provenance?: { provenance: FactProvenance; field?: FactKey };
  /** Fixed text shown before the input, e.g. "+91". */
  prefix?: string;
  /** Fixed text shown after the input, e.g. "@sbx". */
  suffix?: string;
}

/** A labelled text input used by the ABHA flow steps. */
export function AbdmField({
  label,
  error,
  hint,
  provenance,
  prefix,
  suffix,
  className,
  id: idProp,
  ...props
}: AbdmFieldProps) {
  const generatedId = useId();
  const id = idProp ?? generatedId;
  const describedBy = [hint && `${id}-hint`, error && `${id}-error`]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <div className="flex flex-wrap items-center gap-2">
        <Label htmlFor={id}>{label}</Label>
        {provenance && (
          <ProvenanceHint
            provenance={provenance.provenance}
            field={provenance.field}
          />
        )}
      </div>
      <div className="flex items-stretch">
        {prefix && (
          <span className="flex items-center rounded-l-md border border-r-0 border-gray-300 bg-gray-50 px-3 text-sm text-gray-600">
            {prefix}
          </span>
        )}
        <Input
          id={id}
          autoComplete="off"
          spellCheck={false}
          aria-invalid={!!error}
          aria-describedby={describedBy || undefined}
          className={cn(prefix && "rounded-l-none", suffix && "rounded-r-none")}
          {...props}
        />
        {suffix && (
          <span className="flex items-center rounded-r-md border border-l-0 border-gray-300 bg-gray-50 px-3 text-sm text-gray-600">
            {suffix}
          </span>
        )}
      </div>
      {hint && (
        <p id={`${id}-hint`} className="text-xs text-gray-500">
          {hint}
        </p>
      )}
      {error && (
        <p id={`${id}-error`} className="text-sm text-red-500" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

