import { useMutation } from "@tanstack/react-query";
import { Loader2Icon, SendIcon } from "lucide-react";
import { SubmitEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbdmField } from "@/components/Abdm/AbdmField";
import {
  useAbhaFlow,
  usePrefilledFacts,
} from "@/components/Abdm/AbhaFlowContext";
import { AbhaOtpInput } from "@/components/Abdm/AbhaOtpInput";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import {
  abdmSilent,
  isValidMobile,
  provenanceFor,
} from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import {
  AbhaCreateVerified,
  AbhaOtpSent,
  AbhaProfile,
  AbhaTransactionProfile,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

/**
 * Verifies the communication mobile of a new ABHA when it differs from the
 * Aadhaar mobile. The ABHA already exists by now, so the step is optional and
 * never a dead end: the OTP can go to a different number, or the step can be
 * skipped and the ABHA keeps its Aadhaar-linked mobile.
 */
export function CreateMobileStep({
  created,
  mobile: initialMobile,
  otpSent: initialOtpSent,
  sendError,
}: {
  created: AbhaCreateVerified;
  mobile: string;
  otpSent: AbhaOtpSent | null;
  sendError?: unknown;
}) {
  const { t } = useTranslation();
  const { config, rememberFact, goTo, finish, restart } = useAbhaFlow();
  const prefilled = usePrefilledFacts();

  // The number the OTP in view was sent to.
  const [mobile, setMobile] = useState(initialMobile);
  const [otpSent, setOtpSent] = useState(initialOtpSent);
  const [otp, setOtp] = useState("");
  // Choosing the number is the only view until an OTP has been sent.
  const [isEditing, setIsEditing] = useState(!initialOtpSent);
  const [draft, setDraft] = useState(initialMobile);
  const [showErrors, setShowErrors] = useState(false);
  const [initialSendError, setInitialSendError] = useState(sendError);

  const proceed = (transactionId: string, profile: AbhaProfile) => {
    if (created.abha_address_required) {
      goTo({
        name: "address",
        transactionId,
        existingPatient: created.existing_patient,
        isNew: true,
      });
      return;
    }
    finish({
      transactionId,
      profile,
      existingPatient: created.existing_patient,
      isNew: true,
    });
  };

  const verifyMutation = useMutation({
    mutationFn: mutate(abdmApi.createMobileVerify, { silent: abdmSilent }),
    onSuccess: ({ transaction_id, profile }: AbhaTransactionProfile) =>
      proceed(transaction_id, profile),
  });

  const sendMutation = useMutation({
    mutationFn: mutate(abdmApi.createMobileOtp, { silent: abdmSilent }),
    onSuccess: (data: AbhaOtpSent, { mobile: sentTo }) => {
      rememberFact("mobile", sentTo);
      setMobile(sentTo);
