test("sends the mobile OTP to a different number when asked", async ({
  page,
}) => {
  mockAbhaCreation(mock);
  mock.on("POST", "abdm/abha/create/mobile/otp/", ({ body }) => {
    const isFirstNumber = body?.mobile === "9000000002";
    return {
      json: otpSent({
        transaction_id: "txn-create",
        masked_mobile: `******${String(body?.mobile).slice(-4)}`,
        // The first OTP was already resent once, and can be resent now.
        resend: isFirstNumber
          ? { available_in_seconds: 0, remaining: 1 }
          : { available_in_seconds: 60, remaining: 2 },
      }),
    };
  });
  await createAbhaUpToMobile(page);
  const step = page.getByTestId("abdm-step-create-mobile");
  const number = page.getByTestId("abdm-create-mobile-number");
  const resend = page.getByTestId("abdm-resend-otp");

  await test.step("Offer a different number while the OTP is awaited", async () => {
    await expect(page.getByTestId("abdm-otp-sent")).toContainText(
      "******0002",
    );
    await expect(resend).toBeEnabled();
    await expect(step).toContainText("1 resend left");
    await page.getByTestId("abdm-otp-input").fill("12");
    await page.getByTestId("abdm-create-mobile-change").click();
    await expect(number).toHaveValue("9000000002");
    await expect(number).toBeFocused();
  });

  await test.step("Accept only a valid, different number", async () => {
    await page.getByTestId("abdm-create-mobile-send").click();
    await expect(step).toContainText(
      "The OTP was already sent to this number. Enter a different number.",
    );
    await number.fill("5000000003");
    await expect(step).toContainText(
      "Enter a valid 10-digit mobile number starting with 6, 7, 8 or 9",
    );
    expect(mock.calls("POST", "abdm/abha/create/mobile/otp/")).toHaveLength(
      1,
    );
  });

  await test.step("Send a new OTP and restart its countdown", async () => {
    await number.fill("9000000003");
    await page.getByTestId("abdm-create-mobile-send").click();
    await expect(page.getByTestId("abdm-otp-sent")).toContainText(
      "******0003",
    );
    await expect(step).toContainText("An OTP was sent to +91 9000000003");
    expect(
      mock
        .calls("POST", "abdm/abha/create/mobile/otp/")
        .map((call) => call.body),
    ).toEqual([
      { transaction_id: "txn-create", mobile: "9000000002" },
      { transaction_id: "txn-create", mobile: "9000000003" },
    ]);
    await expect(page.getByTestId("abdm-otp-input")).toHaveValue("");
    await expect(resend).toBeDisabled();
    await expect(resend).toContainText(/Resend OTP in \d+s/);
    await expect(step).toContainText("2 resends left");
  });

  await test.step("Verify the new number, then choose the address", async () => {
    await page.getByTestId("abdm-otp-input").fill("654321");
    await page.getByTestId("abdm-create-mobile-submit").click();
    await chooseSuggestedAddress(page);
    expect(
      mock
        .calls("POST", "abdm/abha/create/mobile/verify/")
        .map((call) => call.body),
    ).toEqual([{ transaction_id: "txn-create", otp: "654321" }]);
    expect(mock.calls("POST", "abdm/abha/otp/resend/")).toHaveLength(0);
  });
});

