import { useMutation } from "@tanstack/react-query";
import { Loader2Icon, SendIcon } from "lucide-react";
import { SubmitEvent, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { AbdmErrorAlert } from "@/components/Abdm/AbdmErrorAlert";
import { AbdmField } from "@/components/Abdm/AbdmField";
import {
  useAbhaFlow,
  usePrefilledFacts,
} from "@/components/Abdm/AbhaFlowContext";
import { AbhaOtpInput } from "@/components/Abdm/AbhaOtpInput";
import { StepLayout } from "@/components/Abdm/steps/StepLayout";
import {
  abdmSilent,
  isValidMobile,
  provenanceFor,
} from "@/components/Abdm/utils";

import mutate from "@/Utils/request/mutate";
import {
  AbhaCreateVerified,
  AbhaOtpSent,
  AbhaProfile,
  AbhaTransactionProfile,
} from "@/types/abdm/abdm";
import abdmApi from "@/types/abdm/abdmApi";

/**
 * Verifies the communication mobile of a new ABHA when it differs from the
 * Aadhaar mobile. The ABHA already exists by now, so the step is optional and
 * never a dead end: the OTP can go to a different number, or the step can be
 * skipped and the ABHA keeps its Aadhaar-linked mobile.
 */
export function CreateMobileStep({
  created,
  mobile: initialMobile,
  otpSent: initialOtpSent,
  sendError,
}: {
  created: AbhaCreateVerified;
  mobile: string;
  otpSent: AbhaOtpSent | null;
  sendError?: unknown;
}) {
  const { t } = useTranslation();
  const { config, rememberFact, goTo, finish, restart } = useAbhaFlow();
  const prefilled = usePrefilledFacts();

  // The number the OTP in view was sent to.
  const [mobile, setMobile] = useState(initialMobile);
  const [otpSent, setOtpSent] = useState(initialOtpSent);
  const [otp, setOtp] = useState("");
  // Choosing the number is the only view until an OTP has been sent.
  const [isEditing, setIsEditing] = useState(!initialOtpSent);
  const [draft, setDraft] = useState(initialMobile);
  const [showErrors, setShowErrors] = useState(false);
  const [initialSendError, setInitialSendError] = useState(sendError);

  const proceed = (transactionId: string, profile: AbhaProfile) => {
    if (created.abha_address_required) {
      goTo({
        name: "address",
        transactionId,
        existingPatient: created.existing_patient,
        isNew: true,
      });
      return;
    }
    finish({
      transactionId,
      profile,
      existingPatient: created.existing_patient,
      isNew: true,
    });
  };

  const verifyMutation = useMutation({
    mutationFn: mutate(abdmApi.createMobileVerify, { silent: abdmSilent }),
    onSuccess: ({ transaction_id, profile }: AbhaTransactionProfile) =>
      proceed(transaction_id, profile),
  });

  const sendMutation = useMutation({
    mutationFn: mutate(abdmApi.createMobileOtp, { silent: abdmSilent }),
    onSuccess: (data: AbhaOtpSent, { mobile: sentTo }) => {
      rememberFact("mobile", sentTo);
      setMobile(sentTo);
      setOtp("");
      setOtpSent(data);
      setIsEditing(false);
      verifyMutation.reset();
    },
  });

  const isBusy = sendMutation.isPending || verifyMutation.isPending;
  const isOtpComplete = otp.length === config.otp.length;
  const draftError = !isValidMobile(draft)
    ? t("abdm_validation__mobile")
    : otpSent && draft === mobile
      ? t("abdm_create_mobile_same")
      : undefined;
  const sendFailure = sendMutation.error ?? initialSendError;

  const handleVerify = (event: SubmitEvent) => {
    event.preventDefault();
    if (!otpSent || !isOtpComplete || isBusy) return;
    verifyMutation.mutate({ transaction_id: otpSent.transaction_id, otp });
  };

  const handleSend = (event: SubmitEvent) => {
    event.preventDefault();
    setShowErrors(true);
    if (draftError || isBusy) return;
    setInitialSendError(undefined);
    sendMutation.mutate({
      transaction_id: created.transaction_id,
      mobile: draft,
    });
  };

  const startEditing = () => {
    setDraft(mobile);
    setShowErrors(false);
    verifyMutation.reset();
    setIsEditing(true);
  };

  const stopEditing = () => {
    setShowErrors(false);
    sendMutation.reset();
    setIsEditing(false);
  };

  return (
    <StepLayout
      title={t("abdm_verify_mobile_title")}
      description={
        otpSent && !isEditing
          ? t("abdm_verify_mobile_description", { mobile: `+91 ${mobile}` })
          : t("abdm_create_mobile_edit_description")
      }
      testId="abdm-step-create-mobile"
    >
      {otpSent && !isEditing ? (
        <form
          className="flex flex-col gap-4"
          onSubmit={handleVerify}
          noValidate
        >
          <AbhaOtpInput
            otpSent={otpSent}
            onOtpSentChange={setOtpSent}
            otpLength={config.otp.length}
            value={otp}
            onChange={(next) => {
              setOtp(next);
              if (verifyMutation.error) verifyMutation.reset();
            }}
            disabled={verifyMutation.isPending}
            onRestart={restart}
          />
          {verifyMutation.error && (
            <AbdmErrorAlert error={verifyMutation.error} onRestart={restart} />
          )}
          <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            <Button
              type="button"
              variant="outline"
              disabled={verifyMutation.isPending}
              onClick={startEditing}
              data-testid="abdm-create-mobile-change"
            >
              {t("abdm_use_different_number")}
            </Button>
            <Button
              type="submit"
              variant="primary"
              disabled={!isOtpComplete || verifyMutation.isPending}
              data-testid="abdm-create-mobile-submit"
            >
              {verifyMutation.isPending && (
                <Loader2Icon className="animate-spin" />
              )}
              {t("verify")}
            </Button>
          </div>
        </form>
      ) : (
        <form className="flex flex-col gap-4" onSubmit={handleSend} noValidate>
          <AbdmField
            label={t("abdm_communication_mobile")}
            prefix="+91"
            inputMode="numeric"
            maxLength={10}
            placeholder={t("abdm_mobile_placeholder")}
            value={draft}
            onChange={(event) => {
              setDraft(event.target.value.replace(/\D/g, "").slice(0, 10));
              setInitialSendError(undefined);
              sendMutation.reset();
            }}
            error={showErrors ? draftError : undefined}
            provenance={provenanceFor(prefilled.mobile, draft, "mobile")}
            // Focus the number only when the user asked to change it.
            autoFocus={!!otpSent}
            data-testid="abdm-create-mobile-number"
          />
          {sendFailure ? (
            <AbdmErrorAlert error={sendFailure} onRestart={restart} />
          ) : null}
          <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            {otpSent && (
              <Button
                type="button"
                variant="outline"
                disabled={sendMutation.isPending}
                onClick={stopEditing}
                data-testid="abdm-create-mobile-cancel"
              >
                {t("cancel")}
              </Button>
            )}
            <Button
              type="submit"
              variant="primary"
              disabled={sendMutation.isPending}
              data-testid="abdm-create-mobile-send"
            >
              {sendMutation.isPending ? (
                <Loader2Icon className="animate-spin" />
              ) : (
                <SendIcon />
              )}
              {t("abdm_send_otp")}
            </Button>
          </div>
        </form>
      )}

      <div className="flex flex-col gap-2 rounded-md bg-gray-50 p-3 sm:flex-row sm:items-center sm:justify-between">
        <p
          className="text-sm text-gray-600"
          data-testid="abdm-create-mobile-skip-hint"
        >
          {t("abdm_create_mobile_skip_hint")}
        </p>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="shrink-0 self-start sm:self-auto"
          disabled={isBusy}
          onClick={() => proceed(created.transaction_id, created.profile)}
          data-testid="abdm-create-mobile-skip"
        >
          {t("abdm_skip_for_now")}
        </Button>
      </div>
    </StepLayout>
  );
}

