   const draftError = !isValidMobile(draft)
     ? t("abdm_validation__mobile")
     : otpSent && draft === mobile
       ? t("abdm_create_mobile_same")
       : undefined;
   const sendFailure = sendMutation.error ?? initialSendError;

   const handleVerify = (event: SubmitEvent) => {
     event.preventDefault();
     if (!otpSent || !isOtpComplete || isBusy) return;
     verifyMutation.mutate({ transaction_id: otpSent.transaction_id, otp });
   };

   const handleSend = (event: SubmitEvent) => {
     event.preventDefault();
     setShowErrors(true);
     if (draftError || isBusy) return;
     setInitialSendError(undefined);
     sendMutation.mutate({
       transaction_id: created.transaction_id,
       mobile: draft,
     });
   };

   const startEditing = () => {
     setDraft(mobile);
     setShowErrors(false);
     verifyMutation.reset();
     setIsEditing(true);
   };

   const stopEditing = () => {
     setShowErrors(false);
     sendMutation.reset();
     setIsEditing(false);
   };

   return (
     <StepLayout
       title={t("abdm_verify_mobile_title")}
       description={
         otpSent && !isEditing
           ? t("abdm_verify_mobile_description", { mobile: `+91 ${mobile}` })
           : t("abdm_create_mobile_edit_description")
       }
       testId="abdm-step-create-mobile"
     >
       {otpSent && !isEditing ? (
         <form
           className="flex flex-col gap-4"
           onSubmit={handleVerify}
           noValidate
         >
           <AbhaOtpInput
             otpSent={otpSent}
             onOtpSentChange={setOtpSent}
             otpLength={config.otp.length}
             value={otp}
             onChange={(next) => {
               setOtp(next);
               if (verifyMutation.error) verifyMutation.reset();
             }}
             disabled={verifyMutation.isPending}
             onRestart={restart}
           />
           {verifyMutation.error && (
             <AbdmErrorAlert error={verifyMutation.error} onRestart={restart} />
           )}
           <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
             <Button
               type="button"
               variant="outline"
               disabled={verifyMutation.isPending}
               onClick={startEditing}
               data-testid="abdm-create-mobile-change"
             >
               {t("abdm_use_different_number")}
             </Button>
             <Button
               type="submit"
               variant="primary"
               disabled={!isOtpComplete || verifyMutation.isPending}
               data-testid="abdm-create-mobile-submit"
             >
               {verifyMutation.isPending && (
                 <Loader2Icon className="animate-spin" />
               )}
               {t("verify")}
             </Button>
           </div>
         </form>
       ) : (
         <form className="flex flex-col gap-4" onSubmit={handleSend} noValidate>
           <AbdmField
             label={t("abdm_communication_mobile")}
             prefix="+91"
             inputMode="numeric"
             maxLength={10}
             placeholder={t("abdm_mobile_placeholder")}
             value={draft}
             onChange={(event) => {
               setDraft(event.target.value.replace(/\D/g, "").slice(0, 10));
               setInitialSendError(undefined);
               sendMutation.reset();
             }}
             error={showErrors ? draftError : undefined}
             provenance={provenanceFor(prefilled.mobile, draft, "mobile")}
             // Focus the number only when the user asked to change it.
             autoFocus={!!otpSent}
             data-testid="abdm-create-mobile-number"
           />
           {sendFailure ? (
             <AbdmErrorAlert error={sendFailure} onRestart={restart} />
           ) : null}
           <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
             {otpSent && (
               <Button
                 type="button"
                 variant="outline"
                 disabled={sendMutation.isPending}
                 onClick={stopEditing}
                 data-testid="abdm-create-mobile-cancel"
               >
                 {t("cancel")}
               </Button>
             )}
             <Button
               type="submit"
               variant="primary"
               disabled={sendMutation.isPending}
               data-testid="abdm-create-mobile-send"
             >
               {sendMutation.isPending ? (
                 <Loader2Icon className="animate-spin" />
               ) : (
                 <SendIcon />
               )}
               {t("abdm_send_otp")}
             </Button>
           </div>
         </form>
       )}

       <div className="flex flex-col gap-2 rounded-md bg-gray-50 p-3 sm:flex-row sm:items-center sm:justify-between">
         <p
           className="text-sm text-gray-600"
           data-testid="abdm-create-mobile-skip-hint"
         >
           {t("abdm_create_mobile_skip_hint")}
         </p>
         <Button
           type="button"
           variant="outline"
           size="sm"
           className="shrink-0 self-start sm:self-auto"
           disabled={isBusy}
           onClick={() => proceed(created.transaction_id, created.profile)}
           data-testid="abdm-create-mobile-skip"
         >
           {t("abdm_skip_for_now")}
         </Button>
       </div>
     </StepLayout>
   );
 }

