  "abha_linked_to_other_patient",
  "patient_already_linked",
  "creation_method_not_allowed",
  "abha_not_found",
  "transaction_not_found",
  "profile_share_not_found",
  "resend_too_soon",
  "resend_limit_reached",
  "rate_limited",
  "abdm_unavailable",
  "abdm_error",
  "abdm_session_expired",
  "abdm_disabled",
];

/** "Try again in 4 minutes" / "Try again in 30 seconds". */
function formatRetryAfter(t: TFunction, seconds: number) {
  return seconds >= 60
    ? t("abdm_try_again_in_minutes", { count: Math.ceil(seconds / 60) })
    : t("abdm_try_again_in_seconds", { count: Math.max(1, seconds) });
}

export function getAbdmErrorMessage(t: TFunction, error: unknown) {
  const abdmError = getAbdmError(error);
  if (!abdmError) {
    // CARE's own permission checks answer with 403 {"detail": ...}.
    if (error instanceof HTTPError && error.status === 403) {
      return { title: t("abdm_error__permission_denied") };
    }
    return { title: t("abdm_error__generic") };
  }
  const title = KNOWN_ERROR_TYPES.includes(abdmError.type)
    ? t(`abdm_error__${abdmError.type}`)
    : t("abdm_error__generic");
