// real backend on :9100 through the dev server on :4100. Read-only by construction:
// - every API write is aborted, except logging in and refreshing the token;
// - ABDM GETs are limited to the config and the facility's shares (list and by id);
// - nothing can send an OTP, create a patient or link an ABHA.
const WT = "/Users/jacob/copilot-worktrees/care_fe/jacobjeevan-expert-doodle";
const { chromium, expect } = require(WT + "/node_modules/@playwright/test");
