const OTHER_FAC = "d53f2a67-894b-450d-a633-de9ba1e9c9b9";
const SEEDED_SHARE = "aeed3c31-4331-4f02-9bb8-1d405192c49c";
const RANDOM_SHARE = "00000000-0000-4000-8000-" + Date.now().toString(16).padStart(12, "0").slice(-12);

const results = [];
async function check(name, fn) {
  try {
    const detail = await fn();
    results.push(true);
    console.log(`PASS ${name}${detail ? " — " + detail : ""}`);
  } catch (e) {
    results.push(false);
    console.log(`FAIL ${name} — ${(e.message || String(e)).split("\n").slice(0, 4).join(" | ")}`);
  }
}

async function fencedPage(browser) {
  const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });
  const calls = [];
  const blocked = [];
  page.on("pageerror", (e) => calls.push({ pageError: e.message }));
  await page.route(/\/api\/v1\//, async (route) => {
    const req = route.request();
    const path = new URL(req.url()).pathname.replace(/^\/api\/v1\//, "");
    const method = req.method();
    const isAbdm = /^(abdm\/|patient\/[^/]+\/abha\/|facility\/[^/]+\/abdm\/)/.test(path);
    const ok =
      (method === "POST" && /^auth\/(login|token\/refresh)\/$/.test(path)) ||
      (method === "GET" && !isAbdm) ||
      (method === "GET" && path === "abdm/config/") ||
      (method === "GET" && /^facility\/[^/]+\/abdm\/shares\/([^/]+\/)?$/.test(path));
    if (!ok) {
      blocked.push(`${method} ${path}`);
      return route.abort();
    }
    const response = await route.fetch();
    if (isAbdm) {
      let json = null;
      try { json = await response.json(); } catch { json = null; }
      calls.push({ method, path, query: new URL(req.url()).search, status: response.status(), json });
    }
    return route.fulfill({ response });
  });
  return { page, calls, blocked };
}

async function login(page, username, password) {
  await page.goto(`${BASE}/login`);
  await page.getByRole("textbox", { name: /username/i }).fill(username);
  await page.getByLabel(/password/i).fill(password);
  await page.getByRole("button", { name: /login/i }).click();
  await page.waitForURL((u) => !u.pathname.includes("login"), { timeout: 30000 });
}

const shareCalls = (calls, facility, share) =>
  calls.filter((c) => c.path === `facility/${facility}/abdm/shares/${share}/`);
const listCalls = (calls, facility) =>
  calls.filter((c) => c.path === `facility/${facility}/abdm/shares/`);

(async () => {
  const browser = await chromium.launch();
  const admin = await fencedPage(browser);
  const { page } = admin;

  await check("login as admin", () => login(page, "admin", "admin"));

  await check("seeded share loads by id and fills the share card", async () => {
    await page.goto(`${BASE}/facility/${SEEDED_FAC}/patient/create?profile_share=${SEEDED_SHARE}`);
    const share = page.getByTestId("abdm-profile-share");
    await expect(share.getByTestId("abha-profile-card")).toBeVisible({ timeout: 30000 });
    const [call] = shareCalls(admin.calls, SEEDED_FAC, SEEDED_SHARE);
    if (!call || call.status !== 200) throw new Error(JSON.stringify(call));
    if (call.query) throw new Error(`unexpected query ${call.query}`);
    if (listCalls(admin.calls, SEEDED_FAC).length) throw new Error("the share list was fetched");
    await page.screenshot({ path: SHOTS + "/live-share-1-by-id.png" });
    const action = (await share.getByTestId("abdm-use-for-registration").count())
      ? "offers 'Use for registration'"
      : "shows the linked patient";
    return `200, status ${call.json.status}, token ${call.json.token_number}, ${(await share.locator("p").first().innerText()).trim()}; ${action}`;
  });

  await check("the same share through another facility is 'no longer available'", async () => {
    await page.goto(`${BASE}/facility/${OTHER_FAC}/patient/create?profile_share=${SEEDED_SHARE}`);
    await expect(page.getByTestId("abdm-profile-share-not-found")).toHaveText(
      "This ABHA share is no longer available.", { timeout: 30000 },
    );
    const [call] = shareCalls(admin.calls, OTHER_FAC, SEEDED_SHARE);
    if (!call || call.status !== 404) throw new Error(JSON.stringify(call));
    await page.screenshot({ path: SHOTS + "/live-share-2-other-facility.png" });
    return `404 ${call.json?.errors?.[0]?.type}`;
  });

  await check("an unknown share id is 'no longer available'", async () => {
    await page.goto(`${BASE}/facility/${SEEDED_FAC}/patient/create?profile_share=${RANDOM_SHARE}`);
    await expect(page.getByTestId("abdm-profile-share-not-found")).toBeVisible({ timeout: 30000 });
    const [call] = shareCalls(admin.calls, SEEDED_FAC, RANDOM_SHARE);
    if (!call || call.status !== 404) throw new Error(JSON.stringify(call));
    return `404 ${call.json?.errors?.[0]?.type}`;
  });

  await check("a share_date left in the link is ignored", async () => {
    await page.goto(`${BASE}/facility/${SEEDED_FAC}/patient/create?profile_share=${SEEDED_SHARE}&share_date=2026-01-01`);
    await expect(page.getByTestId("abdm-profile-share").getByTestId("abha-profile-card")).toBeVisible({ timeout: 30000 });
    const call = shareCalls(admin.calls, SEEDED_FAC, SEEDED_SHARE).at(-1);
    if (!call || call.status !== 200 || call.query) throw new Error(JSON.stringify(call));
  });

  const doctor = await fencedPage(browser);
  await check("login as care-doctor", () => login(doctor.page, "care-doctor", "Ohcn@123"));
  await check("care-doctor (no queue permission) is told they lack access", async () => {
    await doctor.page.goto(`${BASE}/facility/${SEEDED_FAC}/patient/create?profile_share=${SEEDED_SHARE}`);
    const share = doctor.page.getByTestId("abdm-profile-share");
    await expect(share.getByTestId("abdm-error")).toHaveText(
      "You don't have access to this. Ask your facility administrator for access.", { timeout: 30000 },
    );
    const [call] = shareCalls(doctor.calls, SEEDED_FAC, SEEDED_SHARE);
    if (!call || call.status !== 403) throw new Error(JSON.stringify(call));
    await doctor.page.screenshot({ path: SHOTS + "/live-share-3-no-permission.png" });
    return `403 ${JSON.stringify(call.json)}`;
  });

  const pageErrors = [...admin.calls, ...doctor.calls].filter((c) => c.pageError);
  console.log(`blocked writes: ${JSON.stringify([...admin.blocked, ...doctor.blocked])}`);
  console.log(`page errors: ${pageErrors.length}`);
  console.log(`${results.filter(Boolean).length}/${results.length} passed`);
  await browser.close();
})();

