+    );
+    const [call] = shareCalls(doctor.calls, SEEDED_FAC, SEEDED_SHARE);
+    if (!call || call.status !== 403) throw new Error(JSON.stringify(call));
+    await doctor.page.screenshot({ path: SHOTS + "/live-share-3-no-permission.png" });
+    return `403 ${JSON.stringify(call.json)}`;
+  });
+
